export enum UserRole {
  STUDENT = 'STUDENT',
  CLUB_ADMIN = 'CLUB_ADMIN',
  COLLEGE_ADMIN = 'COLLEGE_ADMIN'
}

export enum EventStatus {
  PENDING = 'PENDING',
  APPROVED = 'APPROVED',
  REJECTED = 'REJECTED',
  COMPLETED = 'COMPLETED'
}

export interface User {
  id: string;
  name: string;
  role: UserRole;
  avatar?: string;
  clubId?: string; // If club admin
}

export interface Venue {
  id: string;
  name: string;
  capacity: number;
  features: string[];
}

export interface Event {
  id: string;
  title: string;
  description: string;
  organizer: string;
  clubId: string;
  date: string;
  time: string;
  venueId: string;
  status: EventStatus;
  capacity: number;
  registeredCount: number;
  image?: string;
  tags: string[];
  price: number; // 0 for free
  feedback?: Feedback[];
}

export interface Feedback {
  userId: string;
  rating: number;
  comment: string;
}

export interface Proposal {
  title: string;
  description: string;
  date: string;
  time: string;
  venueId: string;
  capacity: number;
  budget: number;
}

import { GoogleGenAI } from "@google/genai";

// Ideally this comes from process.env.API_KEY, but for this demo context:
// We will assume process.env.API_KEY is available in the environment.
// In a real app, never expose keys on the client if not using a proxy or strictly limited keys.
const apiKey = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey });

export const generateEventContent = async (topic: string, type: 'description' | 'tagline' | 'poster_idea') => {
  if (!apiKey) {
    console.warn("API Key is missing for Gemini Service");
    return "AI generation unavailable (Missing API Key).";
  }

  const model = "gemini-3-flash-preview";
  let prompt = "";

  if (type === 'description') {
    prompt = `Write a compelling, professional, yet exciting 2-sentence description for a college event about: "${topic}". Keep it under 50 words.`;
  } else if (type === 'tagline') {
    prompt = `Write a catchy, short tagline for a college event about: "${topic}". Max 10 words.`;
  } else if (type === 'poster_idea') {
    prompt = `Describe a minimalist, black and white abstract geometric poster design concept for an event about: "${topic}".`;
  }

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
    });
    return response.text?.trim() || "Could not generate content.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error generating content. Please try again.";
  }
};

