import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import { UserRole, EventStatus, Event, User, Venue } from './types';
import { INITIAL_EVENTS, MOCK_USERS, MOCK_VENUES } from './constants';
import { generateEventContent } from './services/geminiService';
import { 
  Calendar, 
  MapPin, 
  Clock, 
  Users, 
  Check, 
  X, 
  Search, 
  Loader2, 
  Sparkles, 
  AlertCircle,
  TrendingUp,
  DollarSign
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';

// --- Sub-components placed here for single-file XML requirement simplicity in prompt context ---
// In a real project, these would be in components/

const StatusBadge = ({ status }: { status: EventStatus }) => {
  const styles = {
    [EventStatus.APPROVED]: 'bg-black text-white border border-black',
    [EventStatus.PENDING]: 'bg-white text-black border border-gray-300 border-dashed',
    [EventStatus.REJECTED]: 'bg-gray-200 text-gray-500 border border-transparent line-through',
    [EventStatus.COMPLETED]: 'bg-gray-100 text-gray-800 border border-gray-200',
  };
  return (
    <span className={`px-2 py-1 text-xs font-bold uppercase tracking-wider rounded-sm ${styles[status]}`}>
      {status}
    </span>
  );
};

const EventCard = ({ event, onRegister, isRegistered, isAdminView, onApprove, onReject }: any) => {
  return (
    <div className="bg-white border border-gray-200 shadow-sm hover:shadow-lg transition-all duration-300 flex flex-col h-full group">
      <div className="h-48 overflow-hidden relative bg-gray-100">
        <img 
          src={event.image} 
          alt={event.title} 
          className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500"
        />
        <div className="absolute top-2 right-2">
            <StatusBadge status={event.status} />
        </div>
        {event.price > 0 && (
           <div className="absolute bottom-2 right-2 bg-black text-white px-2 py-1 text-xs font-bold">
             ₹{event.price}
           </div>
        )}
      </div>
      <div className="p-5 flex-1 flex flex-col">
        <div className="mb-2 text-xs font-bold text-gray-400 uppercase tracking-widest">{event.organizer}</div>
        <h3 className="text-xl font-bold mb-2 leading-tight">{event.title}</h3>
        <p className="text-gray-500 text-sm mb-4 line-clamp-2">{event.description}</p>

        <div className="space-y-2 mt-auto text-sm text-gray-600">
          <div className="flex items-center">
            <Calendar size={14} className="mr-2 text-black" />
            {event.date}
          </div>
          <div className="flex items-center">
            <Clock size={14} className="mr-2 text-black" />
            {event.time}
          </div>
          <div className="flex items-center">
            <MapPin size={14} className="mr-2 text-black" />
            {MOCK_VENUES.find((v:any) => v.id === event.venueId)?.name || 'TBD'}
          </div>
        </div>
      </div>

      <div className="p-5 pt-0 border-t border-gray-100 mt-4">
        {isAdminView ? (
          event.status === EventStatus.PENDING ? (
            <div className="flex space-x-2 pt-4">
              <button onClick={() => onApprove(event.id)} className="flex-1 bg-black text-white py-2 text-sm font-bold hover:bg-gray-800 transition">Approve</button>
              <button onClick={() => onReject(event.id)} className="flex-1 bg-white border border-black text-black py-2 text-sm font-bold hover:bg-gray-50 transition">Reject</button>
            </div>
          ) : (
            <div className="pt-4 text-center text-sm font-medium text-gray-400">
              {event.status === EventStatus.APPROVED ? 'Event Active' : 'Event Closed'}
            </div>
          )
        ) : (
          <button 
            onClick={() => onRegister(event.id)}
            disabled={isRegistered || event.status !== EventStatus.APPROVED}
            className={`w-full py-3 text-sm font-bold uppercase tracking-wider transition-colors ${
              isRegistered 
                ? 'bg-gray-100 text-gray-400 cursor-not-allowed' 
                : event.status !== EventStatus.APPROVED 
                  ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
                  : 'bg-black text-white hover:bg-gray-800'
            }`}
          >
            {isRegistered ? 'Registered' : event.status !== EventStatus.APPROVED ? 'Coming Soon' : 'One-Click Register'}
          </button>
        )}
      </div>
    </div>
  );
};

// --- Main App Component ---

const App: React.FC = () => {
