export default App;

export enum UserRole {
  STUDENT = 'STUDENT',
  CLUB_ADMIN = 'CLUB_ADMIN',
  COLLEGE_ADMIN = 'COLLEGE_ADMIN'
}

export enum EventStatus {
  PENDING = 'PENDING',
  APPROVED = 'APPROVED',
  REJECTED = 'REJECTED',
  COMPLETED = 'COMPLETED'
}

export interface User {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  avatar?: string;
  clubId?: string; // If club admin
  bio?: string;
  joinDate?: string;
}

export interface Club {
  id: string;
  name: string;
  description: string;
  logo: string;
  banner: string;
  adminId: string;
  memberCount: number;
}

export interface Venue {
  id: string;
  name: string;
  capacity: number;
  features: string[];
}

export interface Event {
  id: string;
  title: string;
  description: string;
  organizer: string;
  clubId: string;
  date: string;
  time: string;
  venueId: string;
  status: EventStatus;
  capacity: number;
  registeredCount: number;
  image?: string;
  tags: string[];
  price: number; // 0 for free
  feedback?: Feedback[];
}

export interface Feedback {
  userId: string;
  rating: number;
  comment: string;
}

export interface Proposal {
  title: string;
  description: string;
  date: string;
  time: string;
  venueId: string;
  capacity: number;
  budget: number;
}

