import { User, Event, Club, Post, Venue, UserRole, VolunteerApplication, VolunteerStatus } from '../types';
import { MOCK_USERS, INITIAL_EVENTS, MOCK_CLUBS, MOCK_POSTS, MOCK_VENUES } from '../constants';

const DELAY = 800; // Simulated network latency in ms

// Helper to simulate network delay
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// LocalStorage Keys
const KEYS = {
  USERS: 'clix_users',
  EVENTS: 'clix_events',
  CLUBS: 'clix_clubs',
  POSTS: 'clix_posts',
  VENUES: 'clix_venues',
  VOLUNTEERS: 'clix_volunteers'
};

// Initialize LocalStorage with seed data if empty
const initializeDB = () => {
  if (typeof window !== 'undefined') {
    if (!localStorage.getItem(KEYS.USERS)) localStorage.setItem(KEYS.USERS, JSON.stringify(MOCK_USERS));
    if (!localStorage.getItem(KEYS.EVENTS)) localStorage.setItem(KEYS.EVENTS, JSON.stringify(INITIAL_EVENTS));
    if (!localStorage.getItem(KEYS.CLUBS)) localStorage.setItem(KEYS.CLUBS, JSON.stringify(MOCK_CLUBS));
    if (!localStorage.getItem(KEYS.POSTS)) localStorage.setItem(KEYS.POSTS, JSON.stringify(MOCK_POSTS));
    if (!localStorage.getItem(KEYS.VENUES)) localStorage.setItem(KEYS.VENUES, JSON.stringify(MOCK_VENUES));
    if (!localStorage.getItem(KEYS.VOLUNTEERS)) localStorage.setItem(KEYS.VOLUNTEERS, JSON.stringify([]));
  }
};

initializeDB();

// Generic Helpers
const get = <T>(key: string): T => {
  if (typeof window === 'undefined') return [] as T;
  return JSON.parse(localStorage.getItem(key) || '[]');
};
const set = (key: string, data: any) => {
  if (typeof window !== 'undefined') {
    localStorage.setItem(key, JSON.stringify(data));
  }
};

export const api = {
  auth: {
    login: async (email: string, password: string): Promise<User> => {
      await delay(DELAY);
      const users = get<User[]>(KEYS.USERS);
      // In a real app, verify password. Here, just find email (case-insensitive)
      const user = users.find(u => u.email.toLowerCase() === email.toLowerCase());
      if (!user) throw new Error('Invalid credentials');
      return user;
    },
    signup: async (user: User): Promise<User> => {
      await delay(DELAY);
      const users = get<User[]>(KEYS.USERS);
      if (users.find(u => u.email === user.email)) throw new Error('User already exists');
      users.push(user);
      set(KEYS.USERS, users);
      return user;
    },
    // Demo helper to switch roles
    loginAsRole: async (role: UserRole): Promise<User> => {
      await delay(DELAY);
      const users = get<User[]>(KEYS.USERS);
      const user = users.find(u => u.role === role);
      if (!user) throw new Error(`No user found with role ${role}`);
      return user;
    },
    updateProfile: async (user: User): Promise<User> => {
        await delay(DELAY);
        const users = get<User[]>(KEYS.USERS);
        const index = users.findIndex(u => u.id === user.id);
        if (index !== -1) {
            users[index] = user;
            set(KEYS.USERS, users);
            return user;
        }
        throw new Error("User not found");
    }
  },
  events: {
    list: async (): Promise<Event[]> => {
      await delay(DELAY);
      return get<Event[]>(KEYS.EVENTS);
    },
    create: async (event: Event): Promise<Event> => {
      await delay(DELAY);
      const events = get<Event[]>(KEYS.EVENTS);
      events.push(event);
      set(KEYS.EVENTS, events);
      return event;
    },
    updateStatus: async (eventId: string, status: any): Promise<Event> => {
       await delay(DELAY);
       const events = get<Event[]>(KEYS.EVENTS);
       const index = events.findIndex(e => e.id === eventId);
       if (index !== -1) {
         events[index].status = status;
         set(KEYS.EVENTS, events);
         return events[index];
       }
       throw new Error("Event not found");
    },
    register: async (eventId: string, userId: string): Promise<void> => {
        await delay(DELAY);
        const events = get<Event[]>(KEYS.EVENTS);
        const event = events.find(e => e.id === eventId);
        if (event) {
            event.registeredCount += 1;
            // In a real DB, we would also add to a registrations table
            set(KEYS.EVENTS, events);
        }
    }
  },
  clubs: {
    list: async (): Promise<Club[]> => {
      await delay(DELAY);
      return get<Club[]>(KEYS.CLUBS);
    },
    join: async (clubId: string, userId: string): Promise<User> => {
        await delay(DELAY);
        // Update User
        const users = get<User[]>(KEYS.USERS);
        const userIndex = users.findIndex(u => u.id === userId);
        if (userIndex === -1) throw new Error("User not found");

        const user = users[userIndex];
        if (!user.joinedClubIds) user.joinedClubIds = [];
        if (!user.joinedClubIds.includes(clubId)) {
            user.joinedClubIds.push(clubId);
        }
        users[userIndex] = user;
        set(KEYS.USERS, users);

        // Update Club Count
        const clubs = get<Club[]>(KEYS.CLUBS);
        const clubIndex = clubs.findIndex(c => c.id === clubId);
        if (clubIndex !== -1) {
            clubs[clubIndex].memberCount += 1;
            set(KEYS.CLUBS, clubs);
        }

        return user;
    },
    leave: async (clubId: string, userId: string): Promise<User> => {
        await delay(DELAY);
        const users = get<User[]>(KEYS.USERS);
        const userIndex = users.findIndex(u => u.id === userId);
        if (userIndex === -1) throw new Error("User not found");

        const user = users[userIndex];
        if (user.joinedClubIds) {
            user.joinedClubIds = user.joinedClubIds.filter(id => id !== clubId);
        }
        users[userIndex] = user;
        set(KEYS.USERS, users);

         // Update Club Count
         const clubs = get<Club[]>(KEYS.CLUBS);
         const clubIndex = clubs.findIndex(c => c.id === clubId);
         if (clubIndex !== -1) {
             clubs[clubIndex].memberCount = Math.max(0, clubs[clubIndex].memberCount - 1);
             set(KEYS.CLUBS, clubs);
         }

        return user;
    }
  },
  posts: {
    list: async (clubId: string): Promise<Post[]> => {
      await delay(DELAY);
      const posts = get<Post[]>(KEYS.POSTS);
      // Filter by club and sort by newest
      return posts
        .filter(p => p.clubId === clubId)
        .reverse(); // Simple reverse for "newest first" based on insertion
    },
    create: async (post: Post): Promise<Post> => {
        await delay(DELAY);
        const posts = get<Post[]>(KEYS.POSTS);
        posts.push(post);
        set(KEYS.POSTS, posts);
        return post;
    }
  },
  venues: {
      list: async (): Promise<Venue[]> => {
          await delay(200); // Venues load faster
          return get<Venue[]>(KEYS.VENUES);
      }
  },
  volunteers: {
    apply: async (application: VolunteerApplication): Promise<VolunteerApplication> => {
        await delay(DELAY);
        const apps = get<VolunteerApplication[]>(KEYS.VOLUNTEERS);
        // Check if already applied
        if (apps.find(a => a.eventId === application.eventId && a.userId === application.userId)) {
             throw new Error("Already applied");
        }
        apps.push(application);
        set(KEYS.VOLUNTEERS, apps);
        return application;
    },
    listByEvent: async (eventId: string): Promise<VolunteerApplication[]> => {
        await delay(DELAY);
        const apps = get<VolunteerApplication[]>(KEYS.VOLUNTEERS);
        return apps.filter(a => a.eventId === eventId);
    },
    listByUser: async (userId: string): Promise<VolunteerApplication[]> => {
        await delay(DELAY);
        const apps = get<VolunteerApplication[]>(KEYS.VOLUNTEERS);
        return apps.filter(a => a.userId === userId);
    },
    updateStatus: async (appId: string, status: VolunteerStatus): Promise<void> => {
        await delay(DELAY);
        const apps = get<VolunteerApplication[]>(KEYS.VOLUNTEERS);
        const index = apps.findIndex(a => a.id === appId);
        if (index !== -1) {
            apps[index].status = status;
            set(KEYS.VOLUNTEERS, apps);
        }
    }
  }
};

