// --- Club Detail & Discussion Components ---

const ClubDetailView = ({ club, user, onJoin, onLeave, events, onAddPost, onBack, onVolunteer, myVolunteerApps }: any) => {
  const [activeTab, setActiveTab] = useState('overview');
  const [newPostContent, setNewPostContent] = useState('');
  const [loadingPosts, setLoadingPosts] = useState(false);
  const [loadingJoin, setLoadingJoin] = useState(false);
  const [posts, setPosts] = useState<Post[]>([]);
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);

  const isMember = user.joinedClubIds?.includes(club.id);

  // Fetch posts/announcements when tab is active
  useEffect(() => {
    if (activeTab === 'discussions') {
        setLoadingPosts(true);
        api.posts.list(club.id).then(fetchedPosts => {
            setPosts(fetchedPosts);
            setLoadingPosts(false);
        });
    }
    if (activeTab === 'overview') {
        api.announcements.list(club.id).then(setAnnouncements);
    }
  }, [activeTab, club.id]);

  const handlePostSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newPostContent.trim()) {
      onAddPost(newPostContent);
      // Optimistic update
      const tempPost: Post = {
          id: 'temp', clubId: club.id, userId: user.id, userName: user.name, userAvatar: user.avatar || '',
          content: newPostContent, timestamp: 'Just now', likes: 0
      };
      setPosts([tempPost, ...posts]);
      setNewPostContent('');
    }
  };

  const handleJoinLeave = async (action: 'join' | 'leave') => {
      setLoadingJoin(true);
      if (action === 'join') await onJoin(club.id);
      else await onLeave(club.id);
      setLoadingJoin(false);
  };

  const filteredEvents = events.filter((e: Event) => e.clubId === club.id && e.status === EventStatus.APPROVED);

  return (
    <div className="animate-in fade-in duration-500">
      <button onClick={onBack} className="flex items-center gap-2 text-gray-500 hover:text-black font-bold mb-6">
        <ArrowLeft size={20} /> Back to Clubs
      </button>

      {/* Header */}
      <div className="bg-white border-2 border-black p-8 mb-8 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-32 h-32 bg-yellow-400 rotate-45 translate-x-16 -translate-y-16"></div>
        <div className="flex flex-col md:flex-row items-center md:items-start gap-6 relative z-10">
          <img src={club.logo} alt={club.name} className="w-24 h-24 rounded-full border-4 border-black bg-white" />
          <div className="flex-1 text-center md:text-left">
            <h1 className="text-4xl font-black mb-2">{club.name}</h1>
            <p className="text-gray-600 font-medium max-w-2xl">{club.description}</p>
            <div className="flex items-center justify-center md:justify-start gap-4 mt-4">
              <span className="bg-gray-100 px-3 py-1 text-xs font-bold uppercase tracking-wider rounded-full">{club.memberCount} Members</span>
              {isMember && <span className="bg-green-100 text-green-700 px-3 py-1 text-xs font-bold uppercase tracking-wider rounded-full border border-green-200">Member</span>}
            </div>
          </div>
          <div className="mt-4 md:mt-0">
             {isMember ? (
               <button 
                onClick={() => handleJoinLeave('leave')}
                disabled={loadingJoin}
                className="bg-white text-red-500 border-2 border-red-500 px-6 py-3 font-bold uppercase tracking-widest hover:bg-red-50 transition shadow-[4px_4px_0px_#ef4444] flex items-center gap-2"
               >
                 {loadingJoin ? <Loader2 className="animate-spin" /> : 'Leave Club'}
               </button>
             ) : (
               <button 
                onClick={() => handleJoinLeave('join')}
                disabled={loadingJoin}
                className="bg-yellow-400 text-black border-2 border-black px-8 py-3 font-black uppercase tracking-widest hover:bg-yellow-500 transition shadow-[4px_4px_0px_#000] flex items-center gap-2"
               >
                 {loadingJoin ? <Loader2 className="animate-spin" /> : 'Join Club'}
               </button>
             )}
          </div>
        </div>
      </div>

      {/* Navigation Tabs */}
      <div className="flex border-b-2 border-black mb-8 overflow-x-auto">
        {['overview', 'events', 'discussions'].map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-8 py-4 font-black uppercase tracking-widest text-sm whitespace-nowrap transition-colors ${
              activeTab === tab ? 'bg-black text-yellow-400' : 'text-gray-400 hover:text-black'
            }`}
          >
            {tab}
          </button>
        ))}
      </div>

      {/* Content */}
      <div className="min-h-[400px]">
        {activeTab === 'overview' && (
           <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="bg-white p-6 border-2 border-gray-200">
                <h3 className="text-xl font-black mb-4 flex items-center gap-2"><Megaphone size={20} className="text-yellow-500"/> Announcements</h3>
                {announcements.length === 0 ? (
                    <p className="text-gray-600 italic">No recent announcements from the club admin.</p>
                ) : (
                    <ul className="space-y-4">
                        {announcements.map(ann => (
                            <li key={ann.id} className="bg-yellow-50 p-4 border border-yellow-200 rounded">
                                <p className="text-black font-medium">{ann.content}</p>
                                <span className="text-xs text-gray-500 font-bold uppercase mt-2 block">{new Date(ann.date).toLocaleDateString()}</span>
                            </li>
                        ))}
                    </ul>
                )}
              </div>
              <div className="bg-white p-6 border-2 border-gray-200">
                <h3 className="text-xl font-black mb-4 flex items-center gap-2"><FileText size={20} className="text-yellow-500"/> Resources</h3>
                <ul className="space-y-3">
                  <li className="flex items-center gap-2 text-sm font-bold underline cursor-pointer hover:text-yellow-600">Club Constitution.pdf</li>
                  <li className="flex items-center gap-2 text-sm font-bold underline cursor-pointer hover:text-yellow-600">Meeting Minutes - May.docx</li>
                </ul>
              </div>
           </div>
        )}

        {activeTab === 'events' && (
          <div>
            {filteredEvents.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredEvents.map((event: Event) => (
                  <EventCard 
                    key={event.id} 
                    event={event} 
                    isRegistered={false} 
                    onRegister={() => {}} 
                    isAdminView={false} 
                    onVolunteer={onVolunteer}
                    volunteerStatus={myVolunteerApps.find((a: any) => a.eventId === event.id)?.status}
                  />
                ))}
              </div>
            ) : (
              <div className="text-center py-10 text-gray-500 font-bold">No upcoming events found for this club.</div>
            )}
          </div>
        )}

        {activeTab === 'discussions' && (
          <div className="max-w-3xl mx-auto">
            {!isMember ? (
              <div className="text-center py-12 bg-gray-50 border-2 border-dashed border-gray-300 rounded-lg">
                <Lock size={48} className="mx-auto text-gray-300 mb-4" />
                <h3 className="text-xl font-bold mb-2">Members Only</h3>
                <p className="text-gray-500 mb-6">Join the club to participate in discussions and view member content.</p>
                <button 
                  onClick={() => handleJoinLeave('join')}
                  className="bg-black text-white px-6 py-2 font-bold uppercase tracking-widest hover:bg-gray-800"
                >
                  Join Now
                </button>
              </div>
            ) : (
              <>
                 <div className="bg-white border-2 border-black p-4 mb-8 shadow-[4px_4px_0px_#000]">
                    <form onSubmit={handlePostSubmit} className="flex gap-4">
                      <img src={user.avatar} className="w-10 h-10 rounded-full border border-black bg-gray-100" />
                      <div className="flex-1">
                        <textarea 
                          className="w-full p-3 border-2 border-gray-200 focus:border-black focus:outline-none resize-none font-medium" 
                          rows={2}
                          placeholder="Start a discussion..."
                          value={newPostContent}
                          onChange={(e) => setNewPostContent(e.target.value)}
                        />
                        <div className="flex justify-end mt-2">
                           <button type="submit" className="bg-yellow-400 text-black px-6 py-2 font-bold uppercase tracking-wider text-xs border-2 border-black hover:bg-yellow-500 flex items-center gap-2">
                              Post <Send size={14} />
                           </button>
                        </div>
                      </div>
                    </form>
                 </div>

                 {loadingPosts ? (
                     <div className="flex justify-center py-10"><Loader2 className="animate-spin text-gray-400" size={32}/></div>
                 ) : (
                    <div className="space-y-6">
                        {posts.length > 0 ? (
                        posts.map((post: Post) => (
                            <div key={post.id} className="flex gap-4 animate-in slide-in-from-bottom-2">
                            <img src={post.userAvatar} className="w-10 h-10 rounded-full border border-black bg-gray-100" />
                            <div className="flex-1">
                                <div className="bg-white border border-gray-200 p-4 rounded-lg rounded-tl-none shadow-sm">
                                    <div className="flex justify-between items-start mb-2">
                                        <span className="font-bold text-sm">{post.userName}</span>
                                        <span className="text-xs text-gray-400">{post.timestamp}</span>
                                    </div>
                                    <p className="text-gray-700 text-sm leading-relaxed">{post.content}</p>
                                </div>
                                <div className="flex gap-4 mt-1 ml-2">
                                    <button className="text-xs font-bold text-gray-400 hover:text-red-500 flex items-center gap-1 transition-colors">
                                    <Heart size={12} /> {post.likes} Likes
                                    </button>
                                    <button className="text-xs font-bold text-gray-400 hover:text-black flex items-center gap-1 transition-colors">
                                    Reply
                                    </button>
                                </div>
                            </div>
                            </div>
                        ))
                        ) : (
                        <div className="text-center text-gray-400 italic py-10">No discussions yet. Be the first to post!</div>
                        )}
                    </div>
                 )}
              </>
            )}
          </div>
        )}
      </div>
    </div>
  );
};


// --- Club Admin Dashboard (With Announcements) ---

const ClubAdminDashboard = ({ user }: { user: User }) => {
    const [events, setEvents] = useState<Event[]>([]);
    const [announcementText, setAnnouncementText] = useState('');
    const [isPosting, setIsPosting] = useState(false);
    const [isProposalModalOpen, setIsProposalModalOpen] = useState(false);
    const [proposalTopic, setProposalTopic] = useState('');
    const [generatedDesc, setGeneratedDesc] = useState('');
    const [isGenerating, setIsGenerating] = useState(false);
    const [newProposal, setNewProposal] = useState<Partial<Event>>({
      title: '', date: '', time: '', venueId: '', capacity: 0, price: 0, volunteersNeeded: false
    });
    const [venues, setVenues] = useState<Venue[]>([]);

    useEffect(() => {
        api.events.list().then(setEvents);
        api.venues.list().then(setVenues);
    }, []);

    const handleAddAnnouncement = async () => {
        if(!user.clubId || !announcementText.trim()) return;
        setIsPosting(true);
        try {
            const ann: Announcement = {
                id: `a${Date.now()}`,
                clubId: user.clubId,
                content: announcementText,
                date: new Date().toISOString()
            };
            await api.announcements.create(ann);
            alert("Announcement Posted!");
            setAnnouncementText('');
        } catch(e) {
            alert("Failed to post announcement");
        } finally {
            setIsPosting(false);
        }
    };

    const handleAiGenerate = async () => {
        if (!proposalTopic) return;
        setIsGenerating(true);
        const desc = await generateEventContent(proposalTopic, 'description');
        setGeneratedDesc(desc);
        setNewProposal({ ...newProposal, description: desc });
        setIsGenerating(false);
      };

      const handleSubmitProposal = async (e: React.FormEvent) => {
        e.preventDefault();
        const event: Event = {
          id: `e${Date.now()}`,
          title: newProposal.title || 'Untitled Event',
          description: newProposal.description || generatedDesc || 'No description provided.',
          organizer: 'My Club', 
          clubId: user.clubId || 'c1',
          date: newProposal.date || '2024-01-01',
          time: newProposal.time || '12:00',
          venueId: newProposal.venueId || 'v1',
          status: EventStatus.PENDING,
          capacity: newProposal.capacity || 100,
          registeredCount: 0,
          tags: ['New'],
          price: newProposal.price || 0,
          image: `https://picsum.photos/800/400?random=${Date.now()}`,
          volunteersNeeded: newProposal.volunteersNeeded
        };

        await api.events.create(event);
        setIsProposalModalOpen(false);
        setNewProposal({});
        setProposalTopic('');
        setGeneratedDesc('');
        alert("Proposal submitted for College Admin approval.");
      };

    const data = [
      { name: 'Hackathon', participants: 150 },
      { name: 'AI Talk', participants: 80 },
      { name: 'Web Dev', participants: 200 },
    ];

    return (
      <div className="space-y-12 animate-in fade-in duration-500">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="bg-black text-yellow-400 p-8 shadow-[8px_8px_0px_#FACC15] border-2 border-black">
            <h3 className="text-sm font-bold opacity-80 uppercase tracking-widest mb-2">Total Reach</h3>
            <p className="text-5xl font-black">1,240</p>
          </div>
          <div className="bg-white text-black p-8 shadow-[8px_8px_0px_#000] border-2 border-black">
            <h3 className="text-sm font-bold text-gray-500 uppercase tracking-widest mb-2">Avg Rating</h3>
            <p className="text-5xl font-black">4.8</p>
          </div>
          <div className="bg-yellow-400 text-black p-8 border-2 border-black shadow-[8px_8px_0px_#000] flex flex-col justify-between">
            <h3 className="text-sm font-bold text-black uppercase tracking-widest mb-2">Next Event</h3>
            <div>
              <p className="text-2xl font-black leading-tight">Hackathon 2024</p>
              <span className="text-xs font-bold bg-black text-white px-2 py-1 mt-1 inline-block">In 2 days</span>
            </div>
          </div>
        </div>

        {/* Announcement Section */}
        <div className="bg-white border-2 border-black p-6 shadow-sm">
             <h3 className="text-xl font-black mb-4 flex items-center gap-2"><Megaphone size={24} /> POST ANNOUNCEMENT</h3>
             <div className="flex gap-4">
                 <textarea 
                   className="flex-1 p-3 border-2 border-gray-200 focus:border-black focus:outline-none font-medium" 
                   rows={2}
                   placeholder="Share updates with your club members..."
                   value={announcementText}
                   onChange={e => setAnnouncementText(e.target.value)}
                 />
                 <button 
                   onClick={handleAddAnnouncement}
                   disabled={isPosting}
                   className="bg-black text-white px-6 font-bold uppercase tracking-widest hover:bg-gray-800 disabled:opacity-50"
                 >
                    {isPosting ? <Loader2 className="animate-spin" /> : 'Post'}
                 </button>
             </div>
        </div>

        <div>
          <div className="flex justify-between items-center mb-6">
             <h2 className="text-3xl font-black uppercase tracking-tight">Events & Proposals</h2>
             <button 
               onClick={() => setIsProposalModalOpen(true)}
               className="bg-black text-white px-6 py-3 text-sm font-bold uppercase tracking-wider hover:bg-gray-800 hover:scale-105 transition-transform flex items-center gap-2 border-2 border-transparent hover:border-yellow-400"
             >
               <Sparkles size={16} className="text-yellow-400" /> New Proposal
             </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {events.filter(e => e.clubId === user?.clubId).map(event => (
              <EventCard 
                key={event.id} 
                event={event} 
                isAdminView={true}
              />
            ))}
          </div>
        </div>

        <div className="bg-white p-8 border-2 border-black shadow-sm">
           <h3 className="text-xl font-black mb-6 border-b-2 border-gray-100 pb-4">PARTICIPATION ANALYTICS</h3>
           <div className="h-64 w-full">
             <ResponsiveContainer width="100%" height="100%">
               <BarChart data={data}>
                 <XAxis dataKey="name" stroke="#000" fontSize={12} tickLine={false} axisLine={false} />
                 <YAxis stroke="#000" fontSize={12} tickLine={false} axisLine={false} />
                 <Tooltip cursor={{fill: '#fefce8'}} contentStyle={{ background: '#000', color: '#fff', border: 'none', fontWeight: 'bold' }} />
                 <Bar dataKey="participants" fill="#FACC15" radius={[0, 0, 0, 0]} barSize={50} stroke="#000" strokeWidth={2} />
               </BarChart>
             </ResponsiveContainer>
           </div>
        </div>

        {/* Proposal Modal */}
        <Modal
            isOpen={isProposalModalOpen}
            onClose={() => setIsProposalModalOpen(false)}
            title="New Event Proposal"
        >
             <div className="space-y-6">

                {/* AI Assistant */}
                <div className="bg-yellow-50 p-6 border-2 border-yellow-400 border-dashed rounded-lg">
                  <div className="flex items-center gap-2 mb-3">
                    <Sparkles size={20} className="text-black" />
                    <h3 className="text-sm font-black uppercase tracking-wider">AI Content Architect</h3>
                  </div>
                  <div className="flex gap-2">
                    <input 
                      type="text" 
                      placeholder="E.g., A robotics workshop for beginners..."
                      className="flex-1 p-3 border-2 border-black text-sm font-medium focus:outline-none focus:ring-2 focus:ring-yellow-400"
                      value={proposalTopic}
                      onChange={(e) => setProposalTopic(e.target.value)}
                    />
                    <button 
                      onClick={handleAiGenerate}
                      disabled={isGenerating}
                      className="bg-black text-white px-6 py-2 text-xs font-bold uppercase hover:bg-gray-800 disabled:opacity-50 min-w-[120px] flex items-center justify-center border-2 border-black"
                    >
                      {isGenerating ? <Loader2 className="animate-spin text-yellow-400" size={16} /> : 'Generate'}
                    </button>
                  </div>
                </div>

                <form onSubmit={handleSubmitProposal} className="space-y-5">
                  <div>
                    <label className="block text-xs font-bold uppercase text-gray-500 mb-2">Event Title</label>
                    <input 
                      required
                      type="text" 
                      className="w-full p-4 border-2 border-gray-200 focus:border-black focus:outline-none transition-colors font-bold text-lg"
                      value={newProposal.title}
                      onChange={e => setNewProposal({...newProposal, title: e.target.value})}
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold uppercase text-gray-500 mb-2">Description</label>
                    <textarea 
                      required
                      rows={4}
                      className="w-full p-4 border-2 border-gray-200 focus:border-black focus:outline-none transition-colors font-medium"
                      value={newProposal.description || generatedDesc}
                      onChange={e => setNewProposal({...newProposal, description: e.target.value})}
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-6">
                    <div>
                      <label className="block text-xs font-bold uppercase text-gray-500 mb-2">Date</label>
                      <input 
                        required
                        type="date" 
                        className="w-full p-3 border-2 border-gray-200 focus:border-black focus:outline-none font-medium"
                        value={newProposal.date}
                        onChange={e => setNewProposal({...newProposal, date: e.target.value})}
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-bold uppercase text-gray-500 mb-2">Time</label>
                      <input 
                        required
                        type="time" 
                        className="w-full p-3 border-2 border-gray-200 focus:border-black focus:outline-none font-medium"
                        value={newProposal.time}
                        onChange={e => setNewProposal({...newProposal, time: e.target.value})}
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-6">
                     <div>
                      <label className="block text-xs font-bold uppercase text-gray-500 mb-2">Venue Preference</label>
                      <select 
                        className="w-full p-3 border-2 border-gray-200 focus:border-black focus:outline-none bg-white font-medium"
                        value={newProposal.venueId}
                        onChange={e => setNewProposal({...newProposal, venueId: e.target.value})}
                      >
                        <option value="">Select Venue</option>
                        {venues.map(v => (
                          <option key={v.id} value={v.id}>{v.name} (Cap: {v.capacity})</option>
                        ))}
                      </select>
                    </div>
                    <div>
                      <label className="block text-xs font-bold uppercase text-gray-500 mb-2">Ticket Price (₹)</label>
                      <input 
                        type="number" 
                        className="w-full p-3 border-2 border-gray-200 focus:border-black focus:outline-none font-medium"
                        placeholder="0 for Free"
                        value={newProposal.price}
                        onChange={e => setNewProposal({...newProposal, price: Number(e.target.value)})}
                      />
                    </div>
                  </div>

                  {/* Volunteers Checkbox */}
                  <div className="flex items-center gap-3 p-4 bg-gray-50 border-2 border-gray-200">
                      <input 
                        type="checkbox"
                        id="volunteers"
                        className="w-5 h-5 text-yellow-400 focus:ring-black border-gray-300 rounded"
                        checked={newProposal.volunteersNeeded}
                        onChange={e => setNewProposal({...newProposal, volunteersNeeded: e.target.checked})}
                      />
                      <label htmlFor="volunteers" className="font-bold text-sm cursor-pointer select-none">Volunteers Needed for this Event</label>
                  </div>

                  <button type="submit" className="w-full bg-yellow-400 text-black py-4 font-black uppercase tracking-widest hover:bg-yellow-500 transition-all mt-6 border-2 border-black shadow-[4px_4px_0px_#000] active:shadow-none active:translate-x-[2px] active:translate-y-[2px]">
                    Submit Proposal
                  </button>
                </form>
             </div>
        </Modal>
      </div>
    );
};

// --- Main App Component ---

const App: React.FC = () => {
  // Auth State
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [authView, setAuthView] = useState<'login' | 'signup'>('login');

  // App Data State
  const [user, setUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState('feed');
  const [events, setEvents] = useState<Event[]>([]);
  const [registeredEvents, setRegisteredEvents] = useState<string[]>([]);
  const [clubs, setClubs] = useState<Club[]>([]);
  const [venues, setVenues] = useState<Venue[]>([]);
  const [myVolunteerApps, setMyVolunteerApps] = useState<VolunteerApplication[]>([]);

  // Volunteer Management (Admin)
  const [manageVolunteersEvent, setManageVolunteersEvent] = useState<Event | null>(null);
  const [eventVolunteers, setEventVolunteers] = useState<VolunteerApplication[]>([]);
  const [loadingVolunteers, setLoadingVolunteers] = useState(false);

  // Global Loading State
  const [isDataLoading, setIsDataLoading] = useState(false);

  // Search State
  const [searchQuery, setSearchQuery] = useState('');

  // Navigation State
  const [selectedClubId, setSelectedClubId] = useState<string | null>(null);

  // --- Data Fetching ---

  const refreshData = async () => {
      // Background refresh without blocking UI unless initial load
      try {
          const [e, c] = await Promise.all([api.events.list(), api.clubs.list()]);
          setEvents(e);
          setClubs(c);
          if (user) {
              const apps = await api.volunteers.listByUser(user.id);
              setMyVolunteerApps(apps);
          }
      } catch (err) {
          console.error("Error refreshing data", err);
      }
  };

  useEffect(() => {
    // Initial Load
    const init = async () => {
        setIsDataLoading(true);
        try {
            const [e, c, v] = await Promise.all([api.events.list(), api.clubs.list(), api.venues.list()]);
            setEvents(e);
            setClubs(c);
            setVenues(v);
        } catch(err) {
            console.error("Init failed", err);
        } finally {
            setIsDataLoading(false);
        }
    };
    init();
  }, []);

  useEffect(() => {
     if (user) {
         api.volunteers.listByUser(user.id).then(setMyVolunteerApps);
     }
  }, [user]);

  // --- Handlers ---

  const handleLogin = (loggedInUser: User) => {
    setUser(loggedInUser);
    setIsAuthenticated(true);
    // Determine default tab based on role
    if (loggedInUser.role === UserRole.STUDENT) setActiveTab('feed');
    else if (loggedInUser.role === UserRole.CLUB_ADMIN) setActiveTab('dashboard');
    else if (loggedInUser.role === UserRole.COLLEGE_ADMIN) setActiveTab('approvals');
  };

  const handleSignup = (newUser: User) => {
    setUser(newUser);
    setIsAuthenticated(true);
    setActiveTab('feed');
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setUser(null);
    setAuthView('login');
    setSelectedClubId(null);
  };

  const handleRegister = async (eventId: string) => {
    if (registeredEvents.includes(eventId)) return;

    // Optimistic Update
    setRegisteredEvents([...registeredEvents, eventId]);
    await api.events.register(eventId, user!.id);
    await refreshData();

    alert("Ticket Confirmed! You can view it in 'My Tickets'.");
  };

  const handleJoinClub = async (clubId: string) => {
    if (!user) return;
    try {
        const updatedUser = await api.clubs.join(clubId, user.id);
        setUser(updatedUser);
        await refreshData();
        alert("You have joined the club!");
    } catch (e) {
        alert("Could not join club.");
    }
  };

  const handleLeaveClub = async (clubId: string) => {
    if (!user) return;
    try {
        const updatedUser = await api.clubs.leave(clubId, user.id);
        setUser(updatedUser);
        await refreshData();
        alert("You have left the club.");
    } catch (e) {
        alert("Could not leave club.");
    }
  };

  const handleAddPost = async (content: string) => {
    if (!user || !selectedClubId) return;

    const newPost: Post = {
      id: `p${Date.now()}`,
      clubId: selectedClubId,
      userId: user.id,
      userName: user.name,
      userAvatar: user.avatar || '',
      content: content,
      timestamp: 'Just now',
      likes: 0
    };

    // We don't await here to keep UI snappy, discussion component handles optimistic update
    api.posts.create(newPost); 
  };

  const handleApprove = async (eventId: string) => {
    await api.events.updateStatus(eventId, EventStatus.APPROVED);
    await refreshData();
  };

  const handleReject = async (eventId: string) => {
    await api.events.updateStatus(eventId, EventStatus.REJECTED);
    await refreshData();
  };

  // Volunteer Handlers
  const handleVolunteerApply = async (eventId: string) => {
      if (!user) return;
      try {
          const newApp: VolunteerApplication = {
              id: `v${Date.now()}`,
              eventId,
              userId: user.id,
              userName: user.name,
              userAvatar: user.avatar,
              status: VolunteerStatus.PENDING,
              appliedAt: new Date().toISOString()
          };
          await api.volunteers.apply(newApp);
          setMyVolunteerApps([...myVolunteerApps, newApp]);
          alert("Application submitted!");
      } catch (e: any) {
          alert(e.message || "Failed to apply");
      }
  };

  const handleOpenVolunteerManager = async (event: Event) => {
      setManageVolunteersEvent(event);
      setLoadingVolunteers(true);
      try {
          const apps = await api.volunteers.listByEvent(event.id);
          setEventVolunteers(apps);
      } finally {
          setLoadingVolunteers(false);
      }
  };

  const handleVolunteerAction = async (appId: string, status: VolunteerStatus) => {
      try {
          await api.volunteers.updateStatus(appId, status);
          // Update local state
          setEventVolunteers(eventVolunteers.map(a => a.id === appId ? { ...a, status } : a));
      } catch (e) {
          alert("Failed to update status");
      }
  };

  // --- Views ---

  // 1. Events Feed (Optimized with Search)
  const EventsFeed = () => {
    const filteredEvents = events.filter(e => {
        if (e.status !== EventStatus.APPROVED) return false;
        const query = searchQuery.toLowerCase();
        return (
          e.title.toLowerCase().includes(query) || 
          e.description.toLowerCase().includes(query) ||
          e.tags.some(tag => tag.toLowerCase().includes(query))
        );
    });

    if (isDataLoading) return <div className="flex h-96 items-center justify-center"><Loader2 size={48} className="animate-spin text-yellow-500" /></div>;

    return (
      <div className="space-y-8 animate-in fade-in duration-500">
        <div className="flex flex-col md:flex-row justify-between items-end border-b-4 border-black pb-6 gap-4">
          <div>
            <h2 className="text-4xl md:text-5xl font-black tracking-tighter mb-2">WHATS ON<span className="text-yellow-500">?</span></h2>
            <p className="text-gray-500 font-medium">Discover and join campus activities.</p>
          </div>
          <div className="relative w-full md:w-auto">
            <input 
              type="text" 
              placeholder="Search events, tags..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-10 pr-4 py-3 border-2 border-black focus:outline-none focus:ring-4 focus:ring-yellow-400 w-full md:w-80 font-bold bg-white transition-all shadow-sm focus:shadow-md"
            />
            <Search className="absolute left-3 top-3.5 text-black" size={20} />
          </div>
        </div>

        {filteredEvents.length === 0 ? (
           <div className="text-center py-20 bg-gray-50 border-2 border-dashed border-gray-200">
              <Search className="mx-auto h-12 w-12 text-gray-300 mb-4" />
              <h3 className="text-xl font-bold text-gray-500">No events found matching "{searchQuery}"</h3>
           </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {filteredEvents.map(event => (
              <EventCard 
                key={event.id} 
                event={event} 
                onRegister={handleRegister}
                isRegistered={registeredEvents.includes(event.id)}
                isAdminView={false}
                venueName={venues.find(v => v.id === event.venueId)?.name}
                onVolunteer={handleVolunteerApply}
                volunteerStatus={myVolunteerApps.find(a => a.eventId === event.id)?.status}
              />
            ))}
          </div>
        )}
      </div>
    );
  };

  // 2. Clubs View (List or Detail)
  const ClubsView = () => {
    if (selectedClubId) {
      const club = clubs.find(c => c.id === selectedClubId);
      if (!club) return <div>Club not found</div>;

      return (
        <ClubDetailView 
          club={club}
          user={user}
          onJoin={handleJoinClub}
          onLeave={handleLeaveClub}
          events={events}
          onAddPost={handleAddPost}
          onBack={() => setSelectedClubId(null)}
          onVolunteer={handleVolunteerApply}
          myVolunteerApps={myVolunteerApps}
        />
      );
    }

    if (isDataLoading) return <div className="flex h-96 items-center justify-center"><Loader2 size={48} className="animate-spin text-yellow-500" /></div>;

    return (
      <div className="space-y-8 animate-in fade-in duration-500">
        <div className="border-b-4 border-black pb-6 mb-8">
          <h2 className="text-4xl md:text-5xl font-black tracking-tighter mb-2">CAMPUS CLUBS</h2>
          <p className="text-gray-500 font-medium">Find your tribe. Join a community.</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {clubs.map(club => (
            <ClubCard 
              key={club.id} 
              club={club} 
              onClick={() => setSelectedClubId(club.id)}
            />
          ))}
        </div>
      </div>
    );
  };

  // 3. My Tickets
  const MyTicketsView = () => {
    const myEvents = events.filter(e => registeredEvents.includes(e.id));
    return (
      <div className="space-y-8 animate-in fade-in duration-500">
         <div className="border-b-4 border-black pb-6">
          <h2 className="text-4xl font-black tracking-tighter">MY TICKETS</h2>
        </div>
        {myEvents.length === 0 ? (
          <div className="bg-white border-2 border-dashed border-gray-300 p-12 text-center rounded-lg">
             <Trophy size={48} className="mx-auto text-yellow-400 mb-4" />
             <h3 className="text-xl font-bold mb-2">No tickets yet!</h3>
             <p className="text-gray-500 mb-6">Explore the events feed to find something cool.</p>
             <button onClick={() => setActiveTab('feed')} className="bg-black text-white px-6 py-3 font-bold uppercase tracking-widest hover:bg-gray-800">
               Browse Events
             </button>
          </div>
        ) : (
          <div className="grid gap-4">
             {myEvents.map(event => (
               <div key={event.id} className="bg-white border-l-8 border-yellow-400 border border-gray-200 p-6 flex flex-col md:flex-row justify-between items-start md:items-center shadow-sm gap-4">
                  <div>
                    <h3 className="text-2xl font-black">{event.title}</h3>
                    <p className="text-gray-500 font-medium">{event.date} • {event.time} • {venues.find(v => v.id === event.venueId)?.name}</p>
                  </div>
                  <div className="text-left md:text-right w-full md:w-auto">
                    <div className="bg-black text-white px-4 py-2 text-xs font-bold uppercase tracking-widest mb-1 inline-block">Confirmed</div>
                    <p className="text-xs text-gray-400">ID: #{event.id.toUpperCase()}</p>
                  </div>
               </div>
             ))}
          </div>
        )}
      </div>
    );
  };

  // 5. College Admin View (Approvals & Management)
  const CollegeAdminView = () => {
    const pendingEvents = events.filter(e => e.status === EventStatus.PENDING);
    const approvedEvents = events.filter(e => e.status === EventStatus.APPROVED);

    if (activeTab === 'clubs_manage') {
      return (
        <div className="animate-in fade-in duration-500">
           <div className="flex justify-between items-center mb-8 border-b-4 border-black pb-4">
              <h2 className="text-4xl font-black tracking-tight">CLUB MANAGEMENT</h2>
              <button className="bg-black text-white px-4 py-2 text-sm font-bold uppercase tracking-wider flex items-center gap-2">
                 <PlusCircle size={16} /> Add Club
              </button>
           </div>
           <div className="bg-white border-2 border-black shadow-sm overflow-hidden overflow-x-auto">
             <table className="w-full text-left min-w-[600px]">
               <thead className="bg-black text-white">
                 <tr>
                   <th className="p-4 font-bold uppercase text-xs tracking-wider">Club Name</th>
                   <th className="p-4 font-bold uppercase text-xs tracking-wider">Members</th>
                   <th className="p-4 font-bold uppercase text-xs tracking-wider">Admin</th>
                   <th className="p-4 font-bold uppercase text-xs tracking-wider text-right">Actions</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-gray-200">
                 {clubs.map(club => (
                   <tr key={club.id} className="hover:bg-yellow-50 transition-colors">
                     <td className="p-4 font-bold flex items-center gap-3">
                       <img src={club.logo} className="w-8 h-8 rounded-full border border-black" />
                       {club.name}
                     </td>
                     <td className="p-4 font-medium text-gray-600">{club.memberCount}</td>
                     <td className="p-4 font-medium text-gray-600">ID: {club.adminId}</td>
                     <td className="p-4 text-right">
                       <button className="text-xs font-bold border border-black px-2 py-1 hover:bg-black hover:text-white transition">Manage</button>
                     </td>
                   </tr>
                 ))}
               </tbody>
             </table>
           </div>
        </div>
      )
    }

    // Default: Approvals & Calendar
    return (
      <div className="space-y-10 animate-in fade-in duration-500">
        <div className="flex items-center gap-4 bg-yellow-50 p-6 border-l-8 border-yellow-400 shadow-sm">
          <AlertCircle size={32} className="text-black" />
          <div>
            <h3 className="font-black text-lg">ATTENTION NEEDED</h3>
            <p className="text-sm text-gray-600 font-medium">You have <span className="font-bold text-black">{pendingEvents.length} pending event proposals</span> waiting for review.</p>
          </div>
        </div>

        <div>
          <h2 className="text-3xl font-black mb-6 flex items-center gap-3">
            <CheckSquare size={32} className="text-yellow-500" /> PROPOSAL QUEUE
          </h2>
          {pendingEvents.length === 0 ? (
            <div className="text-center py-16 bg-white border-2 border-dashed border-gray-300 text-gray-400">
              <CheckSquare size={48} className="mx-auto mb-4 opacity-20" />
              <p className="font-bold">All caught up! No pending proposals.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {pendingEvents.map(event => (
                <EventCard 
                  key={event.id} 
                  event={event} 
                  isAdminView={true}
                  onApprove={handleApprove}
                  onReject={handleReject}
                  venueName={venues.find(v => v.id === event.venueId)?.name}
                />
              ))}
            </div>
          )}
        </div>

        <div className="pt-10 border-t-4 border-black">
           <div className="flex justify-between items-center mb-6">
              <h2 className="text-3xl font-black flex items-center gap-3">
                <Calendar size={32} className="text-yellow-500" /> MASTER SCHEDULE
              </h2>
              <div className="flex gap-2">
                <button className="px-4 py-2 border-2 border-black text-sm font-bold hover:bg-gray-100">PDF Report</button>
                <button className="px-4 py-2 bg-black text-yellow-400 text-sm font-bold border-2 border-black hover:bg-gray-800">Export CSV</button>
              </div>
           </div>

           <div className="bg-white border-2 border-black overflow-hidden shadow-sm overflow-x-auto">
             <table className="w-full text-left text-sm min-w-[700px]">
               <thead className="bg-gray-100 border-b-2 border-black text-black">
                 <tr>
                   <th className="p-4 font-black uppercase text-xs tracking-wider">Event</th>
                   <th className="p-4 font-black uppercase text-xs tracking-wider">Organizer</th>
                   <th className="p-4 font-black uppercase text-xs tracking-wider">Date/Time</th>
                   <th className="p-4 font-black uppercase text-xs tracking-wider">Venue</th>
                   <th className="p-4 font-black uppercase text-xs tracking-wider">Status</th>
                 </tr>
               </thead>
               <tbody className="divide-y divide-gray-200">
                 {approvedEvents.map(event => (
                   <tr key={event.id} className="hover:bg-yellow-50 transition-colors">
                     <td className="p-4 font-bold text-base">{event.title}</td>
                     <td className="p-4 text-gray-600 font-medium">{event.organizer}</td>
                     <td className="p-4 text-gray-600 font-medium">{event.date} at {event.time}</td>
                     <td className="p-4 text-gray-600 font-medium">
                        {venues.find(v => v.id === event.venueId)?.name}
                     </td>
                     <td className="p-4"><StatusBadge status={event.status} /></td>
                   </tr>
                 ))}
               </tbody>
             </table>
           </div>
        </div>
      </div>
    );
  };

  // --- Main Render ---

  if (!isAuthenticated) {
    if (authView === 'login') {
      return <LoginPage onLogin={handleLogin} onSwitchToSignup={() => setAuthView('signup')} />;
    } else {
      return <SignupPage onSignup={handleSignup} onSwitchToLogin={() => setAuthView('login')} />;
    }
  }

  return (
    <Layout 
      user={user!} 
      onLogout={handleLogout}
      onSwitchRole={async (role) => {
        // Updated Demo Switcher to use API
        const u = await api.auth.loginAsRole(role);
        setUser(u);
      }}
      activeTab={activeTab}
      setActiveTab={setActiveTab}
    >
      {user?.role === UserRole.STUDENT && (
        <>
          {activeTab === 'feed' && <EventsFeed />}
          {activeTab === 'clubs' && <ClubsView />}
          {activeTab === 'tickets' && <MyTicketsView />}
          {activeTab === 'profile' && <ProfilePage user={user} onUpdateUser={setUser} onLogout={handleLogout} />}
        </>
      )}

      {user?.role === UserRole.CLUB_ADMIN && (
        <>
           {activeTab === 'dashboard' && <ClubAdminDashboard user={user} />}
           {activeTab === 'create' && <ClubAdminDashboard user={user} />} 
           {activeTab === 'analytics' && <ClubAdminDashboard user={user} />} 
           {activeTab === 'profile' && <ProfilePage user={user} onUpdateUser={setUser} onLogout={handleLogout} />}
        </>
      )}

      {user?.role === UserRole.COLLEGE_ADMIN && (
        <>
           {activeTab === 'approvals' && <CollegeAdminView />}
           {activeTab === 'calendar' && <CollegeAdminView />}
           {activeTab === 'clubs_manage' && <CollegeAdminView />}
           {activeTab === 'reports' && <CollegeAdminView />}
           {activeTab === 'profile' && <ProfilePage user={user} onUpdateUser={setUser} onLogout={handleLogout} />}
        </>
      )}

      {/* Volunteer Management Modal (Global for Admin) */}
        <Modal 
          isOpen={!!manageVolunteersEvent} 
          onClose={() => setManageVolunteersEvent(null)}
          title={`Manage Volunteers: ${manageVolunteersEvent?.title}`}
        >
            {loadingVolunteers ? (
                <div className="flex justify-center p-8"><Loader2 className="animate-spin" size={32}/></div>
            ) : eventVolunteers.length === 0 ? (
                <div className="text-center p-8 text-gray-500">No volunteer applications yet.</div>
            ) : (
                <div className="space-y-4">
                    {eventVolunteers.map(app => (
                        <div key={app.id} className="flex items-center justify-between p-4 border border-gray-200 bg-gray-50 rounded-lg">
                            <div className="flex items-center gap-3">
                                <img src={app.userAvatar} className="w-10 h-10 rounded-full bg-gray-200 border border-black" />
                                <div>
                                    <p className="font-bold text-sm">{app.userName}</p>
                                    <p className="text-xs text-gray-500">Applied: {new Date(app.appliedAt).toLocaleDateString()}</p>
                                </div>
                            </div>
                            <div className="flex items-center gap-4">
                                <VolunteerBadge status={app.status} />
                                {app.status === VolunteerStatus.PENDING && (
                                    <div className="flex gap-2">
                                        <button 
                                          onClick={() => handleVolunteerAction(app.id, VolunteerStatus.ACCEPTED)}
                                          className="p-1.5 bg-green-100 text-green-700 hover:bg-green-200 rounded border border-green-300"
                                          title="Accept"
                                        >
                                            <Check size={16} />
                                        </button>
                                        <button 
                                          onClick={() => handleVolunteerAction(app.id, VolunteerStatus.REJECTED)}
                                          className="p-1.5 bg-red-100 text-red-700 hover:bg-red-200 rounded border border-red-300"
                                          title="Reject"
                                        >
                                            <X size={16} />
                                        </button>
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            )}
        </Modal>
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import { UserRole, EventStatus, Event, User, Venue, Club, Post, VolunteerApplication, VolunteerStatus, Announcement } from './types';
import { api } from './services/api'; 
import { generateEventContent } from './services/geminiService';
import { 
  Calendar, 
  MapPin, 
  Clock, 
  Users, 
  Check, 
  X, 
  Search, 
  Loader2, 
  Sparkles, 
  AlertCircle,
  TrendingUp,
  DollarSign,
  CheckSquare,
  Hand,
  Trophy,
  Megaphone,
  PlusCircle,
  Mail,
  Lock,
  ArrowRight,
  Edit,
  Save,
  MessageSquare,
  Heart,
  Send,
  ArrowLeft,
  FileText,
  Briefcase,
  LogOut
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';

// --- Shared Components ---

const StatusBadge = ({ status }: { status: EventStatus }) => {
  const styles = {
    [EventStatus.APPROVED]: 'bg-yellow-400 text-black border border-yellow-500 shadow-[2px_2px_0px_rgba(0,0,0,1)]',
    [EventStatus.PENDING]: 'bg-black text-white border border-gray-700',
    [EventStatus.REJECTED]: 'bg-gray-200 text-gray-500 border border-gray-300 line-through',
    [EventStatus.COMPLETED]: 'bg-gray-800 text-white border border-gray-900',
  };
  return (
    <span className={`px-3 py-1 text-[10px] font-extrabold uppercase tracking-widest rounded-sm ${styles[status]}`}>
      {status}
    </span>
  );
};

const VolunteerBadge = ({ status }: { status: VolunteerStatus }) => {
    const styles = {
      [VolunteerStatus.PENDING]: 'bg-gray-100 text-gray-500 border border-gray-300',
      [VolunteerStatus.ACCEPTED]: 'bg-green-100 text-green-700 border border-green-300',
      [VolunteerStatus.REJECTED]: 'bg-red-50 text-red-400 border border-red-200 line-through',
    };
    return (
      <span className={`px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide rounded-sm ${styles[status]}`}>
        {status}
      </span>
    );
};

interface EventCardProps {
    event: Event;
    onRegister?: (id: string) => void;
    isRegistered?: boolean;
    isAdminView: boolean;
    onApprove?: (id: string) => void;
    onReject?: (id: string) => void;
    venueName?: string;
    onVolunteer?: (id: string) => void;
    volunteerStatus?: VolunteerStatus | null;
    onManageVolunteers?: (event: Event) => void;
}

const EventCard = ({ 
    event, onRegister, isRegistered, isAdminView, onApprove, onReject, venueName, 
    onVolunteer, volunteerStatus, onManageVolunteers 
}: EventCardProps) => {
  const [loadingAction, setLoadingAction] = useState<string | null>(null);

  // Safely check if admin actions are available
  const showAdminActions = isAdminView && 
    event.status === EventStatus.PENDING && 
    typeof onApprove === 'function' && 
    typeof onReject === 'function';

  return (
    <div className="bg-white border-2 border-black shadow-[4px_4px_0px_rgba(0,0,0,1)] hover:shadow-[8px_8px_0px_rgba(250,204,21,1)] hover:-translate-y-1 transition-all duration-200 flex flex-col h-full group relative overflow-hidden">

      {/* Decorative corner */}
      <div className="absolute top-0 right-0 w-16 h-16 bg-yellow-400 rotate-45 translate-x-8 -translate-y-8 z-10"></div>

      <div className="h-48 overflow-hidden relative bg-gray-900 border-b-2 border-black">
        <img 
          src={event.image} 
          alt={event.title} 
          className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500 opacity-80 group-hover:opacity-100"
        />
        <div className="absolute top-3 right-3 z-20">
            <StatusBadge status={event.status} />
        </div>
        {event.price > 0 ? (
           <div className="absolute bottom-3 right-3 bg-black text-yellow-400 px-3 py-1 text-xs font-extrabold border border-yellow-400 shadow-sm">
             ₹{event.price}
           </div>
        ) : (
           <div className="absolute bottom-3 right-3 bg-yellow-400 text-black px-3 py-1 text-xs font-extrabold border border-black shadow-sm">
             FREE
           </div>
        )}
      </div>

      <div className="p-5 flex-1 flex flex-col">
        <div className="mb-3 flex items-center justify-between">
           <div className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest border border-gray-200 px-2 py-0.5 rounded-full inline-block">
             {event.organizer}
           </div>
           <div className="text-[10px] font-bold text-gray-400 flex items-center gap-1">
             <Users size={12} /> {event.capacity - event.registeredCount} spots left
           </div>
        </div>

        <h3 className="text-2xl font-black mb-3 leading-none tracking-tight">{event.title}</h3>
        <p className="text-gray-600 text-sm mb-5 line-clamp-2 font-medium">{event.description}</p>

        <div className="space-y-3 mt-auto text-sm text-black font-semibold">
          <div className="flex items-center">
            <Calendar size={16} className="mr-3 text-yellow-500" />
            {event.date}
          </div>
          <div className="flex items-center">
            <Clock size={16} className="mr-3 text-yellow-500" />
            {event.time}
          </div>
          <div className="flex items-center">
            <MapPin size={16} className="mr-3 text-yellow-500" />
            {venueName || 'TBD'}
          </div>
        </div>
      </div>

      <div className="p-4 pt-0 mt-2">
        {isAdminView ? (
          showAdminActions ? (
            <div className="flex space-x-2 pt-2">
              <button 
                onClick={async () => { setLoadingAction('approve'); await onApprove!(event.id); setLoadingAction(null); }} 
                className="flex-1 bg-black text-yellow-400 py-3 text-sm font-bold hover:bg-gray-900 transition border-2 border-black flex items-center justify-center"
              >
                {loadingAction === 'approve' ? <Loader2 className="animate-spin" size={16}/> : 'Approve'}
              </button>
              <button 
                onClick={async () => { setLoadingAction('reject'); await onReject!(event.id); setLoadingAction(null); }} 
                className="flex-1 bg-white border-2 border-black text-black py-3 text-sm font-bold hover:bg-red-50 hover:border-red-500 hover:text-red-500 transition flex items-center justify-center"
              >
                 {loadingAction === 'reject' ? <Loader2 className="animate-spin" size={16}/> : 'Reject'}
              </button>
            </div>
          ) : (
             // Admin view but not pending (Approved/Rejected)
             event.status === EventStatus.APPROVED && onManageVolunteers ? (
                <button 
                  onClick={() => onManageVolunteers(event)}
                  className="w-full py-3 text-sm font-bold uppercase tracking-widest bg-white border-2 border-black text-black hover:bg-yellow-50 transition flex items-center justify-center gap-2 mt-2"
                >
                   <Briefcase size={16}/> Manage Volunteers
                </button>
             ) : (
                <div className="pt-2 text-center text-sm font-bold uppercase tracking-widest text-gray-400 border-t border-gray-100 py-4">
                {event.status === EventStatus.APPROVED ? 'Event Active' : 'Event Closed'}
                </div>
             )
          )
        ) : (
          <div className="space-y-2">
             <button 
                onClick={async () => { 
                  if (onRegister) {
                    setLoadingAction('reg'); 
                    await onRegister(event.id); 
                    setLoadingAction(null); 
                  }
                }}
                disabled={isRegistered || event.status !== EventStatus.APPROVED || loadingAction === 'reg'}
                className={`w-full py-3 text-sm font-black uppercase tracking-widest transition-all border-2 border-black shadow-[2px_2px_0px_rgba(0,0,0,1)] active:shadow-none active:translate-x-[2px] active:translate-y-[2px] flex items-center justify-center gap-2 ${
                  isRegistered 
                    ? 'bg-gray-100 text-gray-400 border-gray-200 shadow-none cursor-not-allowed' 
                    : event.status !== EventStatus.APPROVED 
                      ? 'bg-gray-100 text-gray-400 border-gray-200 shadow-none cursor-not-allowed'
                      : 'bg-yellow-400 text-black hover:bg-yellow-300'
                }`}
              >
                {loadingAction === 'reg' ? <Loader2 className="animate-spin" size={16}/> : (isRegistered ? 'Ticket Confirmed' : event.status !== EventStatus.APPROVED ? 'Coming Soon' : 'Get Ticket')}
              </button>

              {/* Only show volunteer button if needed and user not registered? Or user can be both? */}
              {/* Logic: Can apply if event is approved AND volunteersNeeded is true */}
              {!isRegistered && event.status === EventStatus.APPROVED && event.volunteersNeeded && (
                <button 
                  onClick={async () => {
                     if (volunteerStatus) return; // Already applied
                     setLoadingAction('vol');
                     if (onVolunteer) await onVolunteer(event.id);
                     setLoadingAction(null);
                  }}
                  disabled={!!volunteerStatus || loadingAction === 'vol'}
                  className={`w-full py-2 text-xs font-bold uppercase tracking-wider flex items-center justify-center gap-2 ${
                     volunteerStatus 
                       ? 'text-green-600 bg-green-50 border border-green-200 cursor-default'
                       : 'text-gray-500 hover:text-black hover:bg-gray-100'
                  }`}
                >
                  {loadingAction === 'vol' ? <Loader2 className="animate-spin" size={14}/> : (
                      volunteerStatus ? (
                          <>
                            <Check size={14} /> {volunteerStatus === VolunteerStatus.PENDING ? 'Application Pending' : 'Volunteer Accepted'}
                          </>
                      ) : (
                          <>
                            <Hand size={14} /> Volunteer
                          </>
                      )
                  )}
                </button>
              )}
          </div>
        )}
      </div>
    </div>
  );
};

