                    <div>
                         {isMember ? (
                             <button onClick={() => onLeave(club.id)} className="bg-red-500 text-white px-6 py-3 font-bold uppercase border-2 border-transparent hover:bg-red-600">
                                Leave Club
                             </button>
                         ) : (
                             <button onClick={() => onJoin(club.id)} className="bg-yellow-400 text-black px-6 py-3 font-bold uppercase border-2 border-transparent hover:bg-yellow-500">
                                Join Club
                             </button>
                         )}
                    </div>
                </div>
            </div>

            <div className="flex gap-6 border-b-2 border-gray-200 mb-6">
                <button onClick={() => setActiveTab('feed')} className={`pb-3 font-bold uppercase tracking-wider ${activeTab === 'feed' ? 'border-b-4 border-black' : 'text-gray-400'}`}>Community Feed</button>
                <button onClick={() => setActiveTab('events')} className={`pb-3 font-bold uppercase tracking-wider ${activeTab === 'events' ? 'border-b-4 border-black' : 'text-gray-400'}`}>Events</button>
            </div>

            {activeTab === 'feed' ? (
                <div className="space-y-6">
                    {isMember && (
                        <div className="bg-white p-4 border-2 border-black flex gap-4">
                            <img src={user.avatar} className="w-10 h-10 rounded-full border border-black" />
                            <div className="flex-1">
                                <textarea 
                                    value={newPost}
                                    onChange={(e) => setNewPost(e.target.value)}
                                    placeholder="Start a discussion..."
                                    className="w-full p-2 focus:outline-none resize-none font-medium"
                                    rows={2}
                                />
                                <div className="flex justify-end mt-2">
                                    <button onClick={handlePost} className="bg-black text-white px-4 py-1 text-xs font-bold uppercase flex items-center gap-2 hover:bg-gray-800">
                                        <Send size={12} /> Post
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}

                    <div className="space-y-4">
                        {posts.map(post => (
                            <div key={post.id} className="bg-white p-6 border border-gray-200 shadow-sm">
                                <div className="flex items-center gap-3 mb-3">
                                    <img src={post.userAvatar} className="w-8 h-8 rounded-full border border-gray-300" />
                                    <div>
                                        <p className="font-bold text-sm">{post.userName}</p>
                                        <p className="text-xs text-gray-400">{post.timestamp}</p>
                                    </div>
                                </div>
                                <p className="text-gray-800 mb-4">{post.content}</p>
                                <div className="flex items-center gap-4 text-xs font-bold text-gray-500">
                                    <button className="flex items-center gap-1 hover:text-red-500"><Heart size={14} /> {post.likes} Likes</button>
                                    <button className="flex items-center gap-1 hover:text-blue-500"><MessageSquare size={14} /> Comment</button>
                                </div>
                            </div>
                        ))}
                         {posts.length === 0 && <p className="text-center text-gray-400 py-8">No discussions yet.</p>}
                    </div>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {events.filter((e: Event) => e.clubId === club.id && e.status === EventStatus.APPROVED).map((event: Event) => (
                        <EventCard 
                            key={event.id} 
                            event={event} 
                            isAdminView={false} 
                            onVolunteer={onVolunteer}
                            volunteerStatus={myVolunteerApps.find((a: VolunteerApplication) => a.eventId === event.id)?.status}
                        />
                    ))}
                    {events.filter((e: Event) => e.clubId === club.id && e.status === EventStatus.APPROVED).length === 0 && (
                        <p className="text-gray-500 col-span-2 text-center py-8">No upcoming events.</p>
                    )}
                </div>
            )}
        </div>
    );
};

