interface ClubDetailViewProps {
    club: Club;
    user: User | null;
    onJoin: (id: string) => void;
    onLeave: (id: string) => void;
    events: Event[];
    onAddPost: (content: string) => void;
    onBack: () => void;
    onVolunteer: (id: string) => void;
    myVolunteerApps: VolunteerApplication[];
}

const ClubDetailView = ({ club, user, onJoin, onLeave, events, onAddPost, onBack, onVolunteer, myVolunteerApps }: ClubDetailViewProps) => {
    const isMember = user?.joinedClubIds?.includes(club.id);
    const [posts, setPosts] = useState<Post[]>([]);
    const [newPostContent, setNewPostContent] = useState('');
    const [activeTab, setActiveTab] = useState<'feed' | 'events'>('feed');

    useEffect(() => {
        api.posts.list(club.id).then(setPosts);
    }, [club.id]);

    const handlePostSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if(!newPostContent.trim()) return;
        await onAddPost(newPostContent);
        setNewPostContent('');
        // Optimistic update
        const newPost: Post = {
             id: `temp_${Date.now()}`,
             clubId: club.id,
             userId: user!.id,
             userName: user!.name,
             userAvatar: user!.avatar || '',
             content: newPostContent,
             timestamp: 'Just now',
             likes: 0
        };
        setPosts([newPost, ...posts]);
    };

    return (
        <div className="animate-in slide-in-from-right duration-300">
            <button onClick={onBack} className="flex items-center font-bold text-gray-500 hover:text-black mb-4">
                <ArrowLeft size={20} className="mr-1" /> Back to Clubs
            </button>

            {/* Club Header */}
            <div className="relative h-48 bg-black mb-8 border-2 border-black overflow-hidden">
                <img src={club.banner} className="w-full h-full object-cover opacity-60" />
                <div className="absolute bottom-0 left-0 w-full p-6 bg-gradient-to-t from-black/90 to-transparent flex items-end justify-between">
                    <div className="flex items-center gap-4">
                        <img src={club.logo} className="w-20 h-20 rounded-full border-4 border-white bg-white" />
                        <div className="text-white">
                            <h2 className="text-3xl font-black">{club.name}</h2>
                            <p className="font-medium opacity-90">{club.memberCount} Members</p>
                        </div>
                    </div>
                    {user && (
                         <button 
                            onClick={() => isMember ? onLeave(club.id) : onJoin(club.id)}
                            className={`px-6 py-2 font-bold uppercase tracking-widest text-sm border-2 ${isMember ? 'bg-transparent text-white border-white hover:bg-white/10' : 'bg-yellow-400 border-yellow-400 text-black hover:bg-yellow-300'}`}
                         >
                            {isMember ? 'Leave Club' : 'Join Club'}
                         </button>
                    )}
                </div>
            </div>

            {/* Tabs */}
            <div className="flex border-b-2 border-gray-200 mb-6">
                <button 
                  onClick={() => setActiveTab('feed')}
                  className={`px-6 py-3 font-bold uppercase tracking-wider ${activeTab === 'feed' ? 'border-b-4 border-black text-black' : 'text-gray-400 hover:text-black'}`}
                >
                    Discussion
                </button>
                <button 
                  onClick={() => setActiveTab('events')}
                  className={`px-6 py-3 font-bold uppercase tracking-wider ${activeTab === 'events' ? 'border-b-4 border-black text-black' : 'text-gray-400 hover:text-black'}`}
                >
                    Events
                </button>
            </div>

            {activeTab === 'feed' ? (
                <div className="space-y-6">
                    {isMember && (
                        <form onSubmit={handlePostSubmit} className="bg-gray-50 p-4 border-2 border-gray-200 focus-within:border-black transition-colors">
                            <textarea 
                                placeholder="Start a discussion..." 
                                className="w-full bg-transparent outline-none font-medium text-lg resize-none"
                                rows={2}
                                value={newPostContent}
                                onChange={e => setNewPostContent(e.target.value)}
                            />
                            <div className="flex justify-end mt-2">
                                <button disabled={!newPostContent.trim()} className="bg-black text-white px-4 py-2 font-bold uppercase text-xs hover:bg-gray-800 disabled:opacity-50">
                                    Post
                                </button>
                            </div>
                        </form>
                    )}

                    {posts.length === 0 ? (
                        <div className="text-center py-12 text-gray-400">
                             <MessageSquare size={48} className="mx-auto mb-2 opacity-20" />
                             <p>No discussions yet.</p>
                        </div>
                    ) : (
                        posts.map(post => (
                            <div key={post.id} className="bg-white border-2 border-gray-100 p-4 hover:border-black transition-colors">
                                <div className="flex items-center gap-3 mb-3">
                                    <img src={post.userAvatar} className="w-10 h-10 rounded-full border border-black" />
                                    <div>
                                        <p className="font-bold text-sm">{post.userName}</p>
                                        <p className="text-xs text-gray-400">{post.timestamp}</p>
                                    </div>
                                </div>
                                <p className="text-gray-800 font-medium mb-3">{post.content}</p>
                                <div className="flex items-center gap-4 text-xs font-bold text-gray-400">
                                    <button className="flex items-center gap-1 hover:text-red-500"><Heart size={14} /> {post.likes}</button>
                                    <button className="flex items-center gap-1 hover:text-black">Reply</button>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {events.filter(e => e.clubId === club.id && e.status === EventStatus.APPROVED).map(event => (
                         <EventCard 
                            key={event.id}
                            event={event}
                            isAdminView={false}
                            onVolunteer={onVolunteer}
                            volunteerStatus={myVolunteerApps.find(a => a.eventId === event.id)?.status}
                         />
                    ))}
                    {events.filter(e => e.clubId === club.id && e.status === EventStatus.APPROVED).length === 0 && (
                        <div className="col-span-full text-center py-12 text-gray-400">
                             <Calendar size={48} className="mx-auto mb-2 opacity-20" />
                             <p>No upcoming events.</p>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

const LoginPage = ({ onLogin, onSwitchToSignup }: { onLogin: (user: User) => void, onSwitchToSignup: () => void }) => {
    const [email, setEmail] = useState('alex@college.edu');
    const [password, setPassword] = useState('password');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

