                    <div>
                        <label className="block text-xs font-black uppercase mb-1">Password</label>
                        <input 
                            type="password" 
                            className="w-full p-3 border-2 border-black font-bold focus:outline-none focus:ring-4 focus:ring-yellow-200"
                            value={password}
                            onChange={e => setPassword(e.target.value)}
                        />
                    </div>
                    <button disabled={loading} className="w-full bg-black text-white py-4 font-black uppercase tracking-widest hover:bg-gray-800 hover:scale-[1.02] transition-transform">
                        {loading ? <Loader2 className="animate-spin mx-auto" /> : 'Log In'}
