                    <div className="flex gap-2 justify-center">
                        <button onClick={() => setEmail('alex@college.edu')} className="text-[10px] bg-gray-100 px-2 py-1 border border-gray-300 rounded font-bold">Student</button>
                        <button onClick={() => setEmail('coding@college.edu')} className="text-[10px] bg-gray-100 px-2 py-1 border border-gray-300 rounded font-bold">Club Admin</button>
                        <button onClick={() => setEmail('dean@college.edu')} className="text-[10px] bg-gray-100 px-2 py-1 border border-gray-300 rounded font-bold">College Admin</button>
                    </div>
                </div>
            </div>
        </div>
    );
};

