            <div className="bg-white w-full max-w-md p-8 border-4 border-black shadow-[8px_8px_0px_#000]">
                <h1 className="text-4xl font-black mb-2">CLIX.</h1>
                <p className="font-bold text-gray-500 mb-8 uppercase tracking-widest">Campus Life Interface</p>

                {error && <div className="bg-red-100 text-red-600 p-3 mb-4 text-sm font-bold border border-red-200 flex items-center gap-2"><AlertCircle size={16}/> {error}</div>}

                <form onSubmit={handleSubmit} className="space-y-4">
