                    <div>
                        <label className="block text-xs font-black uppercase mb-1">Password</label>
                        <input 
                            type="password" 
                            className="w-full p-3 border-2 border-black font-bold focus:outline-none focus:ring-4 focus:ring-yellow-200"
                            value={password}
                            onChange={e => setPassword(e.target.value)}
