                    <button disabled={loading} className="w-full bg-black text-white py-4 font-black uppercase tracking-widest hover:bg-gray-800 hover:scale-[1.02] transition-transform">
                        {loading ? <Loader2 className="animate-spin mx-auto" /> : 'Log In'}
