const StudentMediaView = ({ user }: { user: User }) => {
    const [mediaList, setMediaList] = useState<MediaPost[]>([]);
    const [commentingId, setCommentingId] = useState<string | null>(null);
    const [newComment, setNewComment] = useState('');

    useEffect(() => {
        api.media.list().then(setMediaList);
    }, []);

    const handleLike = async (mediaId: string) => {
        await api.media.like(mediaId, user.id);
        setMediaList(prev => prev.map(m => {
            if (m.id === mediaId) {
                const likedBy = m.likedBy || [];
                const isLiked = likedBy.includes(user.id);
                return { 
                    ...m, 
                    likedBy: isLiked ? likedBy.filter(id => id !== user.id) : [...likedBy, user.id]
                };
            }
            return m;
        }));
    };

    const handleComment = async (mediaId: string) => {
        if (!newComment.trim()) return;
        const comment: Comment = {
             id: `c${Date.now()}`,
             userId: user.id,
             userName: user.name,
             text: newComment,
             timestamp: 'Just now'
        };
        await api.media.comment(mediaId, comment);
        setMediaList(mediaList.map(m => m.id === mediaId ? {...m, comments: [...(m.comments || []), comment]} : m));
        setNewComment('');
        setCommentingId(null);
    };

    return (
        <div className="animate-in fade-in duration-500 space-y-6">
            <div className="border-b-4 border-black pb-6 mb-8">
                <h2 className="text-4xl md:text-5xl font-black tracking-tighter mb-2">CAMPUS MEDIA</h2>
                <p className="text-gray-500 font-medium">Highlights from past events.</p>
            </div>

            {mediaList.length === 0 ? (
                <div className="text-center py-16 text-gray-400">
                    <ImageIcon size={48} className="mx-auto mb-4 opacity-20"/>
                    <p>No media posts yet.</p>
                </div>
            ) : (
                <div className="space-y-8">
                    {mediaList.map(post => {
                        const isLiked = (post.likedBy || []).includes(user.id);
                        return (
                        <div key={post.id} className="bg-white border-2 border-black shadow-[6px_6px_0px_#000] p-4">
                            <div className="flex items-center gap-3 mb-3 border-b border-gray-100 pb-3">
                                <div className="w-10 h-10 bg-yellow-400 rounded-full border-2 border-black flex items-center justify-center font-black text-sm">
                                    CA
                                </div>
                                <div>
                                    <p className="font-bold text-sm">Club Admin</p>
                                    <p className="text-xs text-gray-400">Posted updates</p>
                                </div>
                            </div>
                            <img src={post.imageUrl} alt={post.caption} className="w-full h-auto border border-black mb-4" />
                            <p className="font-medium text-lg leading-tight mb-3">{post.caption}</p>
                            <div className="flex items-center gap-4 text-sm font-bold text-gray-500 mb-2">
                                <button onClick={() => handleLike(post.id)} className={`flex items-center gap-1 transition active:scale-90 ${isLiked ? 'text-red-600' : 'hover:text-red-500'}`}>
                                    <Heart size={18} fill={isLiked ? "currentColor" : "none"} /> {(post.likedBy || []).length} Likes
                                </button>
                                <button onClick={() => setCommentingId(commentingId === post.id ? null : post.id)} className="flex items-center gap-1 hover:text-black transition">
                                    <MessageSquare size={18} /> {(post.comments || []).length} Comments
                                </button>
                            </div>

                            {commentingId === post.id && (
                                <div className="mt-4 bg-gray-50 p-3 border border-gray-200">
                                    <div className="space-y-2 mb-3 max-h-40 overflow-y-auto">
                                        {(post.comments || []).map(c => (
                                            <div key={c.id} className="text-sm">
                                                <span className="font-bold">{c.userName}: </span>
                                                <span className="text-gray-700">{c.text}</span>
                                            </div>
                                        ))}
                                    </div>
                                    <div className="flex gap-2">
                                        <input 
                                            type="text" 
                                            className="flex-1 border border-gray-300 p-2 text-sm focus:outline-none focus:border-black"
                                            placeholder="Write a comment..."
                                            value={newComment}
                                            onChange={e => setNewComment(e.target.value)}
                                        />
                                        <button onClick={() => handleComment(post.id)} className="bg-black text-white px-3 py-1 text-xs font-bold uppercase">Post</button>
                                    </div>
                                </div>
                            )}
                        </div>
                    );
                    })}
                </div>
            )}
        </div>
    );
};

const ClubAdminDashboard = ({ user, refreshData, activeTab }: { user: User, refreshData: () => void, activeTab: string }) => {
    const [events, setEvents] = useState<Event[]>([]);
    const [announcements, setAnnouncements] = useState<Announcement[]>([]);
    const [announcementText, setAnnouncementText] = useState('');
    const [mediaList, setMediaList] = useState<MediaPost[]>([]);
    const [isPosting, setIsPosting] = useState(false);

    // Proposal State
    const [isProposalModalOpen, setIsProposalModalOpen] = useState(false);
    const [proposalTopic, setProposalTopic] = useState('');
    const [generatedDesc, setGeneratedDesc] = useState('');
    const [isGenerating, setIsGenerating] = useState(false);
    const [newProposal, setNewProposal] = useState<Partial<Event>>({
      title: '', description: '', date: '', time: '', venueId: '', capacity: 0, price: 0, volunteersNeeded: false, image: ''
    });
    const [venues, setVenues] = useState<Venue[]>([]);
    const [editingEventId, setEditingEventId] = useState<string | null>(null);

    // Media Upload State
    const [mediaEventId, setMediaEventId] = useState('');
    const [mediaUrl, setMediaUrl] = useState('');
    const [mediaCaption, setMediaCaption] = useState('');

    // Winners Poster State
    const [posterEvent, setPosterEvent] = useState<Event | null>(null);
    const [winners, setWinners] = useState<Winner[]>([
        { rank: 1, name: '', photo: '' },
        { rank: 2, name: '', photo: '' },
        { rank: 3, name: '', photo: '' }
    ]);
    const [generatedPoster, setGeneratedPoster] = useState(false);

    useEffect(() => {
        api.events.list().then(setEvents);
        api.venues.list().then(setVenues);
        if (user.clubId) {
            api.announcements.list(user.clubId).then(setAnnouncements);
        }
        api.media.list().then(m => setMediaList(m.filter(x => x.clubId === user.clubId)));
    }, [user.clubId]);

    const handleAddAnnouncement = async () => {
        if(!user.clubId || !announcementText.trim()) return;
        setIsPosting(true);
        try {
            const ann: Announcement = {
                id: `a${Date.now()}`,
                clubId: user.clubId,
                content: announcementText,
                date: new Date().toISOString()
            };
            await api.announcements.create(ann);
            setAnnouncements([ann, ...announcements]);
            setAnnouncementText('');
            alert("Announcement Posted!");
        } catch(e) {
            alert("Failed to post announcement");
        } finally {
            setIsPosting(false);
        }
    };

    const handleAiGenerate = async () => {
        if (!proposalTopic) return;
        setIsGenerating(true);
        const desc = await generateEventContent(proposalTopic, 'description');
        setGeneratedDesc(desc);
        setNewProposal({ ...newProposal, description: desc });
        setIsGenerating(false);
    };

    const handleSubmitProposal = async (e: React.FormEvent) => {
        e.preventDefault();

        // If editing existing rejected event, update it. Else create new.
        if (editingEventId) {
            const existingEvent = events.find(e => e.id === editingEventId);
            if (existingEvent) {
                const updatedEvent: Event = {
                    ...existingEvent,
                    ...newProposal,
                    title: newProposal.title || existingEvent.title,
                    description: newProposal.description || existingEvent.description,
                    date: newProposal.date || existingEvent.date,
                    time: newProposal.time || existingEvent.time,
                    venueId: newProposal.venueId || existingEvent.venueId,
                    capacity: newProposal.capacity || existingEvent.capacity,
                    price: newProposal.price || existingEvent.price,
                    image: newProposal.image || existingEvent.image,
                    volunteersNeeded: newProposal.volunteersNeeded,
                    status: EventStatus.PENDING, // Reset status to PENDING for review
                    rejectionReason: undefined // Clear reason
                } as Event;
                await api.events.update(updatedEvent);
                alert("Proposal updated and re-submitted for approval.");
            }
        } else {
             const event: Event = {
                id: `e${Date.now()}`,
                title: newProposal.title || 'Untitled Event',
                description: newProposal.description || generatedDesc || 'No description provided.',
                organizer: 'My Club', 
                clubId: user.clubId || 'c1',
                date: newProposal.date || '2024-01-01',
                time: newProposal.time || '12:00',
                venueId: newProposal.venueId || 'v1',
                status: EventStatus.PENDING,
                capacity: newProposal.capacity || 100,
                registeredCount: 0,
                tags: ['New'],
                price: newProposal.price || 0,
                image: newProposal.image || `https://picsum.photos/800/400?random=${Date.now()}`,
                volunteersNeeded: newProposal.volunteersNeeded
            };
            await api.events.create(event);
            alert("Proposal submitted for College Admin approval.");
        }

        setIsProposalModalOpen(false);
        setNewProposal({});
        setEditingEventId(null);
        setProposalTopic('');
        setGeneratedDesc('');
        refreshData(); 

        const updatedEvents = await api.events.list();
        setEvents(updatedEvents);
    };

    const handleEditEvent = (event: Event) => {
        setEditingEventId(event.id);
        setNewProposal({
            title: event.title,
            description: event.description,
            date: event.date,
            time: event.time,
            venueId: event.venueId,
            capacity: event.capacity,
            price: event.price,
            image: event.image,
            volunteersNeeded: event.volunteersNeeded
        });
        setIsProposalModalOpen(true);
    };

    const handleUploadMedia = async (e: React.FormEvent) => {
        e.preventDefault();
        if(!mediaEventId || !mediaUrl || !user.clubId) return;
        const newMedia: MediaPost = {
            id: `m${Date.now()}`,
            clubId: user.clubId,
            eventId: mediaEventId,
            imageUrl: mediaUrl,
            caption: mediaCaption || 'Event Highlights',
            likedBy: [],
            comments: []
        };
        await api.media.create(newMedia);
        setMediaList([...mediaList, newMedia]);
        setMediaUrl('');
        setMediaEventId('');
        setMediaCaption('');
        alert("Media Uploaded!");
    };

    const handleIssueCertificates = async (event: Event) => {
        if(confirm(`Issue certificates to all ${event.registeredCount} participants for ${event.title}?`)) {
            await api.events.issueCertificates(event.id);
            setEvents(events.map(e => e.id === event.id ? {...e, certificatesIssued: true} : e));
            alert("Certificates Issued!");
        }
    };

    const handleGeneratePoster = async () => {
        if (!posterEvent) return;
        // Save winners to event
        await api.events.saveWinners(posterEvent.id, winners);
        setGeneratedPoster(true);
    };

    const analyticsData = [
      { name: 'Hackathon', participants: 150 },
      { name: 'AI Talk', participants: 80 },
      { name: 'Web Dev', participants: 200 },
    ];

    return (
      <div className="space-y-8 animate-in fade-in duration-500">

        {activeTab === 'dashboard' && (
            <div className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="bg-black text-yellow-400 p-8 shadow-[8px_8px_0px_#FACC15] border-2 border-black">
                        <h3 className="text-sm font-bold opacity-80 uppercase tracking-widest mb-2">Total Reach</h3>
                        <p className="text-5xl font-black">1,240</p>
                    </div>
                    <div className="bg-white text-black p-8 shadow-[8px_8px_0px_#000] border-2 border-black">
                        <h3 className="text-sm font-bold text-gray-500 uppercase tracking-widest mb-2">Avg Rating</h3>
                        <p className="text-5xl font-black">4.8</p>
                    </div>
                </div>

                <div className="bg-white border-2 border-black p-6 shadow-sm">
                    <h3 className="text-xl font-black mb-4 flex items-center gap-2"><Megaphone size={24} /> POST ANNOUNCEMENT</h3>
                    <div className="flex gap-4">
                        <textarea 
                        className="flex-1 p-3 border-2 border-gray-200 focus:border-black focus:outline-none font-medium" 
                        rows={2}
                        placeholder="Share updates with your club members..."
                        value={announcementText}
                        onChange={e => setAnnouncementText(e.target.value)}
                        />
                        <button 
                        onClick={handleAddAnnouncement}
                        disabled={isPosting}
                        className="bg-black text-white px-6 font-bold uppercase tracking-widest hover:bg-gray-800 disabled:opacity-50"
                        >
                            {isPosting ? <Loader2 className="animate-spin" /> : 'Post'}
                        </button>
                    </div>
                    <div className="mt-4 space-y-2">
                        {announcements.map(a => (
                            <div key={a.id} className="bg-gray-50 p-2 border-l-4 border-yellow-400 text-sm">
                                {a.content} <span className="text-gray-400 text-xs ml-2">{new Date(a.date).toLocaleDateString()}</span>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="bg-white p-8 border-2 border-black shadow-sm">
                    <h3 className="text-xl font-black mb-6 border-b-2 border-gray-100 pb-4">PARTICIPATION ANALYTICS</h3>
                    <div className="h-64 w-full">
                        <ResponsiveContainer width="100%" height="100%">
