const App = () => {
  const [user, setUser] = useState<User | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [authView, setAuthView] = useState<'login' | 'signup'>('login');

  const [activeTab, setActiveTab] = useState('feed');
  const [events, setEvents] = useState<Event[]>([]);
  const [clubs, setClubs] = useState<Club[]>([]);
  const [userRegistrations, setUserRegistrations] = useState<string[]>([]);
  const [volunteerApps, setVolunteerApps] = useState<VolunteerApplication[]>([]);

  // Search state
  const [searchQuery, setSearchQuery] = useState('');
  const [filterPrice, setFilterPrice] = useState<'all' | 'free' | 'paid'>('all');

  // Modals
  const [selectedEvent, setSelectedEvent] = useState<Event | null>(null);
  const [paymentOpen, setPaymentOpen] = useState(false);
  const [qrOpen, setQrOpen] = useState(false);
  const [certOpen, setCertOpen] = useState(false);

  useEffect(() => {
    if(isAuthenticated) fetchData();
  }, [user, isAuthenticated]);

  const fetchData = async () => {
    if (!user) return;
    try {
        const e = await api.events.list();
        setEvents(e);
        const c = await api.clubs.list();
        setClubs(c);
        if (api.auth.getRegistrations) {
            const regs = await api.auth.getRegistrations(user.id);
            setUserRegistrations(regs);
        }
        const vApps = await api.volunteers.listByUser(user.id);
        setVolunteerApps(vApps);
    } catch (err) {
        console.error("Failed to fetch data", err);
    }
  };

  const handleLogin = (u: User) => {
      setUser(u);
      setIsAuthenticated(true);
      if (u.role === UserRole.STUDENT) setActiveTab('feed');
      else if (u.role === UserRole.CLUB_ADMIN) setActiveTab('dashboard');
      else if (u.role === UserRole.COLLEGE_ADMIN) setActiveTab('approvals');
  };

  const handleLogout = () => {
      setIsAuthenticated(false);
      setUser(null);
      setAuthView('login');
  };

  const handleSwitchRole = async (role: UserRole) => {
      try {
        const targetUser = await api.auth.loginAsRole(role);
        if (targetUser) {
            setUser(targetUser);
            if (role === UserRole.STUDENT) setActiveTab('feed');
            else if (role === UserRole.CLUB_ADMIN) setActiveTab('dashboard');
            else if (role === UserRole.COLLEGE_ADMIN) setActiveTab('approvals');
        }
      } catch(e) {
          alert("No demo user found for this role in DB. Please create one manually via Supabase.");
      }
  };

  const handleRegister = async (event: Event) => {
      if(!user) return;
      if (event.price > 0) {
          setSelectedEvent(event);
          setPaymentOpen(true);
      } else {
          await confirmRegistration(event);
      }
  };

  const confirmRegistration = async (event: Event) => {
      if(!user) return;
      await api.events.register(event.id, user.id);
      setUserRegistrations(prev => [...prev, event.id]);
      setEvents(prev => prev.map(e => e.id === event.id ? {...e, registeredCount: e.registeredCount + 1} : e));
      if (paymentOpen) setPaymentOpen(false);
  };

  const handleVolunteerApply = async (eventId: string) => {
      if(!user) return;
      try {
          const app: VolunteerApplication = {
              id: `v${Date.now()}`,
              eventId,
              userId: user.id,
              userName: user.name,
              userAvatar: user.avatar,
              status: VolunteerStatus.PENDING,
              appliedAt: new Date().toISOString()
          };
          await api.volunteers.apply(app);
          setVolunteerApps(prev => [...prev, app]);
      } catch (e: any) {
          alert(e.message);
      }
  };

  // Auth Views
  if (!isAuthenticated) {
      return authView === 'login' 
        ? <LoginPage onLogin={handleLogin} onSwitchToSignup={() => setAuthView('signup')} />
        : <SignupPage onSignup={(u) => { setUser(u); setIsAuthenticated(true); setActiveTab('feed'); }} onSwitchToLogin={() => setAuthView('login')} />;
  }

  // Filtered Events for Feed
  const filteredEvents = events.filter(e => {
        if (e.status !== EventStatus.APPROVED) return false;
        if (filterPrice === 'free' && e.price > 0) return false;
        if (filterPrice === 'paid' && e.price === 0) return false;
        const query = searchQuery.toLowerCase();
        return (
          e.title.toLowerCase().includes(query) || 
          e.description.toLowerCase().includes(query) ||
          e.tags.some(tag => tag.toLowerCase().includes(query))
        );
  });

  if (!user) return null;

  return (
    <Layout user={user} onLogout={handleLogout} onSwitchRole={handleSwitchRole} activeTab={activeTab} setActiveTab={setActiveTab}>

      {/* STUDENT VIEW */}
      {user.role === UserRole.STUDENT && (
        <>
           {activeTab === 'feed' && (
               <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                   <div className="flex flex-col gap-4 border-b-4 border-black pb-6">
                      <div className="flex justify-between items-end">
                         <div>
                            <h2 className="text-4xl md:text-5xl font-black tracking-tighter mb-2">WHATS ON<span className="text-yellow-500">?</span></h2>
                            <p className="text-gray-500 font-medium">Discover and join campus activities.</p>
                         </div>
                      </div>
                      <div className="flex flex-col md:flex-row gap-4">
                         <div className="relative flex-1">
                            <input 
                            type="text" 
                            placeholder="Search events, tags..." 
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="pl-10 pr-4 py-3 border-2 border-black focus:outline-none focus:ring-4 focus:ring-yellow-400 w-full font-bold bg-white"
                            />
                            <Search className="absolute left-3 top-3.5 text-black" size={20} />
                         </div>
                         <div className="flex items-center gap-2">
                             <Filter size={20} className="text-gray-500" />
                             <select 
                                className="p-3 border-2 border-black font-bold bg-white focus:outline-none focus:ring-4 focus:ring-yellow-400"
                                value={filterPrice}
                                onChange={(e) => setFilterPrice(e.target.value as any)}
                             >
                                 <option value="all">All Prices</option>
                                 <option value="free">Free Only</option>
                                 <option value="paid">Paid Only</option>
                             </select>
                         </div>
                      </div>
                   </div>

                   <div className="grid gap-6">
                       {filteredEvents.map(event => (
                           <EventCard 
                             key={event.id} 
                             event={event} 
                             isAdminView={false}
                             isRegistered={userRegistrations.includes(event.id)}
                             onRegister={handleRegister}
                             venueName={event.venueId} 
                             onVolunteer={handleVolunteerApply}
                             volunteerStatus={volunteerApps.find(v => v.eventId === event.id)?.status}
                           />
                       ))}
                       {filteredEvents.length === 0 && <div className="text-center py-10 text-gray-400">No events found.</div>}
                   </div>
               </div>
           )}
           {activeTab === 'media' && <StudentMediaView user={user} />}
           {activeTab === 'clubs' && (
               <div className="grid grid-cols-1 gap-4">
                   {clubs.map(club => (
                       <div key={club.id} className="bg-white border-2 border-black p-4 flex gap-4">
                           <img src={club.logo} className="w-16 h-16 border border-black object-cover" />
                           <div>
                               <h3 className="font-black text-lg">{club.name}</h3>
                               <p className="text-sm text-gray-600 line-clamp-2">{club.description}</p>
                               <div className="mt-2 text-xs font-bold text-gray-400">{club.memberCount} Members</div>
                           </div>
                       </div>
                   ))}
               </div>
           )}
           {activeTab === 'tickets' && (
               <div className="space-y-4">
                   <h2 className="text-2xl font-black">MY TICKETS</h2>
                   {events.filter(e => userRegistrations.includes(e.id)).map(event => (
                       <div key={event.id} className="bg-white border-2 border-black p-4 flex justify-between items-center group cursor-pointer hover:bg-yellow-50" onClick={() => { setSelectedEvent(event); setQrOpen(true); }}>
                           <div>
                               <h3 className="font-black">{event.title}</h3>
                               <p className="text-xs text-gray-500">{event.date} | {event.time}</p>
                           </div>
                           <QrCode size={32} />
                       </div>
                   ))}
                   {userRegistrations.length === 0 && <p className="text-gray-500">No tickets yet.</p>}

                   <h2 className="text-2xl font-black mt-8">CERTIFICATES</h2>
                   {events.filter(e => userRegistrations.includes(e.id) && e.certificatesIssued).map(event => (
                        <div key={event.id} className="bg-green-50 border-2 border-green-800 p-4 flex justify-between items-center cursor-pointer" onClick={() => { setSelectedEvent(event); setCertOpen(true); }}>
                            <div>
                               <h3 className="font-black text-green-900">{event.title}</h3>
                               <p className="text-xs text-green-700">Completed</p>
                           </div>
                           <Award size={32} className="text-green-800"/>
                        </div>
                   ))}
               </div>
           )}
           {activeTab === 'profile' && (
               <div className="bg-white border-2 border-black p-6 text-center">
                   <img src={user.avatar} className="w-32 h-32 rounded-full border-4 border-black mx-auto mb-4" />
                   <h2 className="text-2xl font-black">{user.name}</h2>
                   <p className="text-gray-500 font-bold">{user.email}</p>
                   <div className="mt-6 flex justify-center gap-4">
                       <div className="text-center">
                           <p className="font-black text-xl">{userRegistrations.length}</p>
                           <p className="text-xs uppercase text-gray-400">Events</p>
                       </div>
                       <div className="text-center">
                           <p className="font-black text-xl">{(user.joinedClubIds || []).length}</p>
                           <p className="text-xs uppercase text-gray-400">Clubs</p>
                       </div>
                   </div>
                   <button onClick={handleLogout} className="mt-8 bg-red-500 text-white px-6 py-2 font-bold uppercase tracking-widest hover:bg-red-600 flex items-center gap-2 mx-auto"><LogOut size={16}/> Logout</button>
               </div>
           )}
        </>
      )}

      {/* CLUB ADMIN VIEW */}
      {user.role === UserRole.CLUB_ADMIN && (
          activeTab === 'profile' ? (
              <div className="bg-white border-2 border-black p-6 text-center">
                 <img src={user.avatar} className="w-32 h-32 rounded-full border-4 border-black mx-auto mb-4" />
                 <h2 className="text-2xl font-black">{user.name}</h2>
                 <p className="text-gray-500 font-bold">Club Admin</p>
                 <button onClick={handleLogout} className="mt-8 bg-red-500 text-white px-6 py-2 font-bold uppercase tracking-widest hover:bg-red-600 flex items-center gap-2 mx-auto"><LogOut size={16}/> Logout</button>
              </div>
          ) : (
              <ClubAdminDashboard user={user} refreshData={fetchData} activeTab={activeTab} />
          )
      )}

      {/* COLLEGE ADMIN VIEW */}
      {user.role === UserRole.COLLEGE_ADMIN && (
        <div className="space-y-6">
            {activeTab === 'approvals' && (
                <>
                    <h2 className="text-3xl font-black mb-6">PENDING APPROVALS</h2>
                    {events.filter(e => e.status === EventStatus.PENDING).length === 0 && <p className="text-gray-500">No pending events.</p>}
