                                 <div className="bg-yellow-400 text-black px-4 py-1.5 font-bold text-sm uppercase mb-1">Winner</div>
                                 <p className="font-bold text-xl">{winners[0].name}</p>
                             </div>
                              {/* 3rd Place */}
