    const [events, setEvents] = useState<Event[]>([]);
    const [media, setMedia] = useState<MediaPost[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const load = async () => {
            setLoading(true);
            try {
                const anns = await api.announcements.list(club.id);
