// --- Main Event Card ---

interface EventCardProps {
    event: Event;
    onRegister?: (event: Event) => void;
    isRegistered?: boolean;
    isAdminView: boolean;
    onApprove?: (id: string) => void;
    onReject?: (id: string, reason: string) => void;
    venueName?: string;
    onVolunteer?: (id: string) => void;
    volunteerStatus?: VolunteerStatus | null;
    onManageVolunteers?: (event: Event) => void;
    onGeneratePoster?: (event: Event) => void;
    onIssueCertificates?: (event: Event) => void;
    onEdit?: (event: Event) => void; // For re-application
    onClick?: () => void;
}

const EventCard = ({ 
    event, onRegister, isRegistered, isAdminView, onApprove, onReject, venueName, 
    onVolunteer, volunteerStatus, onManageVolunteers, onGeneratePoster, onIssueCertificates, onEdit, onClick
}: EventCardProps) => {
  const [loadingAction, setLoadingAction] = useState<string | null>(null);
  const [rejectReason, setRejectReason] = useState('');
  const [showRejectInput, setShowRejectInput] = useState(false);

  const showAdminActions = isAdminView && 
    event.status === EventStatus.PENDING && 
    typeof onApprove === 'function' && 
    typeof onReject === 'function';

  return (
    <div 
        className={`bg-white border-2 border-black shadow-[4px_4px_0px_rgba(0,0,0,1)] hover:shadow-[8px_8px_0px_rgba(250,204,21,1)] hover:-translate-y-1 transition-all duration-200 flex flex-col h-full group relative overflow-hidden ${onClick ? 'cursor-pointer' : ''}`}
        onClick={(e) => {
            // Prevent triggering card click when clicking interactive buttons inside
            if ((e.target as HTMLElement).closest('button') || (e.target as HTMLElement).closest('textarea') || (e.target as HTMLElement).closest('input')) return;
            if (onClick) onClick();
        }}
    >
      <div className="absolute top-0 right-0 w-16 h-16 bg-yellow-400 rotate-45 translate-x-8 -translate-y-8 z-10"></div>

      <div className="h-48 overflow-hidden relative bg-gray-900 border-b-2 border-black">
        <img 
          src={event.image || `https://picsum.photos/800/400?random=${event.id}`} 
          alt={event.title} 
          onError={(e) => {
              // Fallback if image fails
              e.currentTarget.src = "https://via.placeholder.com/800x400/000000/FACC15?text=CLIX+EVENT";
          }}
          className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500 opacity-80 group-hover:opacity-100"
        />
        <div className="absolute top-3 right-3 z-20">
            <StatusBadge status={event.status} />
        </div>
        {event.price > 0 ? (
           <div className="absolute bottom-3 right-3 bg-black text-yellow-400 px-3 py-1 text-xs font-extrabold border border-yellow-400 shadow-sm">
             ₹{event.price}
           </div>
        ) : (
           <div className="absolute bottom-3 right-3 bg-yellow-400 text-black px-3 py-1 text-xs font-extrabold border border-black shadow-sm">
             FREE
           </div>
        )}
      </div>

      <div className="p-5 flex-1 flex flex-col">
        <div className="mb-3 flex items-center justify-between">
           <div className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest border border-gray-200 px-2 py-0.5 rounded-full inline-block">
             {event.organizer}
           </div>
           <div className="text-[10px] font-bold text-gray-400 flex items-center gap-1">
             <Users size={12} /> {event.capacity - event.registeredCount} spots left
           </div>
        </div>

        <h3 className="text-2xl font-black mb-3 leading-none tracking-tight">{event.title}</h3>
        <p className="text-gray-600 text-sm mb-5 line-clamp-2 font-medium">{event.description}</p>

        {event.status === EventStatus.REJECTED && event.rejectionReason && (
            <div className="mb-4 bg-red-50 border-l-4 border-red-500 p-2">
                <p className="text-xs font-bold text-red-500 uppercase">Reason for Rejection:</p>
                <p className="text-sm text-gray-700">{event.rejectionReason}</p>
            </div>
        )}

        <div className="space-y-3 mt-auto text-sm text-black font-semibold">
          <div className="flex items-center">
            <Calendar size={16} className="mr-3 text-yellow-500" />
            {event.date}
          </div>
          <div className="flex items-center">
            <Clock size={16} className="mr-3 text-yellow-500" />
            {event.time}
          </div>
          <div className="flex items-center">
            <MapPin size={16} className="mr-3 text-yellow-500" />
            {venueName || 'TBD'}
          </div>
        </div>
      </div>

      <div className="p-4 pt-0 mt-2">
        {isAdminView ? (
          showAdminActions ? (
            <div className="space-y-2 pt-2">
               {showRejectInput ? (
                   <div className="space-y-2 animate-in slide-in-from-bottom duration-200">
                       <textarea 
                          placeholder="Reason for rejection..." 
                          className="w-full p-2 text-sm border-2 border-black focus:outline-none"
                          value={rejectReason}
                          onChange={e => setRejectReason(e.target.value)}
                          rows={2}
                       />
                       <div className="flex gap-2">
                           <button 
                             onClick={async () => { 
                                 setLoadingAction('reject'); 
                                 await onReject!(event.id, rejectReason); 
                                 setLoadingAction(null); 
                                 setShowRejectInput(false);
                            }} 
                             className="flex-1 bg-red-500 text-white text-xs font-bold py-2 hover:bg-red-600"
                           >
                               Confirm Reject
                           </button>
                           <button onClick={() => setShowRejectInput(false)} className="px-3 bg-gray-200 text-xs font-bold">Cancel</button>
                       </div>
                   </div>
               ) : (
                <div className="flex space-x-2">
                    <button 
                        onClick={async () => { setLoadingAction('approve'); await onApprove!(event.id); setLoadingAction(null); }} 
                        className="flex-1 bg-black text-yellow-400 py-3 text-sm font-bold hover:bg-gray-900 transition border-2 border-black flex items-center justify-center"
                    >
                        {loadingAction === 'approve' ? <Loader2 className="animate-spin" size={16}/> : 'Approve'}
                    </button>
                    <button 
                        onClick={() => setShowRejectInput(true)} 
                        className="flex-1 bg-white border-2 border-black text-black py-3 text-sm font-bold hover:bg-red-50 hover:border-red-500 hover:text-red-500 transition flex items-center justify-center"
                    >
                        Reject
                    </button>
                </div>
               )}
            </div>
          ) : (
             <div className="space-y-2">
                 {/* Only show 'Manage' as a hint if clicking card opens management, or show specific actions if not */}
                 {event.status === EventStatus.APPROVED && onClick && (
                    <div className="w-full py-3 text-sm font-bold uppercase tracking-widest bg-white border-2 border-black text-black hover:bg-yellow-50 transition flex items-center justify-center gap-2 mt-2 group-hover:bg-yellow-400 group-hover:border-black">
                       <Eye size={16}/> View & Manage
                    </div>
                 )}

                 {/* Keep Poster/Cert actions accessible directly too */}
                 {(event.status === EventStatus.COMPLETED || new Date(event.date) < new Date()) && onGeneratePoster && onIssueCertificates && (
                    <div className="flex flex-col gap-2 pt-2">
                        <button 
                             onClick={() => onGeneratePoster(event)}
                             className="w-full py-2 text-xs font-bold uppercase tracking-widest bg-yellow-400 border-2 border-black text-black hover:bg-yellow-300 flex items-center justify-center gap-2"
                        >
                            <Trophy size={14}/> Generate Winners Poster
                        </button>
                        <button 
                             onClick={() => onIssueCertificates(event)}
                             disabled={event.certificatesIssued}
                             className={`w-full py-2 text-xs font-bold uppercase tracking-widest border-2 border-black flex items-center justify-center gap-2 ${event.certificatesIssued ? 'bg-green-100 text-green-700 border-green-300' : 'bg-white text-black hover:bg-gray-100'}`}
                        >
                            {event.certificatesIssued ? <><Check size={14}/> Certificates Issued</> : <><Award size={14}/> Issue Certificates</>}
                        </button>
                    </div>
                 )}
                 {event.status === EventStatus.REJECTED && onEdit && (
                     <button 
                        onClick={() => onEdit(event)}
                        className="w-full py-3 text-sm font-bold uppercase tracking-widest bg-black text-white hover:bg-gray-800 transition mt-2"
                     >
                        Edit & Reapply
                     </button>
                 )}
             </div>
          )
        ) : (
          <div className="space-y-2">
             <button 
                onClick={async () => { 
                  if (onRegister) {
                    setLoadingAction('reg'); 
                    await onRegister(event); 
                    setLoadingAction(null); 
                  }
                }}
                disabled={isRegistered || event.status !== EventStatus.APPROVED || loadingAction === 'reg'}
                className={`w-full py-3 text-sm font-black uppercase tracking-widest transition-all border-2 border-black shadow-[2px_2px_0px_rgba(0,0,0,1)] active:shadow-none active:translate-x-[2px] active:translate-y-[2px] flex items-center justify-center gap-2 ${
                  isRegistered 
                    ? 'bg-gray-100 text-gray-400 border-gray-200 shadow-none cursor-not-allowed' 
                    : event.status !== EventStatus.APPROVED 
                      ? 'bg-gray-100 text-gray-400 border-gray-200 shadow-none cursor-not-allowed'
                      : 'bg-yellow-400 text-black hover:bg-yellow-300'
                }`}
              >
                {loadingAction === 'reg' ? <Loader2 className="animate-spin" size={16}/> : (isRegistered ? 'Ticket Confirmed' : event.status !== EventStatus.APPROVED ? 'Coming Soon' : (event.price > 0 ? `Book Ticket (₹${event.price})` : 'Get Ticket'))}
              </button>

              {!isRegistered && event.status === EventStatus.APPROVED && event.volunteersNeeded && (
                <button 
                  onClick={async () => {
                     if (volunteerStatus) return; 
                     setLoadingAction('vol');
                     if (onVolunteer) await onVolunteer(event.id);
                     setLoadingAction(null);
                  }}
                  disabled={!!volunteerStatus || loadingAction === 'vol'}
                  className={`w-full py-2 text-xs font-bold uppercase tracking-wider flex items-center justify-center gap-2 ${
                     volunteerStatus 
                       ? 'text-green-600 bg-green-50 border border-green-200 cursor-default'
                       : 'text-gray-500 hover:text-black hover:bg-gray-100'
                  }`}
                >
                  {loadingAction === 'vol' ? <Loader2 className="animate-spin" size={14}/> : (
                      volunteerStatus ? (
                          <>
                            <Check size={14} /> {volunteerStatus === VolunteerStatus.PENDING ? 'Application Pending' : 'Volunteer Accepted'}
                          </>
                      ) : (
                          <>
                            <Hand size={14} /> Volunteer
                          </>
                      )
                  )}
                </button>
              )}
          </div>
        )}
      </div>
    </div>
  );
};

