                                             </div>
                                             <p className="text-sm mb-4">{post.content}</p>

                                             <div className="flex items-center gap-4 border-t border-gray-100 pt-2">
                                                 <button 
                                                    onClick={() => handleLikePost(post)}
                                                    className={`flex items-center gap-1 text-xs font-bold ${isLiked ? 'text-blue-600' : 'text-gray-500 hover:text-black'}`}
                                                 >
                                                     <ThumbsUp size={14} /> {post.likedBy.length} Likes
                                                 </button>
                                                 <button 
                                                    onClick={() => setCommentingPostId(commentingPostId === post.id ? null : post.id)}
                                                    className="flex items-center gap-1 text-xs font-bold text-gray-500 hover:text-black"
                                                 >
                                                     <MessageSquare size={14} /> {post.comments.length} Comments
                                                 </button>
                                             </div>

                                             {/* Comments Section */}
                                             {commentingPostId === post.id && (
                                                 <div className="mt-3 pt-3 border-t border-dashed border-gray-200">
                                                     <div className="space-y-2 mb-3 max-h-40 overflow-y-auto">
                                                         {post.comments.map(c => (
                                                             <div key={c.id} className="text-xs bg-gray-50 p-2">
                                                                 <span className="font-bold">{c.userName}: </span>
                                                                 <span>{c.text}</span>
