                           ) : (
                               <p className="mt-4 text-gray-400 text-xs italic">No bio added.</p>
                           )}

                           <div className="mt-6 flex justify-center gap-8 w-full border-t-2 border-dashed border-gray-200 pt-6">
                               <div className="text-center">
                                   <p className="font-black text-2xl">{userRegistrations.length}</p>
                                   <p className="text-[10px] uppercase font-bold text-gray-400 tracking-widest">Events</p>
                               </div>
