          event={selectedEvent} 
          user={user} 
      />
      <CertificateModal 
          isOpen={certOpen} 
          onClose={() => setCertOpen(false)} 
          event={selectedEvent} 
          user={user} 
      />
      <FeedbackModal
          isOpen={!!feedbackEvent}
          onClose={() => setFeedbackEvent(null)}
          event={feedbackEvent}
          onSubmit={handleFeedbackSubmit}
      />

      {/* Edit Profile Modal */}
      {user && (
          <EditProfileModal 
              isOpen={isEditProfileOpen}
              onClose={() => setIsEditProfileOpen(false)}
              user={user}
              onUpdate={handleUpdateProfile}
          />
      )}

    </Layout>
  );
};

