const StudentClubDetail = ({ club, onBack, user, onUpdateUser }: { club: Club, onBack: () => void, user: User, onUpdateUser: (u: User) => void }) => {
    const [activeTab, setActiveTab] = useState<'overview' | 'discussion'>('overview');
    const [announcements, setAnnouncements] = useState<Announcement[]>([]);
    const [events, setEvents] = useState<Event[]>([]);
    const [media, setMedia] = useState<MediaPost[]>([]);
    const [loading, setLoading] = useState(true);
    const [loadingJoin, setLoadingJoin] = useState(false);

    // Discussion State
    const [posts, setPosts] = useState<Post[]>([]);
    const [newPostContent, setNewPostContent] = useState('');
    const [loadingPost, setLoadingPost] = useState(false);
    const [commentingPostId, setCommentingPostId] = useState<string | null>(null);
    const [newComment, setNewComment] = useState('');

    const isMember = (user.joinedClubIds || []).includes(club.id);

    useEffect(() => {
        const load = async () => {
            setLoading(true);
            try {
                // Parallel fetching with club-specific filtering for speed
                const [anns, evs, meds] = await Promise.all([
                    api.announcements.list(club.id),
                    api.events.list(club.id),
                    api.media.list(club.id)
                ]);

                setAnnouncements(anns);
                setEvents(evs);
                setMedia(meds);

                if (isMember) {
                    const clubPosts = await api.posts.list(club.id);
                    setPosts(clubPosts);
                }
            } finally {
                setLoading(false);
            }
        };
        load();
    }, [club.id, isMember]);

    const handleJoinToggle = async () => {
        const wasMember = isMember;
        // Optimistic UI Update
        const newJoinedIds = wasMember
            ? (user.joinedClubIds || []).filter(id => id !== club.id)
            : [...(user.joinedClubIds || []), club.id];

        const optimisticUser = { ...user, joinedClubIds: newJoinedIds };
        onUpdateUser(optimisticUser);

        setLoadingJoin(true);
        try {
            let updatedUser;
            if (wasMember) {
                updatedUser = await api.clubs.leave(club.id, user.id);
            } else {
                updatedUser = await api.clubs.join(club.id, user.id);
            }
            onUpdateUser(updatedUser);
        } catch (e: any) {
            // Revert on error
            onUpdateUser(user);
            alert(e.message);
        } finally {
            setLoadingJoin(false);
        }
    };

    const handleCreatePost = async () => {
        if (!newPostContent.trim()) return;

        // Optimistic UI Update
        const tempId = `temp-${Date.now()}`;
        const newPost: Post = {
            id: tempId,
            clubId: club.id,
            userId: user.id,
            userName: user.name,
            userAvatar: user.avatar || '',
            content: newPostContent,
            timestamp: new Date().toISOString(),
            likedBy: [],
            comments: []
        };

        setPosts([newPost, ...posts]);
        setNewPostContent('');

        try {
            // Create real post (Mock API accepts full object)
            // In a real app, backend assigns ID, here client does or we overwrite
            const postToCreate = { ...newPost, id: `p${Date.now()}` }; 
            await api.posts.create(postToCreate);

            // Update state with confirmed post (swapping temp ID)
            setPosts(current => current.map(p => p.id === tempId ? postToCreate : p));
        } catch (e: any) {
            // Revert
            setPosts(current => current.filter(p => p.id !== tempId));
            alert("Failed to create post");
        }
    };

    const handleLikePost = async (post: Post) => {
        // Optimistic Like
        const isLiked = post.likedBy.includes(user.id);
        const newLikedBy = isLiked ? post.likedBy.filter(id => id !== user.id) : [...post.likedBy, user.id];

        setPosts(posts.map(p => p.id === post.id ? { ...p, likedBy: newLikedBy } : p));

        // API call in background
        await api.posts.like(post.id, user.id);
    };

    const handleAddComment = async (postId: string) => {
        if (!newComment.trim()) return;

        const comment: Comment = {
            id: `c${Date.now()}`,
            userId: user.id,
            userName: user.name,
            text: newComment,
            timestamp: new Date().toISOString()
        };

        // Optimistic Comment
        setPosts(posts.map(p => p.id === postId ? { ...p, comments: [...p.comments, comment] } : p));
        setNewComment('');
        setCommentingPostId(null);

        await api.posts.comment(postId, comment);
    };

    if (loading) return <div className="p-10 flex justify-center"><Loader2 className="animate-spin" size={32}/></div>;

    return (
        <div className="animate-in fade-in slide-in-from-right duration-300">
             <button onClick={onBack} className="mb-4 flex items-center gap-2 text-sm font-bold hover:text-yellow-500 transition-colors">
                <ArrowLeft size={16} /> Back to Clubs
             </button>

             {/* Club Detail Layout */}
             <div className="bg-white border-2 border-black overflow-hidden mb-6">
                 <div className="h-32 bg-gray-200 relative">
                     <img src={club.banner} className="w-full h-full object-cover grayscale opacity-50" />
                     <div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent"></div>
                 </div>
                 <div className="px-6 pb-6 pt-0 relative">
                     <div className="flex justify-between items-end -mt-8 mb-4">
                         <img src={club.logo} className="w-20 h-20 border-2 border-black bg-white object-cover" />
                         <button 
                            onClick={handleJoinToggle}
                            className={`px-6 py-2 text-xs font-bold uppercase tracking-widest flex items-center gap-2 border-2 transition-colors ${isMember ? 'bg-white border-black text-black hover:bg-gray-100' : 'bg-black text-white border-black hover:bg-gray-800'}`}
                         >
                            {loadingJoin ? <Loader2 className="animate-spin" size={14}/> : (isMember ? 'Leave Club' : 'Join Club')}
                         </button>
                     </div>
                     <h2 className="text-3xl font-black uppercase mb-1">{club.name}</h2>
                     <p className="text-gray-600 font-medium">{club.description}</p>
                 </div>
             </div>

             {/* Navigation Tabs */}
             <div className="flex border-b-2 border-gray-200 mb-6">
                <button 
                    onClick={() => setActiveTab('overview')} 
                    className={`flex-1 py-3 text-sm font-bold uppercase tracking-widest border-b-4 transition-colors ${activeTab === 'overview' ? 'border-yellow-400 text-black' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
                >
                    <div className="flex items-center justify-center gap-2">
                        <LayoutGrid size={16} /> Overview
                    </div>
                </button>
                <button 
                    onClick={() => setActiveTab('discussion')} 
                    className={`flex-1 py-3 text-sm font-bold uppercase tracking-widest border-b-4 transition-colors ${activeTab === 'discussion' ? 'border-yellow-400 text-black' : 'border-transparent text-gray-400 hover:text-gray-600'}`}
                >
                    <div className="flex items-center justify-center gap-2">
                        <MessageSquare size={16} /> Discussion
                    </div>
                </button>
             </div>

             {/* Tab Content */}
             {activeTab === 'overview' && (
                 <div className="space-y-8 animate-in fade-in duration-300">
                     {/* Announcements */}
                     <div>
                         <h3 className="text-xl font-black uppercase mb-4 flex items-center gap-2 border-b-2 border-gray-100 pb-2"><Megaphone size={20}/> Announcements</h3>
                         {announcements.length === 0 ? <p className="text-gray-400 italic">No announcements.</p> : (
                             <div className="space-y-2">
                                 {announcements.map(a => (
                                     <div key={a.id} className="bg-yellow-50 p-3 border-l-4 border-yellow-400">
                                         <p className="font-medium">{a.content}</p>
                                         <p className="text-xs text-gray-400 mt-1">{new Date(a.date).toLocaleDateString()}</p>
                                     </div>
                                 ))}
                             </div>
                         )}
                     </div>

                     {/* Upcoming Events */}
                     <div>
                         <h3 className="text-xl font-black uppercase mb-4 flex items-center gap-2 border-b-2 border-gray-100 pb-2"><Calendar size={20}/> Upcoming Events</h3>
                         <div className="grid gap-4">
                            {events.length === 0 ? <p className="text-gray-400 italic">No upcoming events.</p> : (
                                events.map(event => (
                                    <div key={event.id} className="bg-white border border-gray-200 p-4 flex gap-4">
                                         <div className="flex-1">
                                             <h4 className="font-bold text-lg">{event.title}</h4>
                                             <p className="text-sm text-gray-500 mb-2">{event.date} at {event.time}</p>
                                             <span className="text-xs bg-gray-100 px-2 py-1 font-bold">{event.status}</span>
                                         </div>
                                    </div>
                                ))
                            )}
                         </div>
                     </div>

                      {/* Media Gallery */}
                      <div>
                         <h3 className="text-xl font-black uppercase mb-4 flex items-center gap-2 border-b-2 border-gray-100 pb-2"><ImageIcon size={20}/> Club Gallery</h3>
                         <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                             {media.length === 0 ? <p className="text-gray-400 italic col-span-2">No photos yet.</p> : (
                                 media.map(m => (
                                     <div key={m.id} className="aspect-square bg-gray-100 border border-gray-200 relative group overflow-hidden">
                                         <img src={m.imageUrl} className="w-full h-full object-cover" />
                                         <div className="absolute inset-0 bg-black/60 flex items-end p-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                             <p className="text-white text-xs truncate">{m.caption}</p>
                                         </div>
                                     </div>
                                 ))
                             )}
                         </div>
                      </div>
                 </div>
             )}

             {activeTab === 'discussion' && (
                 <div className="animate-in fade-in duration-300">
                     {isMember ? (
                         <div className="space-y-6">
                             {/* Create Post */}
                             <div className="bg-gray-50 p-4 border border-gray-200">
                                 <textarea 
                                    className="w-full p-3 border border-gray-300 focus:outline-none focus:border-black mb-3 text-sm"
                                    rows={2}
                                    placeholder="Start a discussion..."
                                    value={newPostContent}
                                    onChange={e => setNewPostContent(e.target.value)}
                                 />
                                 <div className="flex justify-end">
                                     <button 
                                        onClick={handleCreatePost}
                                        disabled={loadingPost}
                                        className="bg-black text-white px-4 py-2 text-xs font-bold uppercase tracking-wide hover:bg-gray-800 disabled:opacity-50 flex items-center gap-2"
                                     >
                                         {loadingPost ? <Loader2 className="animate-spin" size={14}/> : <><Send size={14} /> Post</>}
                                     </button>
                                 </div>
                             </div>

                             {/* Post List */}
                             <div className="space-y-4">
                                 {posts.length === 0 && <p className="text-gray-400 italic text-center">No discussions yet. Be the first!</p>}
                                 {posts.map(post => {
                                     const isLiked = post.likedBy.includes(user.id);
                                     return (
                                         <div key={post.id} className="bg-white border-2 border-black p-4">
                                             <div className="flex items-center gap-3 mb-3">
                                                 <img src={post.userAvatar || `https://api.dicebear.com/7.x/initials/svg?seed=${post.userName}`} className="w-8 h-8 rounded-full bg-gray-200" />
                                                 <div>
                                                     <p className="font-bold text-sm leading-none">{post.userName}</p>
                                                     <p className="text-[10px] text-gray-400">{new Date(post.timestamp).toLocaleDateString()}</p>
                                                 </div>
                                             </div>
                                             <p className="text-sm mb-4">{post.content}</p>

                                             <div className="flex items-center gap-4 border-t border-gray-100 pt-2">
                                                 <button 
                                                    onClick={() => handleLikePost(post)}
                                                    className={`flex items-center gap-1 text-xs font-bold transition-colors ${isLiked ? 'text-blue-600' : 'text-gray-500 hover:text-black'}`}
                                                 >
                                                     <ThumbsUp size={14} fill={isLiked ? "currentColor" : "none"}/> {post.likedBy.length} Likes
                                                 </button>
                                                 <button 
                                                    onClick={() => setCommentingPostId(commentingPostId === post.id ? null : post.id)}
                                                    className="flex items-center gap-1 text-xs font-bold text-gray-500 hover:text-black transition-colors"
                                                 >
                                                     <MessageSquare size={14} /> {post.comments.length} Comments
                                                 </button>
                                             </div>

                                             {/* Comments Section */}
                                             {commentingPostId === post.id && (
                                                 <div className="mt-3 pt-3 border-t border-dashed border-gray-200">
                                                     <div className="space-y-2 mb-3 max-h-40 overflow-y-auto">
                                                         {post.comments.map(c => (
                                                             <div key={c.id} className="text-xs bg-gray-50 p-2">
                                                                 <span className="font-bold">{c.userName}: </span>
                                                                 <span>{c.text}</span>
                                                             </div>
                                                         ))}
                                                     </div>
                                                     <div className="flex gap-2">
                                                         <input 
                                                            type="text" 
                                                            className="flex-1 border border-gray-300 p-2 text-xs focus:outline-none focus:border-black"
                                                            placeholder="Write a comment..."
                                                            value={newComment}
                                                            onChange={e => setNewComment(e.target.value)}
                                                         />
                                                         <button onClick={() => handleAddComment(post.id)} className="bg-black text-white px-3 py-1 text-xs font-bold uppercase">Reply</button>
                                                     </div>
                                                 </div>
                                             )}
                                         </div>
                                     );
                                 })}
                             </div>
                         </div>
                     ) : (
                         <div className="bg-gray-100 border-2 border-dashed border-gray-300 p-8 text-center">
                             <Lock className="mx-auto mb-2 text-gray-400" size={32} />
                             <p className="font-bold text-gray-500">Join the club to view and participate in discussions.</p>
                         </div>
                     )}
                 </div>
             )}
        </div>
    );
};

// --- Main Event Card ---

interface EventCardProps {
    event: Event;
    onRegister?: (event: Event) => void;
    isRegistered?: boolean;
    isAdminView: boolean;
    onApprove?: (id: string) => void;
    onReject?: (id: string, reason: string) => void;
    venueName?: string;
    onVolunteer?: (id: string) => void;
    volunteerStatus?: VolunteerStatus | null;
    onManageVolunteers?: (event: Event) => void;
    onGeneratePoster?: (event: Event) => void;
    onIssueCertificates?: (event: Event) => void;
    onEdit?: (event: Event) => void; // For re-application
    onClick?: () => void;
}

const EventCard = ({ 
    event, onRegister, isRegistered, isAdminView, onApprove, onReject, venueName, 
    onVolunteer, volunteerStatus, onManageVolunteers, onGeneratePoster, onIssueCertificates, onEdit, onClick
}: EventCardProps) => {
  const [loadingAction, setLoadingAction] = useState<string | null>(null);
  const [rejectReason, setRejectReason] = useState('');
  const [showRejectInput, setShowRejectInput] = useState(false);

  const showAdminActions = isAdminView && 
    event.status === EventStatus.PENDING && 
    typeof onApprove === 'function' && 
    typeof onReject === 'function';

  return (
    <div 
        className={`bg-white border-2 border-black shadow-[4px_4px_0px_rgba(0,0,0,1)] hover:shadow-[8px_8px_0px_rgba(250,204,21,1)] hover:-translate-y-1 transition-all duration-200 flex flex-col h-full group relative overflow-hidden ${onClick ? 'cursor-pointer' : ''}`}
        onClick={(e) => {
            // Prevent triggering card click when clicking interactive buttons inside
            if ((e.target as HTMLElement).closest('button') || (e.target as HTMLElement).closest('textarea') || (e.target as HTMLElement).closest('input')) return;
            if (onClick) onClick();
        }}
    >
      <div className="absolute top-0 right-0 w-16 h-16 bg-yellow-400 rotate-45 translate-x-8 -translate-y-8 z-10"></div>

      <div className="h-48 overflow-hidden relative bg-gray-900 border-b-2 border-black">
        <img 
          src={event.image || `https://picsum.photos/800/400?random=${event.id}`} 
          alt={event.title} 
          onError={(e) => {
              // Fallback if image fails
              e.currentTarget.src = "https://via.placeholder.com/800x400/000000/FACC15?text=CLIX+EVENT";
          }}
          className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all duration-500 opacity-80 group-hover:opacity-100"
        />
        <div className="absolute top-3 right-3 z-20">
            <StatusBadge status={event.status} />
        </div>
        {event.price > 0 ? (
           <div className="absolute bottom-3 right-3 bg-black text-yellow-400 px-3 py-1 text-xs font-extrabold border border-yellow-400 shadow-sm">
             ₹{event.price}
           </div>
        ) : (
           <div className="absolute bottom-3 right-3 bg-yellow-400 text-black px-3 py-1 text-xs font-extrabold border border-black shadow-sm">
             FREE
           </div>
        )}
      </div>

      <div className="p-5 flex-1 flex flex-col">
        <div className="mb-3 flex items-center justify-between">
           <div className="text-[10px] font-extrabold text-gray-400 uppercase tracking-widest border border-gray-200 px-2 py-0.5 rounded-full inline-block">
             {event.organizer}
           </div>
           <div className="text-[10px] font-bold text-gray-400 flex items-center gap-1">
             <Users size={12} /> {event.capacity - event.registeredCount} spots left
           </div>
        </div>

        <h3 className="text-2xl font-black mb-3 leading-none tracking-tight">{event.title}</h3>
        <p className="text-gray-600 text-sm mb-5 line-clamp-2 font-medium">{event.description}</p>

        {event.status === EventStatus.REJECTED && event.rejectionReason && (
            <div className="mb-4 bg-red-50 border-l-4 border-red-500 p-2">
                <p className="text-xs font-bold text-red-500 uppercase">Reason for Rejection:</p>
                <p className="text-sm text-gray-700">{event.rejectionReason}</p>
            </div>
        )}

        <div className="space-y-3 mt-auto text-sm text-black font-semibold">
          <div className="flex items-center">
            <Calendar size={16} className="mr-3 text-yellow-500" />
            {event.date}
          </div>
          <div className="flex items-center">
            <Clock size={16} className="mr-3 text-yellow-500" />
            {event.time}
          </div>
          <div className="flex items-center">
            <MapPin size={16} className="mr-3 text-yellow-500" />
            {venueName || 'TBD'}
          </div>
        </div>
      </div>

      <div className="p-4 pt-0 mt-2">
        {isAdminView ? (
          showAdminActions ? (
            <div className="space-y-2 pt-2">
               {showRejectInput ? (
                   <div className="space-y-2 animate-in slide-in-from-bottom duration-200">
                       <textarea 
                          placeholder="Reason for rejection..." 
                          className="w-full p-2 text-sm border-2 border-black focus:outline-none"
                          value={rejectReason}
                          onChange={e => setRejectReason(e.target.value)}
                          rows={2}
                       />
                       <div className="flex gap-2">
                           <button 
                             onClick={async () => { 
                                 setLoadingAction('reject'); 
                                 await onReject!(event.id, rejectReason); 
                                 setLoadingAction(null); 
                                 setShowRejectInput(false);
                            }} 
                             className="flex-1 bg-red-500 text-white text-xs font-bold py-2 hover:bg-red-600"
                           >
                               Confirm Reject
                           </button>
                           <button onClick={() => setShowRejectInput(false)} className="px-3 bg-gray-200 text-xs font-bold">Cancel</button>
                       </div>
                   </div>
               ) : (
                <div className="flex space-x-2">
                    <button 
                        onClick={async () => { setLoadingAction('approve'); await onApprove!(event.id); setLoadingAction(null); }} 
                        className="flex-1 bg-black text-yellow-400 py-3 text-sm font-bold hover:bg-gray-900 transition border-2 border-black flex items-center justify-center"
                    >
                        {loadingAction === 'approve' ? <Loader2 className="animate-spin" size={16}/> : 'Approve'}
                    </button>
                    <button 
                        onClick={() => setShowRejectInput(true)} 
                        className="flex-1 bg-white border-2 border-black text-black py-3 text-sm font-bold hover:bg-red-50 hover:border-red-500 hover:text-red-500 transition flex items-center justify-center"
                    >
                        Reject
                    </button>
                </div>
               )}
            </div>
          ) : (
             <div className="space-y-2">
                 {/* Only show 'Manage' as a hint if clicking card opens management, or show specific actions if not */}
                 {event.status === EventStatus.APPROVED && onClick && (
                    <div className="w-full py-3 text-sm font-bold uppercase tracking-widest bg-white border-2 border-black text-black hover:bg-yellow-50 transition flex items-center justify-center gap-2 mt-2 group-hover:bg-yellow-400 group-hover:border-black">
                       <Eye size={16}/> View & Manage
                    </div>
                 )}

                 {/* Keep Poster/Cert actions accessible directly too */}
                 {(event.status === EventStatus.COMPLETED || new Date(event.date) < new Date()) && onGeneratePoster && onIssueCertificates && (
                    <div className="flex flex-col gap-2 pt-2">
                        <button 
                             onClick={() => onGeneratePoster(event)}
                             className="w-full py-2 text-xs font-bold uppercase tracking-widest bg-yellow-400 border-2 border-black text-black hover:bg-yellow-300 flex items-center justify-center gap-2"
                        >
                            <Trophy size={14}/> Generate Winners Poster
                        </button>
                        <button 
                             onClick={() => onIssueCertificates(event)}
                             disabled={event.certificatesIssued}
                             className={`w-full py-2 text-xs font-bold uppercase tracking-widest border-2 border-black flex items-center justify-center gap-2 ${event.certificatesIssued ? 'bg-green-100 text-green-700 border-green-300' : 'bg-white text-black hover:bg-gray-100'}`}
                        >
                            {event.certificatesIssued ? <><Check size={14}/> Certificates Issued</> : <><Award size={14}/> Issue Certificates</>}
                        </button>
                    </div>
                 )}
                 {event.status === EventStatus.REJECTED && onEdit && (
                     <button 
                        onClick={() => onEdit(event)}
                        className="w-full py-3 text-sm font-bold uppercase tracking-widest bg-black text-white hover:bg-gray-800 transition mt-2"
                     >
                        Edit & Reapply
                     </button>
                 )}
             </div>
          )
        ) : (
          <div className="space-y-2">
             <button 
                onClick={async () => { 
                  if (onRegister) {
                    setLoadingAction('reg'); 
                    await onRegister(event); 
                    setLoadingAction(null); 
                  }
                }}
                disabled={isRegistered || event.status !== EventStatus.APPROVED || loadingAction === 'reg'}
                className={`w-full py-3 text-sm font-black uppercase tracking-widest transition-all border-2 border-black shadow-[2px_2px_0px_rgba(0,0,0,1)] active:shadow-none active:translate-x-[2px] active:translate-y-[2px] flex items-center justify-center gap-2 ${
                  isRegistered 
                    ? 'bg-gray-100 text-gray-400 border-gray-200 shadow-none cursor-not-allowed' 
                    : event.status !== EventStatus.APPROVED 
                      ? 'bg-gray-100 text-gray-400 border-gray-200 shadow-none cursor-not-allowed'
                      : 'bg-yellow-400 text-black hover:bg-yellow-300'
                }`}
              >
                {loadingAction === 'reg' ? <Loader2 className="animate-spin" size={16}/> : (isRegistered ? 'Ticket Confirmed' : event.status !== EventStatus.APPROVED ? 'Coming Soon' : (event.price > 0 ? `Book Ticket (₹${event.price})` : 'Get Ticket'))}
              </button>

              {!isRegistered && event.status === EventStatus.APPROVED && event.volunteersNeeded && (
                <button 
                  onClick={async () => {
                     if (volunteerStatus) return; 
                     setLoadingAction('vol');
                     if (onVolunteer) await onVolunteer(event.id);
                     setLoadingAction(null);
                  }}
                  disabled={!!volunteerStatus || loadingAction === 'vol'}
                  className={`w-full py-2 text-xs font-bold uppercase tracking-wider flex items-center justify-center gap-2 ${
                     volunteerStatus 
                       ? 'text-green-600 bg-green-50 border border-green-200 cursor-default'
                       : 'text-gray-500 hover:text-black hover:bg-gray-100'
                  }`}
                >
                  {loadingAction === 'vol' ? <Loader2 className="animate-spin" size={14}/> : (
                      volunteerStatus ? (
                          <>
                            <Check size={14} /> {volunteerStatus === VolunteerStatus.PENDING ? 'Application Pending' : 'Volunteer Accepted'}
                          </>
                      ) : (
                          <>
                            <Hand size={14} /> Volunteer
                          </>
                      )
                  )}
                </button>
              )}
          </div>
        )}
      </div>
    </div>
  );
};

