                               <div className="text-center py-6 border-2 border-dashed border-gray-200 bg-gray-50">
                                   <Award size={32} className="mx-auto text-gray-300 mb-2"/>
                                   <p className="text-gray-500 text-sm font-medium">No certificates earned yet.</p>
                               </div>
