                               events.filter(e => userRegistrations.includes(e.id) && e.certificatesIssued).map(event => (
                                    <div key={event.id} className="bg-white border-2 border-black p-4 flex justify-between items-center cursor-pointer hover:bg-yellow-50 transition" onClick={() => { setSelectedEvent(event); setCertOpen(true); }}>
