                {/* Feedback Section */}
                <div className="border-t-2 border-gray-100 pt-6">
                    <h3 className="text-lg font-black uppercase mb-4">Student Feedback</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-h-48 overflow-y-auto">
