                                <option value="3rd Year">3rd Year</option>
                                <option value="4th Year">4th Year</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-black uppercase mb-1 text-black">Branch</label>
                            <input required type="text" placeholder="CSE..." value={branch} onChange={e => setBranch(e.target.value)} className="w-full p-3 border-2 border-black font-bold focus:outline-none focus:ring-4 focus:ring-yellow-200 text-black bg-white" />
                        </div>
                    </div>
                     <div>
                        <label className="block text-xs font-black uppercase mb-1 text-black">Password</label>
                        <input required type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full p-3 border-2 border-black font-bold focus:outline-none focus:ring-4 focus:ring-yellow-200 text-black bg-white" />
                    </div>
                    <button disabled={loading} className="w-full bg-yellow-400 text-black py-4 font-black uppercase tracking-widest hover:bg-yellow-300 hover:scale-[1.02] transition-transform">{loading ? <Loader2 className="animate-spin mx-auto"/> : 'Create Account'}</button>
                </form>
                <div className="mt-6 text-center text-sm font-bold text-black">
                    <span className="text-gray-400">Already have an account?</span> <button onClick={onSwitchToLogin} className="ml-1 underline hover:text-black">Log In</button>
                </div>
            </div>
        </div>
    );
};

const App = () => {
  const [user, setUser] = useState<User | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [authView, setAuthView] = useState<'login' | 'signup'>('login');

  const [activeTab, setActiveTab] = useState('feed');
  const [events, setEvents] = useState<Event[]>([]);
  const [clubs, setClubs] = useState<Club[]>([]);
  const [venues, setVenues] = useState<Venue[]>([]);
  const [userRegistrations, setUserRegistrations] = useState<string[]>([]);
  const [volunteerApps, setVolunteerApps] = useState<VolunteerApplication[]>([]);

  // Search state
  const [searchQuery, setSearchQuery] = useState('');
  const [filterPrice, setFilterPrice] = useState<'all' | 'free' | 'paid'>('all');

  // Modals
  const [selectedEvent, setSelectedEvent] = useState<Event | null>(null);
  const [paymentOpen, setPaymentOpen] = useState(false);
  const [qrOpen, setQrOpen] = useState(false);
  const [certOpen, setCertOpen] = useState(false);

  // Edit Profile
  const [isEditProfileOpen, setIsEditProfileOpen] = useState(false);
  // Feedback
  const [feedbackEvent, setFeedbackEvent] = useState<Event | null>(null);

  // Club Details
  const [selectedClub, setSelectedClub] = useState<Club | null>(null);

  useEffect(() => {
    if(isAuthenticated) fetchData();
  }, [user, isAuthenticated]);

  const fetchData = async () => {
    if (!user) return;
    try {
        const e = await api.events.list();
        setEvents(e);
        const c = await api.clubs.list();
        setClubs(c);
        const v = await api.venues.list();
        setVenues(v);
        if (api.auth.getRegistrations) {
            const regs = await api.auth.getRegistrations(user.id);
            setUserRegistrations(regs);
        }
        const vApps = await api.volunteers.listByUser(user.id);
        setVolunteerApps(vApps);
    } catch (err) {
        console.error("Failed to fetch data", err);
    }
  };

  const handleLogin = (u: User) => {
      setUser(u);
      setIsAuthenticated(true);
      if (u.role === UserRole.STUDENT) setActiveTab('feed');
      else if (u.role === UserRole.CLUB_ADMIN) setActiveTab('dashboard');
      else if (u.role === UserRole.COLLEGE_ADMIN) setActiveTab('approvals');
  };

  const handleLogout = () => {
      setIsAuthenticated(false);
      setUser(null);
      setAuthView('login');
  };

  const handleRegister = async (event: Event) => {
      if(!user) return;
      if (event.price > 0) {
          setSelectedEvent(event);
          setPaymentOpen(true);
      } else {
          await confirmRegistration(event);
      }
  };

  const confirmRegistration = async (event: Event) => {
      if(!user) return;
      await api.events.register(event.id, user.id);
      setUserRegistrations(prev => [...prev, event.id]);
      setEvents(prev => prev.map(e => e.id === event.id ? {...e, registeredCount: e.registeredCount + 1} : e));
      if (paymentOpen) setPaymentOpen(false);
  };

  const handleVolunteerApply = async (eventId: string) => {
      if(!user) return;
      try {
          const app: VolunteerApplication = {
              id: `v${Date.now()}`,
              eventId,
              userId: user.id,
              userName: user.name,
              userAvatar: user.avatar,
              status: VolunteerStatus.PENDING,
              appliedAt: new Date().toISOString()
          };
          await api.volunteers.apply(app);
          setVolunteerApps(prev => [...prev, app]);
      } catch (e: any) {
          alert(e.message);
      }
  };

  const handleUpdateProfile = async (data: Partial<User>) => {
      if (!user) return;
      const updatedUser = { ...user, ...data };
      await api.auth.updateProfile(updatedUser);
      setUser(updatedUser);
  };

  const handleFeedbackSubmit = async (rating: number, comment: string) => {
      if (!feedbackEvent || !user) return;
      const feedback: Feedback = { userId: user.id, rating, comment };
      await api.events.addFeedback(feedbackEvent.id, feedback);
      // Update local event state to reflect new feedback without full refetch
      setEvents(events.map(e => e.id === feedbackEvent.id ? {...e, feedback: [...(e.feedback || []), feedback]} : e));
      setFeedbackEvent(null);
  };

  // Auth Views
  if (!isAuthenticated) {
      return authView === 'login' 
        ? <LoginPage onLogin={handleLogin} onSwitchToSignup={() => setAuthView('signup')} />
        : <SignupPage onSignup={(u) => { setUser(u); setIsAuthenticated(true); setActiveTab('feed'); }} onSwitchToLogin={() => setAuthView('login')} />;
  }

  // Filtered Events for Feed
  const filteredEvents = events.filter(e => {
        if (e.status !== EventStatus.APPROVED) return false;
        if (filterPrice === 'free' && e.price > 0) return false;
        if (filterPrice === 'paid' && e.price === 0) return false;
        const query = searchQuery.toLowerCase();
        return (
          e.title.toLowerCase().includes(query) || 
          e.description.toLowerCase().includes(query) ||
          e.tags.some(tag => tag.toLowerCase().includes(query))
        );
  });

  if (!user) return null;

  return (
    <Layout user={user} onLogout={handleLogout} activeTab={activeTab} setActiveTab={setActiveTab}>

      {/* STUDENT VIEW */}
      {user.role === UserRole.STUDENT && (
        <>
           {/* ... Feed View ... */}
           {activeTab === 'feed' && (
               <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                   <div className="flex flex-col gap-4 border-b-4 border-black pb-6">
                      <div className="flex justify-between items-end">
                         <div>
                            <h2 className="text-4xl md:text-5xl font-black tracking-tighter mb-2">WHATS ON<span className="text-yellow-500">?</span></h2>
                            <p className="text-gray-500 font-medium">Discover and join campus activities.</p>
                         </div>
                      </div>
                      <div className="flex flex-col md:flex-row gap-4">
                         <div className="relative flex-1">
                            <input 
                            type="text" 
                            placeholder="Search events, tags..." 
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="pl-10 pr-4 py-3 border-2 border-black focus:outline-none focus:ring-4 focus:ring-yellow-400 w-full font-bold bg-white"
                            />
                            <Search className="absolute left-3 top-3.5 text-black" size={20} />
                         </div>
                         <div className="flex items-center gap-2">
                             <Filter size={20} className="text-gray-500" />
                             <select 
                                className="p-3 border-2 border-black font-bold bg-white focus:outline-none focus:ring-4 focus:ring-yellow-400"
                                value={filterPrice}
                                onChange={(e) => setFilterPrice(e.target.value as any)}
                             >
                                 <option value="all">All Prices</option>
                                 <option value="free">Free Only</option>
                                 <option value="paid">Paid Only</option>
                             </select>
                         </div>
                      </div>
                   </div>

                   <div className="grid gap-6">
                       {filteredEvents.map(event => (
                           <EventCard 
                             key={event.id} 
                             event={event} 
                             isAdminView={false}
                             isRegistered={userRegistrations.includes(event.id)}
                             onRegister={handleRegister}
                             venueName={venues.find(v => v.id === event.venueId)?.name || event.venueId}
                             onVolunteer={handleVolunteerApply}
                             volunteerStatus={volunteerApps.find(v => v.eventId === event.id)?.status}
                           />
                       ))}
                       {filteredEvents.length === 0 && <div className="text-center py-10 text-gray-400">No events found.</div>}
                   </div>
               </div>
           )}
           {activeTab === 'media' && <StudentMediaView user={user} />}
           {activeTab === 'clubs' && (
               selectedClub ? (
                    <StudentClubDetail 
                        club={selectedClub} 
                        onBack={() => setSelectedClub(null)} 
                        user={user} 
                        onUpdateUser={setUser}
                    />
               ) : (
                    <div className="grid grid-cols-1 gap-4 animate-in fade-in duration-300">
                        {clubs.length > 0 ? (
                            clubs.map(club => (
                            <div 
                                key={club.id} 
                                onClick={() => setSelectedClub(club)}
                                className="bg-white border-2 border-black p-4 flex gap-4 items-start cursor-pointer hover:bg-yellow-50 hover:-translate-y-1 transition-transform shadow-[4px_4px_0px_rgba(0,0,0,0.1)] hover:shadow-[6px_6px_0px_#FACC15]"
                            >
                                <img 
                                        src={club.logo} 
                                        onError={(e) => { e.currentTarget.src = `https://api.dicebear.com/7.x/initials/svg?seed=${club.name}`; }}
                                        className="w-16 h-16 border border-black object-cover flex-shrink-0" 
                                />
                                <div className="flex-1">
                                    <h3 className="font-black text-lg">{club.name}</h3>
                                    <p className="text-sm text-gray-600 line-clamp-2">{club.description || 'No description available.'}</p>
                                    <div className="mt-2 text-xs font-bold text-gray-400 flex items-center justify-between">
                                        <span>{club.memberCount} Members</span>
                                        <ChevronRight size={16} />
                                    </div>
                                </div>
                            </div>
                        ))) : (
                            <p className="text-gray-500 text-center py-8">No clubs found.</p>
                        )}
                    </div>
               )
           )}
           {activeTab === 'tickets' && (
               <div className="space-y-4">
                   <h2 className="text-2xl font-black">MY TICKETS</h2>
                   {events.filter(e => userRegistrations.includes(e.id)).length > 0 ? (
                       events.filter(e => userRegistrations.includes(e.id)).map(event => (
                       <div key={event.id} className="bg-white border-2 border-black p-4 group hover:shadow-[4px_4px_0px_#000] transition-shadow">
                           <div className="flex justify-between items-start mb-4" onClick={() => { setSelectedEvent(event); setQrOpen(true); }}>
                               <div className="cursor-pointer">
                                   <h3 className="font-black text-lg">{event.title}</h3>
                                   <p className="text-xs text-gray-500 font-bold uppercase">{event.date} | {event.time}</p>
                                   <p className="text-xs text-gray-400 mt-1">{venues.find(v => v.id === event.venueId)?.name || event.venueId}</p>
                               </div>
                               <QrCode size={40} className="text-black cursor-pointer" onClick={() => { setSelectedEvent(event); setQrOpen(true); }}/>
                           </div>

                           {/* Action Buttons */}
                           <div className="flex gap-2 pt-2 border-t border-gray-100">
                               <button 
                                 onClick={() => { setSelectedEvent(event); setQrOpen(true); }}
                                 className="flex-1 py-2 text-xs font-bold uppercase tracking-wide bg-gray-50 hover:bg-gray-100 flex items-center justify-center gap-1"
                               >
                                   <Ticket size={14} /> View Ticket
                               </button>
                               <button 
                                 onClick={() => setFeedbackEvent(event)}
                                 className="flex-1 py-2 text-xs font-bold uppercase tracking-wide bg-yellow-400 hover:bg-yellow-300 border border-black flex items-center justify-center gap-1"
                               >
                                   <Star size={14} /> Rate Event
                               </button>
                           </div>
                       </div>
                   ))) : (
                       <div className="text-center py-10 border-2 border-dashed border-gray-300">
                           <Ticket size={48} className="mx-auto text-gray-300 mb-2"/>
                           <p className="text-gray-500 font-medium">No tickets yet.</p>
                       </div>
                   )}
               </div>
           )}
           {activeTab === 'profile' && (
               <div className="space-y-6 animate-in fade-in duration-300">
                   <div className="bg-white border-2 border-black p-6 relative">
                       <button 
                         onClick={() => setIsEditProfileOpen(true)}
                         className="absolute top-4 right-4 p-2 hover:bg-gray-100 rounded-full transition-colors"
                         title="Edit Profile"
                       >
                         <UserCog size={20} />
                       </button>

                       <div className="flex flex-col items-center text-center">
                           <img 
                             src={user.avatar} 
                             alt={user.name}
                             onError={(e) => e.currentTarget.src = `https://api.dicebear.com/7.x/initials/svg?seed=${user.name}`}
                             className="w-32 h-32 rounded-full border-4 border-black mb-4 object-cover" 
                           />
                           <h2 className="text-2xl font-black uppercase">{user.name}</h2>
                           <p className="text-sm font-bold text-gray-400">{user.email}</p>
                           {user.bio ? (
                               <p className="mt-4 text-gray-600 max-w-sm italic font-medium">"{user.bio}"</p>
                           ) : (
                               <p className="mt-4 text-gray-400 text-xs italic">No bio added.</p>
                           )}

                           <div className="mt-6 flex justify-center gap-8 w-full border-t-2 border-dashed border-gray-200 pt-6">
                               <div className="text-center">
                                   <p className="font-black text-2xl">{userRegistrations.length}</p>
                                   <p className="text-[10px] uppercase font-bold text-gray-400 tracking-widest">Events</p>
                               </div>
                               <div className="text-center">
                                   <p className="font-black text-2xl">{(user.joinedClubIds || []).length}</p>
                                   <p className="text-[10px] uppercase font-bold text-gray-400 tracking-widest">Clubs</p>
                               </div>
                           </div>
                       </div>
                   </div>

                   {/* Certificates Section Moved Here */}
                   <div>
                       <h3 className="text-xl font-black uppercase mb-4 flex items-center gap-2">
                          <Award className="text-yellow-500" size={24}/> My Certificates
                       </h3>
                       <div className="space-y-3">
                           {events.filter(e => userRegistrations.includes(e.id) && e.certificatesIssued).length === 0 ? (
                               <div className="text-center py-6 border-2 border-dashed border-gray-200 bg-gray-50">
                                   <Award size={32} className="mx-auto text-gray-300 mb-2"/>
                                   <p className="text-gray-500 text-sm font-medium">No certificates earned yet.</p>
                               </div>
