                 <p className="text-gray-500 font-bold mb-4">Club Admin</p>
                 {user.bio && <p className="text-gray-600 italic mb-6">"{user.bio}"</p>}
                 <button onClick={handleLogout} className="mt-8 bg-red-500 text-white px-6 py-2 font-bold uppercase tracking-widest hover:bg-red-600 flex items-center gap-2 mx-auto"><LogOut size={16}/> Logout</button>
              </div>
          ) : (
              <ClubAdminDashboard user={user} refreshData={fetchData} activeTab={activeTab} />
