                                    await api.events.updateStatus(id, EventStatus.APPROVED);
                                    fetchData();
                                }}
                                onReject={async (id, reason) => {
                                    await api.events.updateStatus(id, EventStatus.REJECTED, reason);
                                    fetchData();
                                }}
                            />
                        ))}
                    </div>
                </>
            )}
            {activeTab === 'clubs_manage' && (
                // ... (existing implementation)
                <div>
                    <h2 className="text-3xl font-black mb-6">CLUBS OVERVIEW</h2>
                     <div className="grid grid-cols-1 gap-4">
                        {clubs.length > 0 ? clubs.map(club => (
                            <div key={club.id} className="bg-white border-2 border-black p-4">
                                <div className="flex justify-between items-start">
                                    <div className="flex gap-4">
                                         <img src={club.logo} className="w-12 h-12 object-cover border border-black" onError={(e) => e.currentTarget.src = `https://api.dicebear.com/7.x/initials/svg?seed=${club.name}`}/>
                                         <div>
                                            <h3 className="font-black text-lg">{club.name}</h3>
                                            <p className="text-xs text-gray-500">Admin: {club.adminId}</p>
                                        </div>
                                    </div>
                                    <div className="bg-yellow-400 text-black px-2 py-1 text-xs font-bold border border-black">
                                        {club.memberCount} Members
                                    </div>
                                </div>
                            </div>
                        )) : <p className="text-gray-500">No clubs registered.</p>}
                    </div>
                </div>
            )}
            {activeTab === 'reports' && (
                 <div className="bg-white border-2 border-black p-8 text-center">
                     <BarChart3 size={48} className="mx-auto mb-4"/>
                     <h3 className="text-xl font-black">REPORTS DASHBOARD</h3>
                     <p className="text-gray-500">Comprehensive analytics.</p>
                 </div>
            )}
             {activeTab === 'profile' && (
               <div className="bg-white border-2 border-black p-6 text-center relative">
                   <button 
                         onClick={() => setIsEditProfileOpen(true)}
                         className="absolute top-4 right-4 p-2 hover:bg-gray-100 rounded-full transition-colors"
                   >
                         <UserCog size={20} />
                   </button>
                   <img src={user.avatar} className="w-32 h-32 rounded-full border-4 border-black mx-auto mb-4" onError={(e) => e.currentTarget.src = `https://api.dicebear.com/7.x/initials/svg?seed=${user.name}`}/>
                   <h2 className="text-2xl font-black">{user.name}</h2>
                   <p className="text-gray-500 font-bold mb-4">College Admin</p>
                   {user.bio && <p className="text-gray-600 italic mb-6">"{user.bio}"</p>}
                   <button onClick={handleLogout} className="mt-8 bg-red-500 text-white px-6 py-2 font-bold uppercase tracking-widest hover:bg-red-600 flex items-center gap-2 mx-auto"><LogOut size={16}/> Logout</button>
               </div>
           )}
        </div>
      )}

      {/* Global Modals */}
      <PaymentModal 
          isOpen={paymentOpen} 
          onClose={() => setPaymentOpen(false)} 
          event={selectedEvent} 
          onConfirm={() => selectedEvent && confirmRegistration(selectedEvent)} 
      />
      <TicketQRModal 
          isOpen={qrOpen} 
          onClose={() => setQrOpen(false)} 
          event={selectedEvent} 
          user={user} 
      />
      <CertificateModal 
          isOpen={certOpen} 
          onClose={() => setCertOpen(false)} 
          event={selectedEvent} 
          user={user} 
      />
      <FeedbackModal
          isOpen={!!feedbackEvent}
          onClose={() => setFeedbackEvent(null)}
          event={feedbackEvent}
          onSubmit={handleFeedbackSubmit}
      />

      {/* Edit Profile Modal */}
      {user && (
          <EditProfileModal 
              isOpen={isEditProfileOpen}
              onClose={() => setIsEditProfileOpen(false)}
              user={user}
              onUpdate={handleUpdateProfile}
          />
      )}

    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
