                <span key={tag} className="text-[10px] bg-gray-100 px-2 py-1 font-bold uppercase tracking-wide border border-gray-200">{tag}</span>
            ))}
        </div>

        {/* Action Area */}
        <div className="mt-auto pt-4 border-t-2 border-dashed border-gray-200 space-y-3">
             {/* Progress Bar for capacity */}
             {event.status === EventStatus.APPROVED && (
                 <div>
                    <div className="flex justify-between text-[10px] font-bold uppercase mb-1">
                        <span>{event.registeredCount} / {event.capacity} Registered</span>
                        <span className={event.registeredCount >= event.capacity ? "text-red-500" : "text-green-500"}>
                            {event.registeredCount >= event.capacity ? "Full" : "Open"}
                        </span>
                    </div>
                    <div className="h-2 w-full bg-gray-200 rounded-full overflow-hidden border border-black">
                        <div 
                            className="h-full bg-yellow-400" 
                            style={{ width: `${Math.min((event.registeredCount / event.capacity) * 100, 100)}%` }}
                        ></div>
                    </div>
                 </div>
             )}

             {/* Admin Actions */}
             {isAdminView && onApprove && onReject && event.status === EventStatus.PENDING && (
                 <div className="space-y-2">
                     {!showRejectInput ? (
                         <div className="flex gap-2">
                             <button 
                                onClick={(e) => { e.stopPropagation(); onApprove(event.id); }}
                                className="flex-1 bg-green-500 text-white py-2 font-bold uppercase tracking-widest hover:bg-green-600 border border-black shadow-[2px_2px_0px_#000]"
                             >
                                Approve
                             </button>
                             <button 
                                onClick={(e) => { e.stopPropagation(); setShowRejectInput(true); }}
                                className="flex-1 bg-red-500 text-white py-2 font-bold uppercase tracking-widest hover:bg-red-600 border border-black shadow-[2px_2px_0px_#000]"
                             >
                                Reject
                             </button>
                         </div>
                     ) : (
                         <div className="flex gap-2" onClick={e => e.stopPropagation()}>
                             <input 
                                type="text" 
                                placeholder="Reason..." 
                                className="flex-1 border-2 border-black p-2 text-xs font-bold"
                                value={rejectReason}
                                onChange={e => setRejectReason(e.target.value)}
                             />
                             <button onClick={() => onReject(event.id, rejectReason)} className="bg-red-500 text-white px-3 font-bold uppercase border border-black">Confirm</button>
                             <button onClick={() => setShowRejectInput(false)} className="bg-gray-200 text-black px-3 font-bold uppercase border border-black">X</button>
