const LoginPage = ({ onLogin, onSwitchToSignup }: { onLogin: (user: User) => void, onSwitchToSignup: () => void }) => {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError('');
        try {
            const user = await api.auth.login(email, password);
            onLogin(user);
        } catch (err: any) {
            setError(err.message || 'Login failed');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-yellow-400 flex items-center justify-center p-4">
            <div className="bg-white w-full max-w-md p-8 border-4 border-black shadow-[8px_8px_0px_#000]">
                <h1 className="text-5xl font-black mb-2 text-black tracking-tighter">CLIX<span className="text-yellow-400">.</span></h1>
                <p className="font-bold text-gray-500 mb-8 uppercase tracking-widest">Campus Life Interface</p>
                {error && <div className="bg-red-100 text-red-600 p-3 mb-4 text-sm font-bold border border-red-200">{error}</div>}
                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <label className="block text-xs font-black uppercase mb-1 text-black">Email Address</label>
                        <input type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full p-3 border-2 border-black font-bold focus:outline-none focus:ring-4 focus:ring-yellow-200 text-black bg-white" />
                    </div>
                    <div>
                        <label className="block text-xs font-black uppercase mb-1 text-black">Password</label>
                        <input type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full p-3 border-2 border-black font-bold focus:outline-none focus:ring-4 focus:ring-yellow-200 text-black bg-white" />
                    </div>
                    <button disabled={loading} className="w-full bg-black text-white py-4 font-black uppercase tracking-widest hover:bg-gray-800 transition-transform hover:scale-[1.02]">{loading ? <Loader2 className="animate-spin mx-auto"/> : 'Log In'}</button>
                </form>
                <div className="mt-6 text-center text-sm font-bold text-black">
                    <span className="text-gray-400">New here?</span> <button onClick={onSwitchToSignup} className="ml-1 underline hover:text-yellow-600">Create Account</button>
                </div>
            </div>
        </div>
    );
};

