    return (
        <div className="min-h-screen bg-black flex items-center justify-center p-4">
             <div className="bg-white w-full max-w-md p-8 border-4 border-yellow-400 shadow-[8px_8px_0px_#FACC15] max-h-[90vh] overflow-y-auto">
                <h1 className="text-4xl font-black mb-2 text-black">JOIN US.</h1>
                <p className="font-bold text-gray-500 mb-8 uppercase tracking-widest">Start your journey</p>

                <form onSubmit={handleSubmit} className="space-y-4">
                    <div className="flex justify-center mb-4">
                         <ImageUpload label="Profile Picture" onImageSelected={setAvatar} currentImage={avatar} />
                    </div>

                    <div>
                        <label className="block text-xs font-black uppercase mb-1 text-black">Full Name</label>
                        <input required type="text" value={name} onChange={e => setName(e.target.value)} className="w-full p-3 border-2 border-black font-bold focus:outline-none focus:ring-4 focus:ring-yellow-200 text-black bg-white" />
                    </div>
                    <div>
                        <label className="block text-xs font-black uppercase mb-1 text-black">Email Address</label>
                        <input required type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full p-3 border-2 border-black font-bold focus:outline-none focus:ring-4 focus:ring-yellow-200 text-black bg-white" />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                         <div>
                            <label className="block text-xs font-black uppercase mb-1 text-black">Year</label>
                            <select required className="w-full p-3 border-2 border-black font-bold focus:outline-none focus:ring-4 focus:ring-yellow-200 bg-white text-black" value={year} onChange={e => setYear(e.target.value)}>
                                <option value="">Select</option>
                                <option value="1st Year">1st Year</option>
                                <option value="2nd Year">2nd Year</option>
                                <option value="3rd Year">3rd Year</option>
                                <option value="4th Year">4th Year</option>
                            </select>
                        </div>
                        <div>
                            <label className="block text-xs font-black uppercase mb-1 text-black">Branch</label>
                            <input required type="text" placeholder="CSE..." value={branch} onChange={e => setBranch(e.target.value)} className="w-full p-3 border-2 border-black font-bold focus:outline-none focus:ring-4 focus:ring-yellow-200 text-black bg-white" />
                        </div>
                    </div>
                     <div>
                        <label className="block text-xs font-black uppercase mb-1 text-black">Password</label>
                        <input required type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full p-3 border-2 border-black font-bold focus:outline-none focus:ring-4 focus:ring-yellow-200 text-black bg-white" />
                    </div>
                    <button disabled={loading} className="w-full bg-yellow-400 text-black py-4 font-black uppercase tracking-widest hover:bg-yellow-300 hover:scale-[1.02] transition-transform">{loading ? <Loader2 className="animate-spin mx-auto"/> : 'Create Account'}</button>
                </form>
                <div className="mt-6 text-center text-sm font-bold text-black">
                    <span className="text-gray-400">Already have an account?</span> <button onClick={onSwitchToLogin} className="ml-1 underline hover:text-black">Log In</button>
                </div>
            </div>
        </div>
    );
};

const App = () => {
  const [user, setUser] = useState<User | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [authView, setAuthView] = useState<'login' | 'signup'>('login');

  const [activeTab, setActiveTab] = useState('feed');
  const [events, setEvents] = useState<Event[]>([]);
  const [clubs, setClubs] = useState<Club[]>([]);
  const [venues, setVenues] = useState<Venue[]>([]);
  const [userRegistrations, setUserRegistrations] = useState<string[]>([]);
  const [volunteerApps, setVolunteerApps] = useState<VolunteerApplication[]>([]);

  // Search state
  const [searchQuery, setSearchQuery] = useState('');
  const [filterPrice, setFilterPrice] = useState<'all' | 'free' | 'paid'>('all');

  // Modals
  const [selectedEvent, setSelectedEvent] = useState<Event | null>(null);
  const [paymentOpen, setPaymentOpen] = useState(false);
  const [qrOpen, setQrOpen] = useState(false);
  const [certOpen, setCertOpen] = useState(false);

  // Edit Profile
  const [isEditProfileOpen, setIsEditProfileOpen] = useState(false);
  // Feedback
  const [feedbackEvent, setFeedbackEvent] = useState<Event | null>(null);

  // Club Details
  const [selectedClub, setSelectedClub] = useState<Club | null>(null);

  useEffect(() => {
    if(isAuthenticated) fetchData();
  }, [user, isAuthenticated]);

  const fetchData = async () => {
    if (!user) return;
    try {
        const e = await api.events.list();
        setEvents(e);
        const c = await api.clubs.list();
        setClubs(c);
        const v = await api.venues.list();
        setVenues(v);
        if (api.auth.getRegistrations) {
            const regs = await api.auth.getRegistrations(user.id);
            setUserRegistrations(regs);
        }
        const vApps = await api.volunteers.listByUser(user.id);
        setVolunteerApps(vApps);
    } catch (err) {
        console.error("Failed to fetch data", err);
    }
  };

  const handleLogin = (u: User) => {
      setUser(u);
      setIsAuthenticated(true);
      if (u.role === UserRole.STUDENT) setActiveTab('feed');
      else if (u.role === UserRole.CLUB_ADMIN) setActiveTab('dashboard');
      else if (u.role === UserRole.COLLEGE_ADMIN) setActiveTab('approvals');
  };

  const handleLogout = () => {
      setIsAuthenticated(false);
      setUser(null);
      setAuthView('login');
  };

  const handleRegister = async (event: Event) => {
      if(!user) return;
      if (event.price > 0) {
          setSelectedEvent(event);
          setPaymentOpen(true);
      } else {
          await confirmRegistration(event);
      }
  };

  const confirmRegistration = async (event: Event) => {
      if(!user) return;
      await api.events.register(event.id, user.id);
      setUserRegistrations(prev => [...prev, event.id]);
      setEvents(prev => prev.map(e => e.id === event.id ? {...e, registeredCount: e.registeredCount + 1} : e));
      if (paymentOpen) setPaymentOpen(false);
  };

  const handleVolunteerApply = async (eventId: string) => {
      if(!user) return;
      try {
          const app: VolunteerApplication = {
              id: `v${Date.now()}`,
              eventId,
              userId: user.id,
              userName: user.name,
              userAvatar: user.avatar,
              status: VolunteerStatus.PENDING,
              appliedAt: new Date().toISOString()
          };
          await api.volunteers.apply(app);
          setVolunteerApps(prev => [...prev, app]);
      } catch (e: any) {
          alert(e.message);
      }
  };

  const handleUpdateProfile = async (data: Partial<User>) => {
      if (!user) return;
      const updatedUser = { ...user, ...data };
      await api.auth.updateProfile(updatedUser);
      setUser(updatedUser);
  };

  const handleFeedbackSubmit = async (rating: number, comment: string) => {
      if (!feedbackEvent || !user) return;
      const feedback: Feedback = { userId: user.id, rating, comment };
      await api.events.addFeedback(feedbackEvent.id, feedback);
      // Update local event state to reflect new feedback without full refetch
      setEvents(events.map(e => e.id === feedbackEvent.id ? {...e, feedback: [...(e.feedback || []), feedback]} : e));
      setFeedbackEvent(null);
  };

  // Auth Views
  if (!isAuthenticated) {
      return authView === 'login' 
        ? <LoginPage onLogin={handleLogin} onSwitchToSignup={() => setAuthView('signup')} />
        : <SignupPage onSignup={(u) => { setUser(u); setIsAuthenticated(true); setActiveTab('feed'); }} onSwitchToLogin={() => setAuthView('login')} />;
  }

  // Filtered Events for Feed
  const filteredEvents = events.filter(e => {
        if (e.status !== EventStatus.APPROVED) return false;
        if (filterPrice === 'free' && e.price > 0) return false;
        if (filterPrice === 'paid' && e.price === 0) return false;
        const query = searchQuery.toLowerCase();
        return (
          e.title.toLowerCase().includes(query) || 
          e.description.toLowerCase().includes(query) ||
          e.tags.some(tag => tag.toLowerCase().includes(query))
        );
  });

  if (!user) return null;

  return (
    <Layout user={user} onLogout={handleLogout} activeTab={activeTab} setActiveTab={setActiveTab}>

      {/* STUDENT VIEW */}
      {user.role === UserRole.STUDENT && (
        <>
           {/* ... Feed View ... */}
           {activeTab === 'feed' && (
               <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                   <div className="flex flex-col gap-4 border-b-4 border-black pb-6">
                      <div className="flex justify-between items-end">
                         <div>
                            <h2 className="text-4xl md:text-5xl font-black tracking-tighter mb-2">WHATS ON<span className="text-yellow-500">?</span></h2>
                            <p className="text-gray-500 font-medium">Discover and join campus activities.</p>
                         </div>
                      </div>
                      <div className="flex flex-col md:flex-row gap-4">
                         <div className="relative flex-1">
                            <input 
                            type="text" 
                            placeholder="Search events, tags..." 
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="pl-10 pr-4 py-3 border-2 border-black focus:outline-none focus:ring-4 focus:ring-yellow-400 w-full font-bold bg-white"
                            />
                            <Search className="absolute left-3 top-3.5 text-black" size={20} />
                         </div>
                         <div className="flex items-center gap-2">
                             <Filter size={20} className="text-gray-500" />
                             <select 
                                className="p-3 border-2 border-black font-bold bg-white focus:outline-none focus:ring-4 focus:ring-yellow-400"
                                value={filterPrice}
                                onChange={(e) => setFilterPrice(e.target.value as any)}
                             >
                                 <option value="all">All Prices</option>
                                 <option value="free">Free Only</option>
                                 <option value="paid">Paid Only</option>
                             </select>
                         </div>
                      </div>
                   </div>

                   <div className="grid gap-6">
                       {filteredEvents.map(event => (
                           <EventCard 
                             key={event.id} 
                             event={event} 
                             isAdminView={false}
                             isRegistered={userRegistrations.includes(event.id)}
                             onRegister={handleRegister}
                             venueName={venues.find(v => v.id === event.venueId)?.name || event.venueId}
                             onVolunteer={handleVolunteerApply}
                             volunteerStatus={volunteerApps.find(v => v.eventId === event.id)?.status}
                           />
                       ))}
                       {filteredEvents.length === 0 && <div className="text-center py-10 text-gray-400">No events found.</div>}
                   </div>
               </div>
           )}
           {activeTab === 'media' && <StudentMediaView user={user} />}
           {activeTab === 'clubs' && (
               selectedClub ? (
                    <StudentClubDetail 
                        club={selectedClub} 
                        onBack={() => setSelectedClub(null)} 
                        user={user} 
                        onUpdateUser={setUser}
                    />
               ) : (
                    <div className="grid grid-cols-1 gap-4 animate-in fade-in duration-300">
                        {clubs.length > 0 ? (
                            clubs.map(club => (
                            <div 
                                key={club.id} 
                                onClick={() => setSelectedClub(club)}
                                className="bg-white border-2 border-black p-4 flex gap-4 items-start cursor-pointer hover:bg-yellow-50 hover:-translate-y-1 transition-transform shadow-[4px_4px_0px_rgba(0,0,0,0.1)] hover:shadow-[6px_6px_0px_#FACC15]"
                            >
                                <img 
                                        src={club.logo} 
                                        onError={(e) => { e.currentTarget.src = `https://api.dicebear.com/7.x/initials/svg?seed=${club.name}`; }}
                                        className="w-16 h-16 border border-black object-cover flex-shrink-0" 
                                />
                                <div className="flex-1">
                                    <h3 className="font-black text-lg">{club.name}</h3>
                                    <p className="text-sm text-gray-600 line-clamp-2">{club.description || 'No description available.'}</p>
                                    <div className="mt-2 text-xs font-bold text-gray-400 flex items-center justify-between">
                                        <span>{club.memberCount} Members</span>
                                        <ChevronRight size={16} />
                                    </div>
                                </div>
                            </div>
                        ))) : (
                            <p className="text-gray-500 text-center py-8">No clubs found.</p>
                        )}
                    </div>
               )
           )}
           {activeTab === 'tickets' && (
               <div className="space-y-4">
                   <h2 className="text-2xl font-black">MY TICKETS</h2>
                   {events.filter(e => userRegistrations.includes(e.id)).length > 0 ? (
                       events.filter(e => userRegistrations.includes(e.id)).map(event => (
                       <div key={event.id} className="bg-white border-2 border-black p-4 group hover:shadow-[4px_4px_0px_#000] transition-shadow">
                           <div className="flex justify-between items-start mb-4" onClick={() => { setSelectedEvent(event); setQrOpen(true); }}>
                               <div className="cursor-pointer">
                                   <h3 className="font-black text-lg">{event.title}</h3>
                                   <p className="text-xs text-gray-500 font-bold uppercase">{event.date} | {event.time}</p>
                                   <p className="text-xs text-gray-400 mt-1">{venues.find(v => v.id === event.venueId)?.name || event.venueId}</p>
                               </div>
                               <QrCode size={40} className="text-black cursor-pointer" onClick={() => { setSelectedEvent(event); setQrOpen(true); }}/>
                           </div>

                           {/* Action Buttons */}
                           <div className="flex gap-2 pt-2 border-t border-gray-100">
                               <button 
                                 onClick={() => { setSelectedEvent(event); setQrOpen(true); }}
                                 className="flex-1 py-2 text-xs font-bold uppercase tracking-wide bg-gray-50 hover:bg-gray-100 flex items-center justify-center gap-1"
                               >
                                   <Ticket size={14} /> View Ticket
                               </button>
                               <button 
                                 onClick={() => setFeedbackEvent(event)}
                                 className="flex-1 py-2 text-xs font-bold uppercase tracking-wide bg-yellow-400 hover:bg-yellow-300 border border-black flex items-center justify-center gap-1"
                               >
                                   <Star size={14} /> Rate Event
                               </button>
                           </div>
                       </div>
                   ))) : (
                       <div className="text-center py-10 border-2 border-dashed border-gray-300">
                           <Ticket size={48} className="mx-auto text-gray-300 mb-2"/>
                           <p className="text-gray-500 font-medium">No tickets yet.</p>
                       </div>
                   )}
               </div>
           )}
           {activeTab === 'profile' && (
               <div className="space-y-6 animate-in fade-in duration-300">
                   <div className="bg-white border-2 border-black p-6 relative">
                       <button 
                         onClick={() => setIsEditProfileOpen(true)}
                         className="absolute top-4 right-4 p-2 hover:bg-gray-100 rounded-full transition-colors"
                         title="Edit Profile"
                       >
                         <UserCog size={20} />
                       </button>

                       <div className="flex flex-col items-center text-center">
                           <img 
                             src={user.avatar} 
                             alt={user.name}
                             onError={(e) => e.currentTarget.src = `https://api.dicebear.com/7.x/initials/svg?seed=${user.name}`}
                             className="w-32 h-32 rounded-full border-4 border-black mb-4 object-cover" 
                           />
                           <h2 className="text-2xl font-black uppercase">{user.name}</h2>
                           <p className="text-sm font-bold text-gray-400">{user.email}</p>
                           {user.bio ? (
                               <p className="mt-4 text-gray-600 max-w-sm italic font-medium">"{user.bio}"</p>
                           ) : (
                               <p className="mt-4 text-gray-400 text-xs italic">No bio added.</p>
                           )}

                           <div className="mt-6 flex justify-center gap-8 w-full border-t-2 border-dashed border-gray-200 pt-6">
                               <div className="text-center">
                                   <p className="font-black text-2xl">{userRegistrations.length}</p>
                                   <p className="text-[10px] uppercase font-bold text-gray-400 tracking-widest">Events</p>
                               </div>
                               <div className="text-center">
                                   <p className="font-black text-2xl">{(user.joinedClubIds || []).length}</p>
                                   <p className="text-[10px] uppercase font-bold text-gray-400 tracking-widest">Clubs</p>
                               </div>
                           </div>
                       </div>
                   </div>

                   {/* Certificates Section Moved Here */}
                   <div>
                       <h3 className="text-xl font-black uppercase mb-4 flex items-center gap-2">
                          <Award className="text-yellow-500" size={24}/> My Certificates
                       </h3>
                       <div className="space-y-3">
                           {events.filter(e => userRegistrations.includes(e.id) && e.certificatesIssued).length === 0 ? (
                               <div className="text-center py-6 border-2 border-dashed border-gray-200 bg-gray-50">
                                   <Award size={32} className="mx-auto text-gray-300 mb-2"/>
                                   <p className="text-gray-500 text-sm font-medium">No certificates earned yet.</p>
                               </div>
                           ) : (
                               events.filter(e => userRegistrations.includes(e.id) && e.certificatesIssued).map(event => (
                                    <div key={event.id} className="bg-white border-2 border-black p-4 flex justify-between items-center cursor-pointer hover:bg-yellow-50 transition" onClick={() => { setSelectedEvent(event); setCertOpen(true); }}>
                                        <div className="flex items-center gap-3">
                                            <div className="bg-green-100 p-2 rounded-full border border-green-300">
                                                <Award size={20} className="text-green-700"/>
                                            </div>
                                            <div>
                                               <h3 className="font-bold text-sm">{event.title}</h3>
                                               <p className="text-xs text-gray-500">Completed • {event.date}</p>
                                           </div>
                                        </div>
                                       <Download size={20} className="text-black"/>
                                    </div>
                               ))
                           )}
                       </div>
                   </div>

                   <button onClick={handleLogout} className="w-full bg-red-50 text-red-600 border-2 border-red-200 py-3 font-bold uppercase tracking-widest hover:bg-red-100 flex items-center justify-center gap-2 transition-colors"><LogOut size={16}/> Logout</button>
               </div>
           )}
        </>
      )}

      {/* CLUB ADMIN VIEW */}
      {user.role === UserRole.CLUB_ADMIN && (
          activeTab === 'profile' ? (
              <div className="bg-white border-2 border-black p-6 text-center relative">
                 <button 
                         onClick={() => setIsEditProfileOpen(true)}
                         className="absolute top-4 right-4 p-2 hover:bg-gray-100 rounded-full transition-colors"
                 >
                         <UserCog size={20} />
                 </button>
                 <img src={user.avatar} className="w-32 h-32 rounded-full border-4 border-black mx-auto mb-4" onError={(e) => e.currentTarget.src = `https://api.dicebear.com/7.x/initials/svg?seed=${user.name}`}/>
                 <h2 className="text-2xl font-black">{user.name}</h2>
                 <p className="text-gray-500 font-bold mb-4">Club Admin</p>
                 {user.bio && <p className="text-gray-600 italic mb-6">"{user.bio}"</p>}
                 <button onClick={handleLogout} className="mt-8 bg-red-500 text-white px-6 py-2 font-bold uppercase tracking-widest hover:bg-red-600 flex items-center gap-2 mx-auto"><LogOut size={16}/> Logout</button>
              </div>
          ) : (
              <ClubAdminDashboard user={user} refreshData={fetchData} activeTab={activeTab} />
          )
      )}

      {/* COLLEGE ADMIN VIEW */}
      {user.role === UserRole.COLLEGE_ADMIN && (
        <div className="space-y-6">
            {activeTab === 'approvals' && (
                <>
                    <h2 className="text-3xl font-black mb-6">PENDING APPROVALS</h2>
                    {events.filter(e => e.status === EventStatus.PENDING).length === 0 && <p className="text-gray-500">No pending events.</p>}
                    <div className="grid gap-6">
                        {events.filter(e => e.status === EventStatus.PENDING).map(event => (
                            <EventCard 
                                key={event.id}
                                event={event}
                                isAdminView={true}
                                onApprove={async (id) => {
                                    await api.events.updateStatus(id, EventStatus.APPROVED);
                                    fetchData();
                                }}
                                onReject={async (id, reason) => {
                                    await api.events.updateStatus(id, EventStatus.REJECTED, reason);
                                    fetchData();
                                }}
                            />
                        ))}
                    </div>
                </>
            )}
            {activeTab === 'clubs_manage' && (
                // ... (existing implementation)
                <div>
                    <h2 className="text-3xl font-black mb-6">CLUBS OVERVIEW</h2>
                     <div className="grid grid-cols-1 gap-4">
                        {clubs.length > 0 ? clubs.map(club => (
                            <div key={club.id} className="bg-white border-2 border-black p-4">
                                <div className="flex justify-between items-start">
                                    <div className="flex gap-4">
                                         <img src={club.logo} className="w-12 h-12 object-cover border border-black" onError={(e) => e.currentTarget.src = `https://api.dicebear.com/7.x/initials/svg?seed=${club.name}`}/>
                                         <div>
                                            <h3 className="font-black text-lg">{club.name}</h3>
                                            <p className="text-xs text-gray-500">Admin: {club.adminId}</p>
                                        </div>
                                    </div>
                                    <div className="bg-yellow-400 text-black px-2 py-1 text-xs font-bold border border-black">
                                        {club.memberCount} Members
                                    </div>
                                </div>
                            </div>
                        )) : <p className="text-gray-500">No clubs registered.</p>}
                    </div>
                </div>
            )}
            {activeTab === 'reports' && (
                 <div className="bg-white border-2 border-black p-8 text-center">
                     <BarChart3 size={48} className="mx-auto mb-4"/>
                     <h3 className="text-xl font-black">REPORTS DASHBOARD</h3>
                     <p className="text-gray-500">Comprehensive analytics.</p>
                 </div>
            )}
             {activeTab === 'profile' && (
               <div className="bg-white border-2 border-black p-6 text-center relative">
                   <button 
                         onClick={() => setIsEditProfileOpen(true)}
                         className="absolute top-4 right-4 p-2 hover:bg-gray-100 rounded-full transition-colors"
                   >
                         <UserCog size={20} />
                   </button>
                   <img src={user.avatar} className="w-32 h-32 rounded-full border-4 border-black mx-auto mb-4" onError={(e) => e.currentTarget.src = `https://api.dicebear.com/7.x/initials/svg?seed=${user.name}`}/>
                   <h2 className="text-2xl font-black">{user.name}</h2>
                   <p className="text-gray-500 font-bold mb-4">College Admin</p>
                   {user.bio && <p className="text-gray-600 italic mb-6">"{user.bio}"</p>}
                   <button onClick={handleLogout} className="mt-8 bg-red-500 text-white px-6 py-2 font-bold uppercase tracking-widest hover:bg-red-600 flex items-center gap-2 mx-auto"><LogOut size={16}/> Logout</button>
               </div>
           )}
        </div>
      )}

      {/* Global Modals */}
      <PaymentModal 
          isOpen={paymentOpen} 
          onClose={() => setPaymentOpen(false)} 
          event={selectedEvent} 
          onConfirm={() => selectedEvent && confirmRegistration(selectedEvent)} 
      />
      <TicketQRModal 
          isOpen={qrOpen} 
          onClose={() => setQrOpen(false)} 
          event={selectedEvent} 
          user={user} 
      />
      <CertificateModal 
          isOpen={certOpen} 
          onClose={() => setCertOpen(false)} 
          event={selectedEvent} 
          user={user} 
      />
      <FeedbackModal
          isOpen={!!feedbackEvent}
          onClose={() => setFeedbackEvent(null)}
          event={feedbackEvent}
          onSubmit={handleFeedbackSubmit}
      />

      {/* Edit Profile Modal */}
      {user && (
          <EditProfileModal 
              isOpen={isEditProfileOpen}
              onClose={() => setIsEditProfileOpen(false)}
              user={user}
              onUpdate={handleUpdateProfile}
          />
      )}

    </Layout>
  );
};

export default App;

import { User, Event, Club, Post, Venue, UserRole, VolunteerApplication, VolunteerStatus, Announcement, MediaPost, Feedback, Comment, Winner } from '../types';
import { supabase } from './supabaseClient';

// Helper to map DB response to types if needed (Supabase returns null for missing JSONB, we might need [] default)
const handleResponse = async <T>(promise: Promise<any>): Promise<T> => {
    const { data, error } = await promise;
    if (error) {
        console.error("Supabase Error:", error);
        throw new Error(error.message);
    }
    return data as T;
};

export const api = {
  auth: {
    login: async (email: string, password: string): Promise<User> => {
      // In a real app, use supabase.auth.signInWithPassword
      // For this migration keeping existing logic structure: query users table
      const { data, error } = await supabase
        .from('users')
        .select('*')
        .eq('email', email)
        .single();

      if (error || !data) throw new Error('Invalid credentials');
      // Simple password check (plaintext for this demo as requested in prompt feature list)
      if (data.password !== password) throw new Error('Invalid credentials');

      return data as User;
    },
    signup: async (user: User): Promise<User> => {
      const { error } = await supabase.from('users').insert(user);
      if (error) throw new Error(error.message);
      return user;
    },
    loginAsRole: async (role: UserRole): Promise<User> => {
      // Demo helper to switch roles - fetch first user of that role
      const { data, error } = await supabase
        .from('users')
        .select('*')
        .eq('role', role)
        .limit(1)
        .single();

      if (error || !data) throw new Error(`No user found with role ${role}`);
      return data as User;
    },
    updateProfile: async (user: User): Promise<User> => {
        const { error } = await supabase
            .from('users')
            .update(user)
            .eq('id', user.id);
        if (error) throw new Error(error.message);
        return user;
    },
    getRegistrations: async (userId: string): Promise<string[]> => {
        const { data, error } = await supabase
            .from('registrations')
            .select('eventId')
            .eq('userId', userId);
        if (error) return [];
        return data.map((r: any) => r.eventId);
    }
  },
  events: {
    list: async (clubId?: string): Promise<Event[]> => {
      let query = supabase.from('events').select('*');
      if (clubId) {
          query = query.eq('clubId', clubId);
      }
      const { data, error } = await query;
      if (error) throw new Error(error.message);
      return data || [];
    },
    create: async (event: Event): Promise<Event> => {
      const { error } = await supabase.from('events').insert(event);
      if (error) throw new Error(error.message);
      return event;
    },
    update: async (event: Event): Promise<Event> => {
        const { error } = await supabase
            .from('events')
            .update(event)
            .eq('id', event.id);
        if (error) throw new Error(error.message);
        return event;
    },
    updateStatus: async (eventId: string, status: any, reason?: string): Promise<Event> => {
       const updateData: any = { status };
       if (reason) updateData.rejectionReason = reason;
       if (status === 'PENDING') updateData.rejectionReason = null; // Clear reason

       const { data, error } = await supabase
         .from('events')
         .update(updateData)
         .eq('id', eventId)
         .select()
         .single();

       if (error) throw new Error(error.message);
       return data;
    },
    register: async (eventId: string, userId: string): Promise<void> => {
        // 1. Add to registrations table
        const { error: regError } = await supabase
            .from('registrations')
            .insert({ eventId, userId });

        if (regError) {
            // Ignore duplicate key error if user clicks twice quickly
            if (regError.code !== '23505') throw new Error(regError.message);
        }

        // 2. Increment count (Atomic increment is better, but simple update for now)
        // Fetch current count first (safe enough for this scale)
        const { data: event } = await supabase.from('events').select('registeredCount').eq('id', eventId).single();
        if (event) {
             await supabase.from('events').update({ registeredCount: (event.registeredCount || 0) + 1 }).eq('id', eventId);
        }
    },
    getRegisteredUsers: async (eventId: string): Promise<User[]> => {
        // 1. Get user IDs from registrations table
        const { data: regs, error: regError } = await supabase
            .from('registrations')
            .select('userId')
            .eq('eventId', eventId);

        if (regError) throw new Error(regError.message);
        if (!regs || regs.length === 0) return [];

        const userIds = regs.map((r: any) => r.userId);

        // 2. Fetch User details
        const { data: users, error: userError } = await supabase
            .from('users')
            .select('*')
            .in('id', userIds);

        if (userError) throw new Error(userError.message);
        return users || [];
    },
    addFeedback: async (eventId: string, feedback: Feedback): Promise<void> => {
        const { data: event } = await supabase.from('events').select('feedback').eq('id', eventId).single();
        const currentFeedback = event?.feedback || [];

        await supabase
            .from('events')
            .update({ feedback: [...currentFeedback, feedback] })
            .eq('id', eventId);
    },
    issueCertificates: async (eventId: string): Promise<void> => {
        await supabase.from('events').update({ certificatesIssued: true }).eq('id', eventId);
    },
    saveWinners: async (eventId: string, winners: Winner[]): Promise<void> => {
        await supabase.from('events').update({ winners }).eq('id', eventId);
    }
  },
  clubs: {
    list: async (): Promise<Club[]> => {
      const { data, error } = await supabase.from('clubs').select('*');
      if (error) return [];
      return data;
    },
    join: async (clubId: string, userId: string): Promise<User> => {
        // Fetch User
        const { data: user } = await supabase.from('users').select('*').eq('id', userId).single();
        if (!user) throw new Error("User not found");

        const joinedClubIds = user.joinedClubIds || [];
        if (!joinedClubIds.includes(clubId)) {
            const newJoined = [...joinedClubIds, clubId];

            // Update User
            await supabase.from('users').update({ joinedClubIds: newJoined }).eq('id', userId);

            // Update Club Count
            const { data: club } = await supabase.from('clubs').select('memberCount').eq('id', clubId).single();
            if (club) {
                await supabase.from('clubs').update({ memberCount: (club.memberCount || 0) + 1 }).eq('id', clubId);
            }

            return { ...user, joinedClubIds: newJoined };
        }
        return user;
    },
    leave: async (clubId: string, userId: string): Promise<User> => {
        const { data: user } = await supabase.from('users').select('*').eq('id', userId).single();
        if (!user) throw new Error("User not found");

        const joinedClubIds = user.joinedClubIds || [];
        const newJoined = joinedClubIds.filter((id: string) => id !== clubId);

        await supabase.from('users').update({ joinedClubIds: newJoined }).eq('id', userId);

        const { data: club } = await supabase.from('clubs').select('memberCount').eq('id', clubId).single();
        if (club) {
            await supabase.from('clubs').update({ memberCount: Math.max(0, (club.memberCount || 0) - 1) }).eq('id', clubId);
        }

        return { ...user, joinedClubIds: newJoined };
    }
  },
  posts: {
    list: async (clubId: string): Promise<Post[]> => {
      const { data, error } = await supabase
        .from('posts')
        .select('*')
        .eq('clubId', clubId)
        .order('timestamp', { ascending: false });

      if (error) return [];
      return data || [];
    },
    create: async (post: Post): Promise<Post> => {
      const { error } = await supabase.from('posts').insert(post);
      if (error) throw new Error(error.message);
      return post;
    },
    like: async (postId: string, userId: string): Promise<void> => {
        const { data: post } = await supabase.from('posts').select('likedBy').eq('id', postId).single();
        if (post) {
            const likedBy = post.likedBy || [];
            const newLikedBy = likedBy.includes(userId) 
                ? likedBy.filter((id: string) => id !== userId)
                : [...likedBy, userId];

            await supabase.from('posts').update({ likedBy: newLikedBy }).eq('id', postId);
        }
    },
    comment: async (postId: string, comment: Comment): Promise<void> => {
        const { data: post } = await supabase.from('posts').select('comments').eq('id', postId).single();
        if (post) {
            const comments = post.comments || [];
            await supabase.from('posts').update({ comments: [...comments, comment] }).eq('id', postId);
        }
    }
  },
  venues: {
      list: async (): Promise<Venue[]> => {
          const { data } = await supabase.from('venues').select('*');
          return data || [];
      }
  },
  volunteers: {
    apply: async (application: VolunteerApplication): Promise<VolunteerApplication> => {
        // Check duplicate
        const { data } = await supabase.from('volunteers')
            .select('*')
            .eq('eventId', application.eventId)
            .eq('userId', application.userId);

        if (data && data.length > 0) throw new Error("Already applied");

        const { error } = await supabase.from('volunteers').insert(application);
        if (error) throw new Error(error.message);
        return application;
    },
    listByEvent: async (eventId: string): Promise<VolunteerApplication[]> => {
        const { data } = await supabase.from('volunteers').select('*').eq('eventId', eventId);
        return data || [];
    },
    listByUser: async (userId: string): Promise<VolunteerApplication[]> => {
        const { data } = await supabase.from('volunteers').select('*').eq('userId', userId);
        return data || [];
    },
    updateStatus: async (appId: string, status: VolunteerStatus): Promise<void> => {
        await supabase.from('volunteers').update({ status }).eq('id', appId);
    }
  },
  announcements: {
      list: async (clubId: string): Promise<Announcement[]> => {
          const { data } = await supabase.from('announcements')
            .select('*')
            .eq('clubId', clubId)
            .order('date', { ascending: false });
          return data || [];
      },
      create: async (announcement: Announcement): Promise<Announcement> => {
          await supabase.from('announcements').insert(announcement);
          return announcement;
      }
  },
  media: {
      list: async (clubId?: string): Promise<MediaPost[]> => {
          let query = supabase.from('media').select('*');
          if (clubId) {
              query = query.eq('clubId', clubId);
          }
          const { data } = await query;
          return data || [];
      },
      create: async (media: MediaPost): Promise<MediaPost> => {
          await supabase.from('media').insert(media);
          return media;
      },
      like: async (mediaId: string, userId: string): Promise<void> => {
          const { data: m } = await supabase.from('media').select('likedBy').eq('id', mediaId).single();
          if (m) {
              const likedBy = m.likedBy || [];
              const newLikedBy = likedBy.includes(userId) 
                  ? likedBy.filter((id: string) => id !== userId)
                  : [...likedBy, userId];

              await supabase.from('media').update({ likedBy: newLikedBy }).eq('id', mediaId);
          }
      },
      comment: async (mediaId: string, comment: Comment): Promise<void> => {
          const { data: m } = await supabase.from('media').select('comments').eq('id', mediaId).single();
          if (m) {
              const comments = m.comments || [];
              await supabase.from('media').update({ comments: [...comments, comment] }).eq('id', mediaId);
          }
      }
  }
};

