const EventCard = ({ 
  event, 
  isAdminView = false, 
  isRegistered = false, 
  onRegister, 
  onApprove, 
  onReject, 
  venueName,
  onVolunteer,
  volunteerStatus,
  onGeneratePoster,
  onIssueCertificates,
  onEdit,
  onClick
}: { 
  event: Event, 
  isAdminView?: boolean, 
  isRegistered?: boolean, 
  onRegister?: (e: Event) => void, 
  onApprove?: (id: string) => void, 
  onReject?: (id: string, reason: string) => void, 
  venueName?: string,
  onVolunteer?: (id: string) => void,
  volunteerStatus?: VolunteerStatus,
  onGeneratePoster?: (e: Event) => void,
  onIssueCertificates?: (e: Event) => void,
  onEdit?: (e: Event) => void,
  onClick?: () => void
}) => {
  const [rejectReason, setRejectReason] = useState("");
  const [showRejectInput, setShowRejectInput] = useState(false);

  return (
    <div 
        className={`bg-white border-2 border-black group transition-all duration-300 hover:shadow-[8px_8px_0px_#000] relative overflow-hidden flex flex-col h-full`}
        onClick={onClick}
    >
      {/* Image */}
      <div className="h-48 overflow-hidden relative border-b-2 border-black">
        <img 
            src={event.image} 
            alt={event.title} 
            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" 
            onError={(e) => { e.currentTarget.src = "https://via.placeholder.com/800x400/000000/FACC15?text=CLIX"; }}
        />
        <div className="absolute top-3 right-3 flex gap-2">
            <StatusBadge status={event.status} />
            {event.price === 0 ? (
                <span className="bg-green-400 text-black px-2 py-1 text-[10px] font-black uppercase tracking-widest border border-black shadow-[2px_2px_0px_rgba(0,0,0,1)]">Free</span>
            ) : (
                <span className="bg-yellow-400 text-black px-2 py-1 text-[10px] font-black uppercase tracking-widest border border-black shadow-[2px_2px_0px_rgba(0,0,0,1)]">₹{event.price}</span>
            )}
        </div>
      </div>

      {/* Content */}
      <div className="p-5 flex-1 flex flex-col">
        <div className="flex justify-between items-start mb-2">
            <div>
                <p className="text-[10px] font-black uppercase tracking-widest text-gray-500 mb-1">{event.date} • {event.time}</p>
                <h3 className="text-xl font-black leading-tight mb-1">{event.title}</h3>
                <p className="text-xs font-bold text-gray-400">{event.organizer} @ {venueName || event.venueId}</p>
            </div>
        </div>

        <p className="text-sm text-gray-600 font-medium mb-4 line-clamp-2 flex-1">{event.description}</p>

        {/* Tags */}
        <div className="flex flex-wrap gap-2 mb-4">
            {event.tags.map(tag => (
                <span key={tag} className="text-[10px] bg-gray-100 px-2 py-1 font-bold uppercase tracking-wide border border-gray-200">{tag}</span>
            ))}
        </div>

        {/* Action Area */}
        <div className="mt-auto pt-4 border-t-2 border-dashed border-gray-200 space-y-3">
             {/* Progress Bar for capacity */}
             {event.status === EventStatus.APPROVED && (
                 <div>
                    <div className="flex justify-between text-[10px] font-bold uppercase mb-1">
                        <span>{event.registeredCount} / {event.capacity} Registered</span>
                        <span className={event.registeredCount >= event.capacity ? "text-red-500" : "text-green-500"}>
                            {event.registeredCount >= event.capacity ? "Full" : "Open"}
                        </span>
                    </div>
                    <div className="h-2 w-full bg-gray-200 rounded-full overflow-hidden border border-black">
                        <div 
                            className="h-full bg-yellow-400" 
                            style={{ width: `${Math.min((event.registeredCount / event.capacity) * 100, 100)}%` }}
                        ></div>
                    </div>
                 </div>
             )}

             {/* Admin Actions */}
             {isAdminView && onApprove && onReject && event.status === EventStatus.PENDING && (
                 <div className="space-y-2">
                     {!showRejectInput ? (
                         <div className="flex gap-2">
                             <button 
                                onClick={(e) => { e.stopPropagation(); onApprove(event.id); }}
                                className="flex-1 bg-green-500 text-white py-2 font-bold uppercase tracking-widest hover:bg-green-600 border border-black shadow-[2px_2px_0px_#000]"
                             >
                                Approve
                             </button>
                             <button 
                                onClick={(e) => { e.stopPropagation(); setShowRejectInput(true); }}
                                className="flex-1 bg-red-500 text-white py-2 font-bold uppercase tracking-widest hover:bg-red-600 border border-black shadow-[2px_2px_0px_#000]"
                             >
                                Reject
                             </button>
                         </div>
                     ) : (
                         <div className="flex gap-2" onClick={e => e.stopPropagation()}>
                             <input 
                                type="text" 
                                placeholder="Reason..." 
                                className="flex-1 border-2 border-black p-2 text-xs font-bold"
                                value={rejectReason}
                                onChange={e => setRejectReason(e.target.value)}
                             />
                             <button onClick={() => onReject(event.id, rejectReason)} className="bg-red-500 text-white px-3 font-bold uppercase border border-black">Confirm</button>
                             <button onClick={() => setShowRejectInput(false)} className="bg-gray-200 text-black px-3 font-bold uppercase border border-black">X</button>
                         </div>
                     )}
                 </div>
             )}

            {/* Club Admin Actions */}
             {isAdminView && onEdit && (
                 <div className="flex gap-2 flex-wrap">
                     <button onClick={(e) => { e.stopPropagation(); onEdit(event); }} className="flex-1 bg-black text-white py-2 text-xs font-bold uppercase hover:bg-gray-800">Edit</button>
                     {event.status === EventStatus.COMPLETED && (
                         <>
                            <button onClick={(e) => { e.stopPropagation(); onGeneratePoster?.(event); }} className="flex-1 bg-yellow-400 text-black py-2 text-xs font-bold uppercase border border-black hover:bg-yellow-500">Poster</button>
                            {!event.certificatesIssued && <button onClick={(e) => { e.stopPropagation(); onIssueCertificates?.(event); }} className="flex-1 bg-white text-black py-2 text-xs font-bold uppercase border border-black hover:bg-gray-50">Certs</button>}
                         </>
                     )}
                 </div>
             )}

             {/* Student Actions */}
             {!isAdminView && onRegister && (
                 <div className="flex gap-2">
                     {isRegistered ? (
                         <button disabled className="flex-1 bg-gray-100 text-green-600 py-3 font-bold uppercase tracking-widest border border-gray-200 flex items-center justify-center gap-2 cursor-default">
                             <Check size={18} /> Registered
                         </button>
                     ) : (
                         <button 
                            onClick={(e) => { e.stopPropagation(); onRegister(event); }}
                            disabled={event.registeredCount >= event.capacity}
                            className="flex-1 bg-black text-white py-3 font-bold uppercase tracking-widest hover:bg-gray-800 border-2 border-black shadow-[4px_4px_0px_#FACC15] active:shadow-none active:translate-x-[2px] active:translate-y-[2px] transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                         >
                            {event.registeredCount >= event.capacity ? 'Sold Out' : (event.price > 0 ? 'Buy Ticket' : 'Register Now')}
                         </button>
                     )}

                     {/* Volunteer Button */}
                     {event.volunteersNeeded && onVolunteer && (
                         volunteerStatus ? (
                             <div className="px-3 py-2 border border-gray-200 bg-gray-50 flex items-center justify-center">
                                 <VolunteerBadge status={volunteerStatus} />
                             </div>
                         ) : (
                            <button 
                                onClick={(e) => { e.stopPropagation(); onVolunteer(event.id); }}
                                className="px-3 py-2 border-2 border-black bg-white hover:bg-gray-100 text-black"
                                title="Apply as Volunteer"
                            >
                                <Hand size={20} />
                            </button>
                         )
                     )}
                 </div>
             )}
        </div>
      </div>
    </div>
  );
};

const StudentMediaView = ({ user }: { user: User }) => {
    const [media, setMedia] = useState<MediaPost[]>([]);
    const [loading, setLoading] = useState(true);
    const [newComment, setNewComment] = useState("");
    const [activeCommentId, setActiveCommentId] = useState<string | null>(null);

    useEffect(() => {
        api.media.list().then(m => {
            setMedia(m.reverse()); // Newest first
            setLoading(false);
        });
    }, []);

    const handleLike = async (m: MediaPost) => {
        // Optimistic update
        const isLiked = m.likedBy.includes(user.id);
        const newLikedBy = isLiked ? m.likedBy.filter(id => id !== user.id) : [...m.likedBy, user.id];
        setMedia(media.map(item => item.id === m.id ? { ...item, likedBy: newLikedBy } : item));

        await api.media.like(m.id, user.id);
    };

    const handleComment = async (m: MediaPost) => {
        if (!newComment.trim()) return;
        const comment: Comment = {
            id: `c${Date.now()}`,
            userId: user.id,
            userName: user.name,
            text: newComment,
            timestamp: new Date().toISOString()
        };

        // Optimistic
        setMedia(media.map(item => item.id === m.id ? { ...item, comments: [...item.comments, comment] } : item));
        setNewComment("");
        setActiveCommentId(null);

        await api.media.comment(m.id, comment);
    };

    if (loading) return <div className="p-10 flex justify-center"><Loader2 className="animate-spin" size={32}/></div>;

    return (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in fade-in duration-500">
            {media.map(item => {
                const isLiked = item.likedBy.includes(user.id);
                return (
                    <div key={item.id} className="bg-white border-2 border-black shadow-[8px_8px_0px_#000]">
                        <div className="relative">
                            <img src={item.imageUrl} className="w-full h-64 object-cover border-b-2 border-black" />
                            <div className="absolute bottom-4 left-4 bg-white/90 backdrop-blur-sm px-3 py-1 border border-black text-xs font-bold uppercase">
                                {item.caption}
                            </div>
                        </div>
                        <div className="p-4">
                            <div className="flex items-center justify-between mb-4">
                                <div className="flex gap-4">
                                    <button onClick={() => handleLike(item)} className={`flex items-center gap-1 font-bold ${isLiked ? 'text-red-500' : 'text-gray-500 hover:text-black'}`}>
                                        <Heart size={20} fill={isLiked ? "currentColor" : "none"} /> {item.likedBy.length}
                                    </button>
                                    <button onClick={() => setActiveCommentId(activeCommentId === item.id ? null : item.id)} className="flex items-center gap-1 font-bold text-gray-500 hover:text-black">
                                        <MessageSquare size={20} /> {item.comments.length}
                                    </button>
                                </div>
                                <button className="text-gray-500 hover:text-black"><Send size={20} /></button>
                            </div>

                            {/* Comments */}
                            {activeCommentId === item.id && (
                                <div className="mt-4 border-t border-gray-100 pt-4 animate-in slide-in-from-top-2">
                                    <div className="max-h-40 overflow-y-auto space-y-2 mb-3">
                                        {item.comments.map(c => (
                                            <div key={c.id} className="text-xs">
                                                <span className="font-bold">{c.userName}</span> <span className="text-gray-600">{c.text}</span>
                                            </div>
                                        ))}
                                    </div>
                                    <div className="flex gap-2">
                                        <input 
                                            type="text" 
                                            placeholder="Add a comment..."
                                            className="flex-1 border border-black p-2 text-xs font-bold focus:outline-none"
                                            value={newComment}
                                            onChange={e => setNewComment(e.target.value)}
                                        />
                                        <button onClick={() => handleComment(item)} className="bg-black text-white px-3 font-bold uppercase text-xs">Post</button>
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>
                );
            })}
            {media.length === 0 && <div className="col-span-2 text-center py-10 text-gray-400">No media posts yet.</div>}
        </div>
    );
};

const ClubAdminDashboard = ({ user, refreshData, activeTab }: { user: User, refreshData: () => void, activeTab: string }) => {
    const [events, setEvents] = useState<Event[]>([]);
    const [announcements, setAnnouncements] = useState<Announcement[]>([]);
    const [announcementText, setAnnouncementText] = useState('');
    const [mediaList, setMediaList] = useState<MediaPost[]>([]);
    const [isPosting, setIsPosting] = useState(false);

    // Proposal State
    const [isProposalModalOpen, setIsProposalModalOpen] = useState(false);
    const [proposalTopic, setProposalTopic] = useState('');
    const [generatedDesc, setGeneratedDesc] = useState('');
    const [isGenerating, setIsGenerating] = useState(false);
    const [newProposal, setNewProposal] = useState<Partial<Event>>({
      title: '', description: '', date: '', time: '', venueId: '', capacity: 0, price: 0, volunteersNeeded: false, image: ''
    });
    const [venues, setVenues] = useState<Venue[]>([]);
    const [editingEventId, setEditingEventId] = useState<string | null>(null);

    // Media Upload State
    const [mediaEventId, setMediaEventId] = useState('');
    const [mediaUrl, setMediaUrl] = useState('');
    const [mediaCaption, setMediaCaption] = useState('');

    // Winners Poster State
    const [posterEvent, setPosterEvent] = useState<Event | null>(null);
    const [winners, setWinners] = useState<Winner[]>([
        { rank: 1, name: '', photo: '' },
        { rank: 2, name: '', photo: '' },
        { rank: 3, name: '', photo: '' }
    ]);
    const [generatedPoster, setGeneratedPoster] = useState(false);

    // Event Management State
    const [manageEvent, setManageEvent] = useState<Event | null>(null);
    const [manageVolunteers, setManageVolunteers] = useState<VolunteerApplication[]>([]);
    const [manageRegisteredUsers, setManageRegisteredUsers] = useState<User[]>([]);

    useEffect(() => {
        api.events.list().then(setEvents);
        api.venues.list().then(setVenues);
        if (user.clubId) {
            api.announcements.list(user.clubId).then(setAnnouncements);
        }
        api.media.list().then(m => setMediaList(m.filter(x => x.clubId === user.clubId)));
    }, [user.clubId]);

    const handleAddAnnouncement = async () => {
        if(!user.clubId || !announcementText.trim()) return;
        setIsPosting(true);
        try {
            const ann: Announcement = {
                id: `a${Date.now()}`,
                clubId: user.clubId,
                content: announcementText,
                date: new Date().toISOString()
            };
            await api.announcements.create(ann);
            setAnnouncements([ann, ...announcements]);
            setAnnouncementText('');
            alert("Announcement Posted!");
        } catch(e) {
            alert("Failed to post announcement");
        } finally {
            setIsPosting(false);
        }
    };

    // Calculate Dashboard Metrics
    const myEvents = events.filter(e => e.clubId === user.clubId);
    const myMedia = mediaList.filter(m => m.clubId === user.clubId);

    // Total Reach: Sum of unique user interactions (likes/comments on media) + Event Registrations
    const totalReach = 
        myEvents.reduce((acc, e) => acc + e.registeredCount, 0) + 
        myMedia.reduce((acc, m) => acc + (m.likedBy?.length || 0) + (m.comments?.length || 0), 0);

    // Avg Rating: Average of all feedback ratings
    const allFeedbacks = myEvents.flatMap(e => e.feedback || []);
    const totalRatingSum = allFeedbacks.reduce((acc, f) => acc + f.rating, 0);
    const avgRating = allFeedbacks.length > 0 ? (totalRatingSum / allFeedbacks.length).toFixed(1) : 'N/A';

    // Revenue: Sum of (Price * RegisteredCount)
    const totalRevenue = myEvents.reduce((acc, e) => acc + (e.price * e.registeredCount), 0);

    const handleAiGenerate = async () => {
        if (!proposalTopic) return;
        setIsGenerating(true);
        const desc = await generateEventContent(proposalTopic, 'description');
        setGeneratedDesc(desc);
        setNewProposal({ ...newProposal, description: desc });
        setIsGenerating(false);
    };

    // ... handleSubmitProposal, handleEditEvent, handleUploadMedia ...
    const handleSubmitProposal = async (e: React.FormEvent) => {
        e.preventDefault();

        // If editing existing rejected event, update it. Else create new.
        if (editingEventId) {
            const existingEvent = events.find(e => e.id === editingEventId);
            if (existingEvent) {
                const updatedEvent: Event = {
                    ...existingEvent,
                    ...newProposal,
                    title: newProposal.title || existingEvent.title,
                    description: newProposal.description || existingEvent.description,
                    date: newProposal.date || existingEvent.date,
                    time: newProposal.time || existingEvent.time,
                    venueId: newProposal.venueId || existingEvent.venueId,
                    capacity: newProposal.capacity || existingEvent.capacity,
                    price: newProposal.price || existingEvent.price,
                    image: newProposal.image || existingEvent.image,
                    volunteersNeeded: newProposal.volunteersNeeded,
                    status: EventStatus.PENDING, // Reset status to PENDING for review
                    rejectionReason: undefined // Clear reason
                } as Event;
                await api.events.update(updatedEvent);
                alert("Proposal updated and re-submitted for approval.");
            }
        } else {
             const event: Event = {
                id: `e${Date.now()}`,
                title: newProposal.title || 'Untitled Event',
                description: newProposal.description || generatedDesc || 'No description provided.',
                organizer: 'My Club', 
                clubId: user.clubId || 'c1',
                date: newProposal.date || '2024-01-01',
                time: newProposal.time || '12:00',
                venueId: newProposal.venueId || 'v1',
                status: EventStatus.PENDING,
                capacity: newProposal.capacity || 100,
                registeredCount: 0,
                tags: ['New'],
                price: newProposal.price || 0,
                image: newProposal.image || `https://picsum.photos/800/400?random=${Date.now()}`,
                volunteersNeeded: newProposal.volunteersNeeded
            };
            await api.events.create(event);
            alert("Proposal submitted for College Admin approval.");
        }

        setIsProposalModalOpen(false);
        setNewProposal({});
        setEditingEventId(null);
        setProposalTopic('');
        setGeneratedDesc('');
        refreshData(); 

        const updatedEvents = await api.events.list();
        setEvents(updatedEvents);
    };

    const handleEditEvent = (event: Event) => {
        setEditingEventId(event.id);
        setNewProposal({
            title: event.title,
            description: event.description,
            date: event.date,
            time: event.time,
            venueId: event.venueId,
            capacity: event.capacity,
            price: event.price,
            image: event.image,
            volunteersNeeded: event.volunteersNeeded
        });
        setIsProposalModalOpen(true);
    };

    const handleUploadMedia = async (e: React.FormEvent) => {
        e.preventDefault();
        if(!mediaEventId || !mediaUrl || !user.clubId) return;
        const newMedia: MediaPost = {
            id: `m${Date.now()}`,
            clubId: user.clubId,
            eventId: mediaEventId,
            imageUrl: mediaUrl,
            caption: mediaCaption || 'Event Highlights',
            likedBy: [],
            comments: []
        };
        await api.media.create(newMedia);
        setMediaList([...mediaList, newMedia]);
        setMediaUrl('');
        setMediaEventId('');
        setMediaCaption('');
        alert("Media Uploaded!");
    };

    const handleIssueCertificates = async (event: Event) => {
        if(confirm(`Issue certificates to all ${event.registeredCount} participants for ${event.title}?`)) {
            await api.events.issueCertificates(event.id);
            setEvents(events.map(e => e.id === event.id ? {...e, certificatesIssued: true} : e));
            alert("Certificates Issued!");
        }
    };

    const handleGeneratePoster = async () => {
        if (!posterEvent) return;
        // Save winners to event
        await api.events.saveWinners(posterEvent.id, winners);
        setGeneratedPoster(true);
    };

    // New: Open Event Management Modal
    const handleOpenEventManagement = async (event: Event) => {
        if (event.status !== EventStatus.APPROVED && event.status !== EventStatus.COMPLETED) return;
        setManageEvent(event);
        // Parallel fetching
        const [vols, users] = await Promise.all([
            api.volunteers.listByEvent(event.id),
            api.events.getRegisteredUsers(event.id)
        ]);
        setManageVolunteers(vols);
        setManageRegisteredUsers(users);
    };

    const handleUpdateVolunteer = async (appId: string, status: VolunteerStatus) => {
        await api.volunteers.updateStatus(appId, status);
        setManageVolunteers(prev => prev.map(v => v.id === appId ? { ...v, status } : v));
    };

    const analyticsData = [
      { name: 'Hackathon', participants: 150 },
      { name: 'AI Talk', participants: 80 },
      { name: 'Web Dev', participants: 200 },
    ];

    return (
      <div className="space-y-8 animate-in fade-in duration-500">

        {activeTab === 'dashboard' && (
            <div className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div className="bg-black text-yellow-400 p-8 shadow-[8px_8px_0px_#FACC15] border-2 border-black">
                        <h3 className="text-sm font-bold opacity-80 uppercase tracking-widest mb-2">Total Reach</h3>
                        <p className="text-5xl font-black">{totalReach.toLocaleString()}</p>
                    </div>
                    <div className="bg-white text-black p-8 shadow-[8px_8px_0px_#000] border-2 border-black">
                        <h3 className="text-sm font-bold text-gray-500 uppercase tracking-widest mb-2">Avg Rating</h3>
                        <p className="text-5xl font-black">{avgRating}</p>
                    </div>
                    <div className="bg-yellow-400 text-black p-8 border-2 border-black">
                        <h3 className="text-sm font-bold opacity-80 uppercase tracking-widest mb-2">Total Revenue</h3>
                        <p className="text-5xl font-black">₹{totalRevenue.toLocaleString()}</p>
                    </div>
                </div>

                <div className="bg-white border-2 border-black p-6 shadow-sm">
                    <h3 className="text-xl font-black mb-4 flex items-center gap-2"><Megaphone size={24} /> POST ANNOUNCEMENT</h3>
                    <div className="flex gap-4">
                        <textarea 
                        className="flex-1 p-3 border-2 border-gray-200 focus:border-black focus:outline-none font-medium" 
                        rows={2}
                        placeholder="Share updates with your club members..."
                        value={announcementText}
                        onChange={e => setAnnouncementText(e.target.value)}
                        />
                        <button 
                        onClick={handleAddAnnouncement}
                        disabled={isPosting}
                        className="bg-black text-white px-6 font-bold uppercase tracking-widest hover:bg-gray-800 disabled:opacity-50"
                        >
                            {isPosting ? <Loader2 className="animate-spin" /> : 'Post'}
                        </button>
                    </div>
                    <div className="mt-4 space-y-2">
                        {announcements.map(a => (
                            <div key={a.id} className="bg-gray-50 p-2 border-l-4 border-yellow-400 text-sm">
                                {a.content} <span className="text-gray-400 text-xs ml-2">{new Date(a.date).toLocaleDateString()}</span>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="bg-white p-8 border-2 border-black shadow-sm">
                    <h3 className="text-xl font-black mb-6 border-b-2 border-gray-100 pb-4">PARTICIPATION ANALYTICS</h3>
                    <div className="h-64 w-full">
                        <ResponsiveContainer width="100%" height="100%">
                        <BarChart data={analyticsData}>
                            <XAxis dataKey="name" stroke="#000" fontSize={12} tickLine={false} axisLine={false} />
                            <YAxis stroke="#000" fontSize={12} tickLine={false} axisLine={false} />
                            <Tooltip cursor={{fill: '#fefce8'}} contentStyle={{ background: '#000', color: '#fff', border: 'none', fontWeight: 'bold' }} />
                            <Bar dataKey="participants" fill="#FACC15" radius={[0, 0, 0, 0]} barSize={50} stroke="#000" strokeWidth={2} />
                        </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>
            </div>
        )}

        {/* ... Rest of ClubAdminDashboard (events, media tabs and modals) ... */}
        {activeTab === 'events' && (
            <div>
                <div className="flex justify-between items-center mb-6">
                    <h2 className="text-3xl font-black uppercase tracking-tight">Events & Proposals</h2>
                    <button 
                    onClick={() => {
                        setEditingEventId(null);
                        setNewProposal({});
                        setIsProposalModalOpen(true);
                    }}
                    className="bg-black text-white px-6 py-3 text-sm font-bold uppercase tracking-wider hover:bg-gray-800 hover:scale-105 transition-transform flex items-center gap-2 border-2 border-transparent hover:border-yellow-400"
                    >
                    <Sparkles size={16} className="text-yellow-400" /> New Proposal
                    </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {events.filter(e => e.clubId === user?.clubId).map(event => (
                    <EventCard 
                        key={event.id} 
                        event={event} 
                        isAdminView={true}
                        onGeneratePoster={() => {
                            setPosterEvent(event);
                            setGeneratedPoster(!!event.winners); 
                            if (event.winners) setWinners(event.winners);
                        }}
                        onIssueCertificates={handleIssueCertificates}
                        onEdit={handleEditEvent}
                        onClick={() => handleOpenEventManagement(event)}
                    />
                    ))}
                </div>
            </div>
        )}

        {activeTab === 'media' && (
            <div className="space-y-8">
                <div className="bg-white p-6 border-2 border-black shadow-sm">
                    <h3 className="text-xl font-black mb-4">UPLOAD MEDIA</h3>
                    <form onSubmit={handleUploadMedia} className="flex flex-col gap-4">
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <select 
                                required
                                className="p-3 border-2 border-gray-200 focus:border-black outline-none font-medium"
                                value={mediaEventId}
                                onChange={e => setMediaEventId(e.target.value)}
                            >
                                <option value="">Select Completed Event</option>
                                {events.filter(e => e.clubId === user.clubId).map(e => (
                                    <option key={e.id} value={e.id}>{e.title}</option>
                                ))}
                            </select>

                            <ImageUpload 
                                label="Upload Image"
                                onImageSelected={setMediaUrl}
                                currentImage={mediaUrl}
                            />
                        </div>
                        <input 
                            required
                            type="text"
                            placeholder="Add a caption..."
                            className="p-3 border-2 border-gray-200 focus:border-black outline-none font-medium"
                            value={mediaCaption}
                            onChange={e => setMediaCaption(e.target.value)}
                        />
                        <button className="bg-black text-white py-3 font-bold uppercase hover:bg-gray-800 border-2 border-black">
                            Post to Media Feed
                        </button>
                    </form>
                </div>

                <h3 className="text-xl font-black mt-8 mb-4 border-b-2 border-gray-200 pb-2">YOUR POSTS</h3>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                    {mediaList.map(m => (
                        <div key={m.id} className="relative group border-2 border-black">
                            <img 
                                src={m.imageUrl} 
                                onError={(e) => { e.currentTarget.src = "https://via.placeholder.com/800x600/000000/FACC15?text=MEDIA"; }}
                                className="w-full h-48 object-cover" 
                            />
                            <div className="absolute bottom-0 left-0 w-full bg-black/80 text-white p-3 text-xs opacity-0 group-hover:opacity-100 transition-opacity">
                                <p className="font-bold truncate mb-1">{m.caption}</p>
                                <p className="text-gray-400 text-[10px] uppercase truncate">{events.find(e => e.id === m.eventId)?.title}</p>
                                <div className="flex gap-2 mt-2">
                                    <span>❤️ {(m.likedBy || []).length}</span>
                                    <span>💬 {(m.comments || []).length}</span>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {/* Proposal Modal */}
        <Modal
            isOpen={isProposalModalOpen}
            onClose={() => setIsProposalModalOpen(false)}
            title={editingEventId ? "Edit Event Proposal" : "New Event Proposal"}
        >
             <div className="space-y-6">

                {/* AI Assistant */}
                <div className="bg-yellow-50 p-6 border-2 border-yellow-400 border-dashed rounded-lg">
                  <div className="flex items-center gap-2 mb-3">
                    <Sparkles size={20} className="text-black" />
                    <h3 className="text-sm font-black uppercase tracking-wider">AI Content Architect</h3>
                  </div>
                  <div className="flex gap-2">
                    <input 
                      type="text" 
                      placeholder="E.g., A robotics workshop for beginners..."
                      className="flex-1 p-3 border-2 border-black text-sm font-medium focus:outline-none focus:ring-2 focus:ring-yellow-400"
                      value={proposalTopic}
                      onChange={(e) => setProposalTopic(e.target.value)}
                    />
                    <button 
                      onClick={handleAiGenerate}
                      disabled={isGenerating}
                      className="bg-black text-white px-6 py-2 text-xs font-bold uppercase hover:bg-gray-800 disabled:opacity-50 min-w-[120px] flex items-center justify-center border-2 border-black"
                    >
                      {isGenerating ? <Loader2 className="animate-spin text-yellow-400" size={16} /> : 'Generate'}
                    </button>
                  </div>
                </div>

                <form onSubmit={handleSubmitProposal} className="space-y-5">
                  <div>
                    <label className="block text-xs font-bold uppercase text-gray-500 mb-2">Event Title</label>
                    <input 
                      required
                      type="text" 
                      className="w-full p-4 border-2 border-gray-200 focus:border-black focus:outline-none transition-colors font-bold text-lg"
                      value={newProposal.title}
                      onChange={e => setNewProposal({...newProposal, title: e.target.value})}
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold uppercase text-gray-500 mb-2">Description</label>
                    <textarea 
                      required
                      rows={4}
                      className="w-full p-4 border-2 border-gray-200 focus:border-black focus:outline-none transition-colors font-medium"
                      value={newProposal.description || generatedDesc}
                      onChange={e => setNewProposal({...newProposal, description: e.target.value})}
                    />
                  </div>

                  {/* Image Upload */}
                  <ImageUpload 
                        label="Cover Image"
                        onImageSelected={(base64) => setNewProposal({...newProposal, image: base64})}
                        currentImage={newProposal.image}
                  />

                  <div className="grid grid-cols-2 gap-6">
                    <div>
                      <label className="block text-xs font-bold uppercase text-gray-500 mb-2">Date</label>
                      <input 
                        required
                        type="date" 
                        className="w-full p-3 border-2 border-gray-200 focus:border-black focus:outline-none font-medium"
                        value={newProposal.date}
                        onChange={e => setNewProposal({...newProposal, date: e.target.value})}
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-bold uppercase text-gray-500 mb-2">Time</label>
                      <input 
                        required
                        type="time" 
                        className="w-full p-3 border-2 border-gray-200 focus:border-black focus:outline-none font-medium"
                        value={newProposal.time}
                        onChange={e => setNewProposal({...newProposal, time: e.target.value})}
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-6">
                     <div>
                      <label className="block text-xs font-bold uppercase text-gray-500 mb-2">Venue Preference</label>
                      <select 
                        className="w-full p-3 border-2 border-gray-200 focus:border-black focus:outline-none bg-white font-medium"
                        value={newProposal.venueId}
                        onChange={e => setNewProposal({...newProposal, venueId: e.target.value})}
                      >
                        <option value="">Select Venue</option>
                        {venues.map(v => (
                          <option key={v.id} value={v.id}>{v.name} (Cap: {v.capacity})</option>
                        ))}
                      </select>
                    </div>
                    <div>
                      <label className="block text-xs font-bold uppercase text-gray-500 mb-2">Ticket Price (₹)</label>
                      <input 
                        type="number" 
                        className="w-full p-3 border-2 border-gray-200 focus:border-black focus:outline-none font-medium"
                        placeholder="0 for Free"
                        value={newProposal.price}
                        onChange={e => setNewProposal({...newProposal, price: Number(e.target.value)})}
                      />
                    </div>
                  </div>

                  {/* Volunteers Checkbox */}
                  <div className="flex items-center gap-3 p-4 bg-gray-50 border-2 border-gray-200">
                      <input 
                        type="checkbox"
                        id="volunteers"
                        className="w-5 h-5 text-yellow-400 focus:ring-black border-gray-300 rounded"
                        checked={newProposal.volunteersNeeded}
                        onChange={e => setNewProposal({...newProposal, volunteersNeeded: e.target.checked})}
                      />
                      <label htmlFor="volunteers" className="font-bold text-sm cursor-pointer select-none">Volunteers Needed for this Event</label>
                  </div>

                  <button type="submit" className="w-full bg-yellow-400 text-black py-4 font-black uppercase tracking-widest hover:bg-yellow-500 transition-all mt-6 border-2 border-black shadow-[4px_4px_0px_#000] active:shadow-none active:translate-x-[2px] active:translate-y-[2px]">
                    {editingEventId ? "Update & Re-Submit" : "Submit Proposal"}
                  </button>
                </form>
             </div>
        </Modal>

        {/* Poster Generator Modal */}
        <Modal 
            isOpen={!!posterEvent} 
            onClose={() => { setPosterEvent(null); setGeneratedPoster(false); }}
            title="Winners Poster"
            large
        >
            {!generatedPoster ? (
                <div className="space-y-6">
                     <p className="font-medium text-gray-600">Upload details of the top 3 winners to generate a celebratory poster.</p>
                     {[0, 1, 2].map(idx => (
                         <div key={idx} className="flex gap-4 p-4 border border-gray-200 bg-gray-50 items-end">
                             <div className="w-12 h-12 flex items-center justify-center bg-black text-white font-black text-xl rounded-full">
                                 {idx + 1}
                             </div>
                             <div className="flex-1">
                                 <label className="block text-xs font-bold uppercase text-gray-500 mb-1">Name</label>
                                 <input 
                                    className="w-full p-2 border border-gray-300"
                                    value={winners[idx].name}
                                    onChange={e => {
                                        const newWinners = [...winners];
                                        newWinners[idx].name = e.target.value;
                                        setWinners(newWinners);
                                    }}
                                 />
                             </div>
                             <div>
                                 <ImageUpload 
                                    label="Photo"
                                    onImageSelected={(b64) => {
                                        const newWinners = [...winners];
                                        newWinners[idx].photo = b64;
                                        setWinners(newWinners);
                                    }}
                                    currentImage={winners[idx].photo}
                                 />
                             </div>
                         </div>
                     ))}
                     <button onClick={handleGeneratePoster} className="w-full bg-black text-yellow-400 py-4 font-black uppercase text-xl hover:bg-gray-900">
                         Generate Poster
                     </button>
                </div>
            ) : (
                <div className="text-center">
                    <div className="bg-black p-8 text-white relative overflow-hidden" id="poster-area">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-yellow-400 rounded-bl-full"></div>
                        <h2 className="text-sm font-bold uppercase tracking-widest text-yellow-400 mb-2">{posterEvent?.title}</h2>
                        <h1 className="text-5xl font-black mb-12">CONGRATULATIONS</h1>

                        <div className="flex justify-center items-end gap-4 mb-8">
                             {/* 2nd Place */}
                             <div className="flex flex-col items-center">
                                 <div className="w-24 h-24 rounded-full border-4 border-gray-400 overflow-hidden mb-2">
                                     <img src={winners[1].photo || "https://via.placeholder.com/100"} className="w-full h-full object-cover"/>
                                 </div>
                                 <div className="bg-gray-400 text-black px-3 py-1 font-bold text-xs uppercase mb-1">2nd Place</div>
                                 <p className="font-bold">{winners[1].name}</p>
                             </div>
                             {/* 1st Place */}
                             <div className="flex flex-col items-center -translate-y-6">
                                 <div className="w-32 h-32 rounded-full border-4 border-yellow-400 overflow-hidden mb-2 shadow-[0_0_20px_rgba(250,204,21,0.5)]">
                                     <img src={winners[0].photo || "https://via.placeholder.com/100"} className="w-full h-full object-cover"/>
                                 </div>
                                 <div className="bg-yellow-400 text-black px-4 py-1.5 font-bold text-sm uppercase mb-1">Winner</div>
                                 <p className="font-bold text-xl">{winners[0].name}</p>
                             </div>
                              {/* 3rd Place */}
                              <div className="flex flex-col items-center">
                                 <div className="w-24 h-24 rounded-full border-4 border-orange-700 overflow-hidden mb-2">
                                     <img src={winners[2].photo || "https://via.placeholder.com/100"} className="w-full h-full object-cover"/>
                                 </div>
                                 <div className="bg-orange-700 text-white px-3 py-1 font-bold text-xs uppercase mb-1">3rd Place</div>
                                 <p className="font-bold">{winners[2].name}</p>
                             </div>
                        </div>
                        <p className="text-gray-500 font-bold text-sm uppercase tracking-widest">Organized by {posterEvent?.organizer}</p>
                    </div>
                    <div className="mt-6 flex justify-center gap-4">
                        <button onClick={() => setGeneratedPoster(false)} className="px-4 py-2 border-2 border-black font-bold uppercase hover:bg-gray-100">Edit</button>
                        <button onClick={() => alert("Poster Saved/Downloaded!")} className="bg-black text-white px-6 py-2 font-bold uppercase hover:bg-gray-800">Download</button>
                    </div>
                </div>
            )}
        </Modal>

        {/* Event Management Modal */}
        <EventManagementModal 
            isOpen={!!manageEvent}
            onClose={() => setManageEvent(null)}
            event={manageEvent}
            volunteers={manageVolunteers}
            registeredUsers={manageRegisteredUsers}
            onUpdateVolunteerStatus={handleUpdateVolunteer}
        />
      </div>
    );
};

const App = () => {
    const [user, setUser] = useState<User | null>(null);
    const [activeTab, setActiveTab] = useState('feed');
    const [loading, setLoading] = useState(false);
    const [authMode, setAuthMode] = useState<'login' | 'signup'>('login');

    // Auth Form State
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [name, setName] = useState('');

    // Data State
    const [events, setEvents] = useState<Event[]>([]);
    const [clubs, setClubs] = useState<Club[]>([]);
    const [volunteerApps, setVolunteerApps] = useState<VolunteerApplication[]>([]);

    // View State
    const [selectedClub, setSelectedClub] = useState<Club | null>(null);
    const [searchQuery, setSearchQuery] = useState('');

    // Modal State
    const [showPayment, setShowPayment] = useState(false);
    const [selectedEvent, setSelectedEvent] = useState<Event | null>(null);
    const [showProfileEdit, setShowProfileEdit] = useState(false);

    useEffect(() => {
        if(user) {
            refreshData();
        }
    }, [user]);

    const refreshData = async () => {
        if(!user) return;
        try {
            const [allEvents, allClubs, userVols] = await Promise.all([
                api.events.list(),
                api.clubs.list(),
                api.volunteers.listByUser(user.id)
            ]);
            setEvents(allEvents);
            setClubs(allClubs);
            setVolunteerApps(userVols);
        } catch (error) {
            console.error(error);
        }
    };

    const handleLogin = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        try {
            const u = await api.auth.login(email, password);
            setUser(u);
            setActiveTab(u.role === UserRole.STUDENT ? 'feed' : (u.role === UserRole.CLUB_ADMIN ? 'dashboard' : 'approvals'));
        } catch (error: any) {
            alert(error.message);
        } finally {
            setLoading(false);
        }
    };

    const handleSignup = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        try {
            const newUser: User = {
                id: `u${Date.now()}`,
                name: name,
                email: email,
                role: UserRole.STUDENT,
                joinDate: new Date().toISOString(),
                joinedClubIds: []
            };
            await api.auth.signup({ ...newUser, password } as any);
            setUser(newUser);
            setActiveTab('feed');
        } catch (error: any) {
            alert(error.message);
        } finally {
            setLoading(false);
        }
    };

    const handleLogout = () => {
        setUser(null);
        setEmail('');
        setPassword('');
    };

    const handleRegister = (event: Event) => {
        setSelectedEvent(event);
        if(event.price > 0) {
            setShowPayment(true);
        } else {
            confirmRegistration(event);
        }
    };

    const confirmRegistration = async (event: Event) => {
        try {
            await api.events.register(event.id, user!.id);
            alert("Registration successful!");
            setShowPayment(false);
            refreshData();
        } catch (e: any) {
            alert(e.message);
        }
    };

    const handleVolunteerApply = async (eventId: string) => {
        try {
            await api.volunteers.apply({
                id: `v${Date.now()}`,
                eventId,
                userId: user!.id,
                userName: user!.name,
                userAvatar: user!.avatar,
                status: VolunteerStatus.PENDING,
                appliedAt: new Date().toISOString()
            });
            alert("Volunteer application submitted!");
            refreshData();
        } catch (e: any) {
            alert(e.message);
        }
    };

    if (!user) {
        return (
            <div className="min-h-screen bg-yellow-400 flex items-center justify-center p-4">
                <div className="bg-white p-8 border-4 border-black shadow-[8px_8px_0px_#000] max-w-md w-full animate-in zoom-in-95 duration-300">
                    <div className="text-center mb-8">
                        <h1 className="text-5xl font-black tracking-tighter mb-2">CLIX<span className="text-yellow-400">.</span></h1>
                        <p className="text-xs font-bold uppercase tracking-[0.3em] text-gray-400">Campus Life Experience</p>
                    </div>

                    <div className="flex border-b-2 border-gray-100 mb-6">
                        <button 
                            className={`flex-1 pb-3 text-xs font-bold uppercase tracking-widest ${authMode === 'login' ? 'border-b-4 border-yellow-400 text-black' : 'text-gray-400'}`}
                            onClick={() => setAuthMode('login')}
                        >
                            Login
                        </button>
                        <button 
                            className={`flex-1 pb-3 text-xs font-bold uppercase tracking-widest ${authMode === 'signup' ? 'border-b-4 border-yellow-400 text-black' : 'text-gray-400'}`}
                            onClick={() => setAuthMode('signup')}
                        >
                            Sign Up
                        </button>
                    </div>

                    <form onSubmit={authMode === 'login' ? handleLogin : handleSignup} className="space-y-4">
                        {authMode === 'signup' && (
                            <div>
                                <label className="block text-[10px] font-bold uppercase text-gray-400 mb-1">Full Name</label>
                                <input 
                                    className="w-full p-3 border-2 border-gray-200 focus:border-black focus:outline-none font-bold"
                                    value={name}
                                    onChange={e => setName(e.target.value)}
                                    required
                                />
                            </div>
                        )}
                        <div>
                            <label className="block text-[10px] font-bold uppercase text-gray-400 mb-1">Email Address</label>
                            <input 
                                type="email"
                                className="w-full p-3 border-2 border-gray-200 focus:border-black focus:outline-none font-bold"
                                value={email}
                                onChange={e => setEmail(e.target.value)}
                                required
                            />
                        </div>
                        <div>
                            <label className="block text-[10px] font-bold uppercase text-gray-400 mb-1">Password</label>
                            <input 
                                type="password"
                                className="w-full p-3 border-2 border-gray-200 focus:border-black focus:outline-none font-bold"
                                value={password}
                                onChange={e => setPassword(e.target.value)}
                                required
                            />
                        </div>

                        <button 
                            type="submit" 
                            disabled={loading}
                            className="w-full bg-black text-white py-4 font-black uppercase tracking-widest hover:bg-gray-800 transition-colors disabled:opacity-50 mt-4"
                        >
                            {loading ? <Loader2 className="animate-spin mx-auto" /> : (authMode === 'login' ? 'Enter Campus' : 'Create Account')}
                        </button>
                    </form>

                    <div className="mt-8 pt-6 border-t-2 border-dashed border-gray-200">
                        <p className="text-[10px] text-gray-400 font-bold uppercase text-center mb-3">Quick Access (Demo)</p>
                        <div className="flex gap-2 justify-center">
                            <button onClick={() => api.auth.loginAsRole(UserRole.STUDENT).then(u => {setUser(u); setActiveTab('feed');})} className="bg-gray-100 hover:bg-yellow-400 border border-gray-200 hover:border-black text-[10px] font-bold uppercase px-3 py-1 transition-colors">Student</button>
                            <button onClick={() => api.auth.loginAsRole(UserRole.CLUB_ADMIN).then(u => {setUser(u); setActiveTab('dashboard');})} className="bg-gray-100 hover:bg-yellow-400 border border-gray-200 hover:border-black text-[10px] font-bold uppercase px-3 py-1 transition-colors">Club Admin</button>
                            <button onClick={() => api.auth.loginAsRole(UserRole.COLLEGE_ADMIN).then(u => {setUser(u); setActiveTab('approvals');})} className="bg-gray-100 hover:bg-yellow-400 border border-gray-200 hover:border-black text-[10px] font-bold uppercase px-3 py-1 transition-colors">Admin</button>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    const renderContent = () => {
        if (user.role === UserRole.CLUB_ADMIN) {
            return <ClubAdminDashboard user={user} refreshData={refreshData} activeTab={activeTab} />;
        }

        if (user.role === UserRole.COLLEGE_ADMIN) {
            if (activeTab === 'approvals') {
                const pendingEvents = events.filter(e => e.status === EventStatus.PENDING);
                return (
                    <div className="space-y-6 animate-in fade-in">
                        <h2 className="text-2xl font-black uppercase tracking-tight mb-6">Pending Approvals</h2>
                        {pendingEvents.length === 0 ? (
                            <div className="text-center py-10 bg-white border-2 border-dashed border-gray-300">
                                <p className="text-gray-400 font-bold">No pending events to review.</p>
                            </div>
                        ) : (
                            <div className="grid gap-6">
                                {pendingEvents.map(event => (
                                    <EventCard 
                                        key={event.id}
                                        event={event}
                                        isAdminView={true}
                                        onApprove={async (id) => {
                                            await api.events.updateStatus(id, EventStatus.APPROVED);
                                            refreshData();
                                        }}
                                        onReject={async (id, reason) => {
                                            await api.events.updateStatus(id, EventStatus.REJECTED, reason);
                                            refreshData();
                                        }}
                                    />
                                ))}
                            </div>
                        )}
                    </div>
                );
            }
            if (activeTab === 'clubs_manage') return <div className="p-10 text-center text-gray-500 font-bold">Club Management Module</div>;
            if (activeTab === 'reports') return <div className="p-10 text-center text-gray-500 font-bold">Analytics & Reports Module</div>;
        }

        if (user.role === UserRole.STUDENT) {
            if (selectedClub) {
                return <StudentClubDetail club={selectedClub} onBack={() => setSelectedClub(null)} user={user} onUpdateUser={setUser} />;
            }

            switch (activeTab) {
                case 'feed':
                    const filteredEvents = events.filter(e => {
                        const matchesSearch = e.title.toLowerCase().includes(searchQuery.toLowerCase()) || e.tags.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()));
                        return (e.status === EventStatus.APPROVED || e.status === EventStatus.COMPLETED) && matchesSearch;
                    });

                    return (
                        <div className="space-y-6 animate-in fade-in">
                            <div className="relative">
                                <input 
                                    className="w-full p-4 pl-12 border-2 border-black font-bold focus:outline-none focus:ring-4 focus:ring-yellow-400 shadow-[4px_4px_0px_#000]"
                                    placeholder="Search for events..."
                                    value={searchQuery}
                                    onChange={e => setSearchQuery(e.target.value)}
                                />
                                <Search className="absolute left-4 top-4 text-gray-400" />
                            </div>

                            <div className="space-y-8">
                                {filteredEvents.map(event => {
                                    const volunteerStatus = volunteerApps.find(v => v.eventId === event.id)?.status;

                                    return (
                                        <EventCard 
                                            key={event.id}
                                            event={event}
                                            venueName={event.venueId} 
                                            onRegister={handleRegister}
                                            onVolunteer={handleVolunteerApply}
                                            volunteerStatus={volunteerStatus}
                                            onClick={() => setSelectedEvent(event)}
                                        />
                                    );
                                })}
                            </div>
                        </div>
                    );
                case 'media':
                    return <StudentMediaView user={user} />;
                case 'clubs':
                    return (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-in fade-in">
                            {clubs.map(club => (
                                <div 
                                    key={club.id} 
                                    onClick={() => setSelectedClub(club)}
                                    className="bg-white border-2 border-black p-4 cursor-pointer hover:bg-yellow-50 transition-colors flex items-center gap-4 group"
                                >
                                    <img src={club.logo} className="w-16 h-16 border-2 border-black object-cover bg-gray-100 group-hover:scale-105 transition-transform" />
                                    <div className="flex-1">
                                        <h3 className="font-black text-lg uppercase leading-none mb-1">{club.name}</h3>
                                        <p className="text-xs text-gray-500 font-bold">{club.memberCount} Members</p>
                                    </div>
                                    <ArrowRight className="text-gray-300 group-hover:text-black transition-colors" />
                                </div>
                            ))}
                        </div>
                    );
                case 'tickets':
                     return (
                         <div className="p-10 text-center border-2 border-dashed border-gray-300">
                             <Ticket size={48} className="mx-auto text-gray-300 mb-2" />
                             <p className="font-bold text-gray-400">Your registered tickets will appear here.</p>
                         </div>
                     );
            }
        }

        if (activeTab === 'profile') {
             return (
                 <div className="bg-white border-2 border-black p-8 text-center animate-in zoom-in-95 max-w-md mx-auto">
                     <div className="relative inline-block mb-6">
                         <div className="w-32 h-32 rounded-full border-4 border-black overflow-hidden mx-auto bg-gray-100">
                              <img src={user.avatar || `https://api.dicebear.com/7.x/initials/svg?seed=${user.name}`} className="w-full h-full object-cover" />
                         </div>
                         <button onClick={() => setShowProfileEdit(true)} className="absolute bottom-0 right-0 bg-yellow-400 p-2 border-2 border-black hover:bg-yellow-500 transition-colors shadow-[2px_2px_0px_#000]">
                             <Edit size={16} />
                         </button>
                     </div>

                     <h2 className="text-3xl font-black uppercase mb-1">{user.name}</h2>
                     <p className="text-gray-500 font-bold text-sm uppercase tracking-widest mb-6">{user.role.replace('_', ' ')}</p>

                     {user.bio && <p className="text-gray-600 font-medium italic mb-6 px-4">"{user.bio}"</p>}

                     <div className="flex justify-center gap-8 border-t-2 border-gray-100 pt-6 mb-8">
                         <div className="text-center">
                             <p className="text-2xl font-black">{user.joinedClubIds?.length || 0}</p>
                             <p className="text-[10px] font-bold uppercase text-gray-400">Clubs</p>
                         </div>
                         {user.role === UserRole.STUDENT && (
                             <div className="text-center">
                                 <p className="text-2xl font-black">{volunteerApps.length}</p>
                                 <p className="text-[10px] font-bold uppercase text-gray-400">Volunteering</p>
                             </div>
                         )}
                     </div>

                     <button 
                        onClick={handleLogout}
                        className="w-full bg-white border-2 border-red-500 text-red-500 font-bold uppercase py-3 hover:bg-red-50 transition-colors flex items-center justify-center gap-2"
                     >
                         <LogOut size={18} /> Logout
                     </button>
                 </div>
             );
        }

        return null;
    };

    return (
        <Layout user={user} onLogout={handleLogout} activeTab={activeTab} setActiveTab={setActiveTab}>
            {renderContent()}

            <PaymentModal 
                isOpen={showPayment}
                onClose={() => setShowPayment(false)}
                event={selectedEvent}
                onConfirm={() => selectedEvent && confirmRegistration(selectedEvent)}
            />

            <EditProfileModal 
                isOpen={showProfileEdit}
                onClose={() => setShowProfileEdit(false)}
                user={user}
                onUpdate={async (data) => {
                    const updated = { ...user, ...data };
                    setUser(updated);
                }}
            />
        </Layout>
    );
};

export default App;

import { User, Event, Club, Post, Venue, UserRole, VolunteerApplication, VolunteerStatus, Announcement, MediaPost, Feedback, Comment, Winner } from '../types';
import { supabase } from './supabaseClient';

// Helper to map DB response to types if needed (Supabase returns null for missing JSONB, we might need [] default)
const handleResponse = async <T>(promise: Promise<any>): Promise<T> => {
    const { data, error } = await promise;
    if (error) {
        console.error("Supabase Error:", error);
        throw new Error(error.message);
    }
    return data as T;
};

export const api = {
  auth: {
    login: async (email: string, password: string): Promise<User> => {
      // In a real app, use supabase.auth.signInWithPassword
      // For this migration keeping existing logic structure: query users table
      const { data, error } = await supabase
        .from('users')
        .select('*')
        .eq('email', email)
        .single();

      if (error || !data) throw new Error('Invalid credentials');
      // Simple password check (plaintext for this demo as requested in prompt feature list)
      if (data.password !== password) throw new Error('Invalid credentials');

      return data as User;
    },
    signup: async (user: User): Promise<User> => {
      const { error } = await supabase.from('users').insert(user);
      if (error) throw new Error(error.message);
      return user;
    },
    loginAsRole: async (role: UserRole): Promise<User> => {
      // Demo helper to switch roles - fetch first user of that role
      const { data, error } = await supabase
        .from('users')
        .select('*')
        .eq('role', role)
        .limit(1)
        .single();

      if (error || !data) throw new Error(`No user found with role ${role}`);
      return data as User;
    },
    updateProfile: async (user: User): Promise<User> => {
        const { error } = await supabase
            .from('users')
            .update(user)
            .eq('id', user.id);
        if (error) throw new Error(error.message);
        return user;
    },
    getRegistrations: async (userId: string): Promise<string[]> => {
        const { data, error } = await supabase
            .from('registrations')
            .select('eventId')
            .eq('userId', userId);
        if (error) return [];
        return data.map((r: any) => r.eventId);
    }
  },
  events: {
    list: async (clubId?: string): Promise<Event[]> => {
      let query = supabase.from('events').select('*');
      if (clubId) {
          query = query.eq('clubId', clubId);
      }
      const { data, error } = await query;
      if (error) throw new Error(error.message);
      return data || [];
    },
    create: async (event: Event): Promise<Event> => {
      const { error } = await supabase.from('events').insert(event);
      if (error) throw new Error(error.message);
      return event;
    },
    update: async (event: Event): Promise<Event> => {
        const { error } = await supabase
            .from('events')
            .update(event)
            .eq('id', event.id);
        if (error) throw new Error(error.message);
        return event;
    },
    updateStatus: async (eventId: string, status: any, reason?: string): Promise<Event> => {
       const updateData: any = { status };
       if (reason) updateData.rejectionReason = reason;
       if (status === 'PENDING') updateData.rejectionReason = null; // Clear reason

       const { data, error } = await supabase
         .from('events')
         .update(updateData)
         .eq('id', eventId)
         .select()
         .single();

       if (error) throw new Error(error.message);
       return data;
    },
    register: async (eventId: string, userId: string): Promise<void> => {
        // 1. Add to registrations table
        const { error: regError } = await supabase
            .from('registrations')
            .insert({ eventId, userId });

        if (regError) {
            // Ignore duplicate key error if user clicks twice quickly
            if (regError.code !== '23505') throw new Error(regError.message);
        }

        // 2. Increment count (Atomic increment is better, but simple update for now)
        // Fetch current count first (safe enough for this scale)
        const { data: event } = await supabase.from('events').select('registeredCount').eq('id', eventId).single();
        if (event) {
             await supabase.from('events').update({ registeredCount: (event.registeredCount || 0) + 1 }).eq('id', eventId);
        }
    },
    getRegisteredUsers: async (eventId: string): Promise<User[]> => {
        // 1. Get user IDs from registrations table
        const { data: regs, error: regError } = await supabase
            .from('registrations')
            .select('userId')
            .eq('eventId', eventId);

        if (regError) throw new Error(regError.message);
        if (!regs || regs.length === 0) return [];

        const userIds = regs.map((r: any) => r.userId);

        // 2. Fetch User details
        const { data: users, error: userError } = await supabase
            .from('users')
            .select('*')
            .in('id', userIds);

        if (userError) throw new Error(userError.message);
        return users || [];
    },
    addFeedback: async (eventId: string, feedback: Feedback): Promise<void> => {
        const { data: event } = await supabase.from('events').select('feedback').eq('id', eventId).single();
        const currentFeedback = event?.feedback || [];

        await supabase
            .from('events')
            .update({ feedback: [...currentFeedback, feedback] })
            .eq('id', eventId);
    },
    issueCertificates: async (eventId: string): Promise<void> => {
        await supabase.from('events').update({ certificatesIssued: true }).eq('id', eventId);
    },
    saveWinners: async (eventId: string, winners: Winner[]): Promise<void> => {
        await supabase.from('events').update({ winners }).eq('id', eventId);
    }
  },
  clubs: {
    list: async (): Promise<Club[]> => {
      const { data, error } = await supabase.from('clubs').select('*');
      if (error) return [];
      return data;
    },
    join: async (clubId: string, userId: string): Promise<User> => {
        // Fetch User
        const { data: user } = await supabase.from('users').select('*').eq('id', userId).single();
        if (!user) throw new Error("User not found");

        const joinedClubIds = user.joinedClubIds || [];
        if (!joinedClubIds.includes(clubId)) {
            const newJoined = [...joinedClubIds, clubId];

            // Update User
            await supabase.from('users').update({ joinedClubIds: newJoined }).eq('id', userId);

            // Update Club Count
            const { data: club } = await supabase.from('clubs').select('memberCount').eq('id', clubId).single();
            if (club) {
                await supabase.from('clubs').update({ memberCount: (club.memberCount || 0) + 1 }).eq('id', clubId);
            }

            return { ...user, joinedClubIds: newJoined };
        }
        return user;
    },
    leave: async (clubId: string, userId: string): Promise<User> => {
        const { data: user } = await supabase.from('users').select('*').eq('id', userId).single();
        if (!user) throw new Error("User not found");

        const joinedClubIds = user.joinedClubIds || [];
        const newJoined = joinedClubIds.filter((id: string) => id !== clubId);

        await supabase.from('users').update({ joinedClubIds: newJoined }).eq('id', userId);

        const { data: club } = await supabase.from('clubs').select('memberCount').eq('id', clubId).single();
        if (club) {
            await supabase.from('clubs').update({ memberCount: Math.max(0, (club.memberCount || 0) - 1) }).eq('id', clubId);
        }

        return { ...user, joinedClubIds: newJoined };
    }
  },
  posts: {
    list: async (clubId: string): Promise<Post[]> => {
      const { data, error } = await supabase
        .from('posts')
        .select('*')
        .eq('clubId', clubId)
        .order('timestamp', { ascending: false });

      if (error) return [];
      return data || [];
    },
    create: async (post: Post): Promise<Post> => {
      const { error } = await supabase.from('posts').insert(post);
      if (error) throw new Error(error.message);
      return post;
    },
    like: async (postId: string, userId: string): Promise<void> => {
        const { data: post } = await supabase.from('posts').select('likedBy').eq('id', postId).single();
        if (post) {
            const likedBy = post.likedBy || [];
            const newLikedBy = likedBy.includes(userId) 
                ? likedBy.filter((id: string) => id !== userId)
                : [...likedBy, userId];

            await supabase.from('posts').update({ likedBy: newLikedBy }).eq('id', postId);
        }
    },
    comment: async (postId: string, comment: Comment): Promise<void> => {
        const { data: post } = await supabase.from('posts').select('comments').eq('id', postId).single();
        if (post) {
            const comments = post.comments || [];
            await supabase.from('posts').update({ comments: [...comments, comment] }).eq('id', postId);
        }
    }
  },
  venues: {
      list: async (): Promise<Venue[]> => {
          const { data } = await supabase.from('venues').select('*');
          return data || [];
      }
  },
  volunteers: {
    apply: async (application: VolunteerApplication): Promise<VolunteerApplication> => {
        // Check duplicate
        const { data } = await supabase.from('volunteers')
            .select('*')
            .eq('eventId', application.eventId)
            .eq('userId', application.userId);

        if (data && data.length > 0) throw new Error("Already applied");

        const { error } = await supabase.from('volunteers').insert(application);
        if (error) throw new Error(error.message);
        return application;
    },
    listByEvent: async (eventId: string): Promise<VolunteerApplication[]> => {
        const { data } = await supabase.from('volunteers').select('*').eq('eventId', eventId);
        return data || [];
    },
    listByUser: async (userId: string): Promise<VolunteerApplication[]> => {
        const { data } = await supabase.from('volunteers').select('*').eq('userId', userId);
        return data || [];
    },
    updateStatus: async (appId: string, status: VolunteerStatus): Promise<void> => {
        await supabase.from('volunteers').update({ status }).eq('id', appId);
    }
  },
  announcements: {
      list: async (clubId: string): Promise<Announcement[]> => {
          const { data } = await supabase.from('announcements')
            .select('*')
            .eq('clubId', clubId)
            .order('date', { ascending: false });
          return data || [];
      },
      create: async (announcement: Announcement): Promise<Announcement> => {
          await supabase.from('announcements').insert(announcement);
          return announcement;
      }
  },
  media: {
      list: async (clubId?: string): Promise<MediaPost[]> => {
          let query = supabase.from('media').select('*');
          if (clubId) {
              query = query.eq('clubId', clubId);
          }
          const { data } = await query;
          return data || [];
      },
      create: async (media: MediaPost): Promise<MediaPost> => {
          await supabase.from('media').insert(media);
          return media;
      },
      like: async (mediaId: string, userId: string): Promise<void> => {
          const { data: m } = await supabase.from('media').select('likedBy').eq('id', mediaId).single();
          if (m) {
              const likedBy = m.likedBy || [];
              const newLikedBy = likedBy.includes(userId) 
                  ? likedBy.filter((id: string) => id !== userId)
                  : [...likedBy, userId];

              await supabase.from('media').update({ likedBy: newLikedBy }).eq('id', mediaId);
          }
      },
      comment: async (mediaId: string, comment: Comment): Promise<void> => {
          const { data: m } = await supabase.from('media').select('comments').eq('id', mediaId).single();
          if (m) {
              const comments = m.comments || [];
              await supabase.from('media').update({ comments: [...comments, comment] }).eq('id', mediaId);
          }
      }
  }
};

