const EventCard = ({ 
  event, 
  isAdminView = false, 
  isRegistered = false, 
  onRegister, 
  onApprove, 
  onReject, 
  venueName,
  onVolunteer,
  volunteerStatus,
  onGeneratePoster,
  onIssueCertificates,
  onEdit,
  onClick
