const App = () => {
  const [user, setUser] = useState<User | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [authView, setAuthView] = useState<'login' | 'signup'>('login');

  const [activeTab, setActiveTab] = useState('feed');
  const [events, setEvents] = useState<Event[]>([]);
  const [clubs, setClubs] = useState<Club[]>([]);
  const [venues, setVenues] = useState<Venue[]>([]);
  const [userRegistrations, setUserRegistrations] = useState<string[]>([]);
  const [volunteerApps, setVolunteerApps] = useState<VolunteerApplication[]>([]);

  // Search state
  const [searchQuery, setSearchQuery] = useState('');
  const [filterPrice, setFilterPrice] = useState<'all' | 'free' | 'paid'>('all');

  // Modals
  const [selectedEvent, setSelectedEvent] = useState<Event | null>(null);
  const [paymentOpen, setPaymentOpen] = useState(false);
  const [qrOpen, setQrOpen] = useState(false);
  const [certOpen, setCertOpen] = useState(false);

  // Edit Profile
  const [isEditProfileOpen, setIsEditProfileOpen] = useState(false);
  // Feedback
  const [feedbackEvent, setFeedbackEvent] = useState<Event | null>(null);

  // Club Details
  const [selectedClub, setSelectedClub] = useState<Club | null>(null);

  useEffect(() => {
    if(isAuthenticated) fetchData();
  }, [user, isAuthenticated]);

  const fetchData = async () => {
    if (!user) return;
    try {
        const e = await api.events.list();
        setEvents(e);
        const c = await api.clubs.list();
        setClubs(c);
        const v = await api.venues.list();
        setVenues(v);
        if (api.auth.getRegistrations) {
            const regs = await api.auth.getRegistrations(user.id);
            setUserRegistrations(regs);
        }
        const vApps = await api.volunteers.listByUser(user.id);
        setVolunteerApps(vApps);
    } catch (err) {
        console.error("Failed to fetch data", err);
    }
  };

  const handleLogin = (u: User) => {
      setUser(u);
      setIsAuthenticated(true);
      if (u.role === UserRole.STUDENT) setActiveTab('feed');
      else if (u.role === UserRole.CLUB_ADMIN) setActiveTab('dashboard');
      else if (u.role === UserRole.COLLEGE_ADMIN) setActiveTab('approvals');
  };

  const handleLogout = () => {
      setIsAuthenticated(false);
      setUser(null);
      setAuthView('login');
  };

  const handleRegister = async (event: Event) => {
      if(!user) return;
      if (event.price > 0) {
          setSelectedEvent(event);
          setPaymentOpen(true);
      } else {
          await confirmRegistration(event);
      }
  };

  const confirmRegistration = async (event: Event) => {
      if(!user) return;
      await api.events.register(event.id, user.id);
      setUserRegistrations(prev => [...prev, event.id]);
      setEvents(prev => prev.map(e => e.id === event.id ? {...e, registeredCount: e.registeredCount + 1} : e));
      if (paymentOpen) setPaymentOpen(false);
  };

  const handleVolunteerApply = async (eventId: string) => {
      if(!user) return;
      try {
          const app: VolunteerApplication = {
              id: `v${Date.now()}`,
              eventId,
              userId: user.id,
              userName: user.name,
              userAvatar: user.avatar,
              status: VolunteerStatus.PENDING,
              appliedAt: new Date().toISOString()
          };
          await api.volunteers.apply(app);
          setVolunteerApps(prev => [...prev, app]);
      } catch (e: any) {
          alert(e.message);
      }
  };

  const handleUpdateProfile = async (data: Partial<User>) => {
      if (!user) return;
      const updatedUser = { ...user, ...data };
      await api.auth.updateProfile(updatedUser);
      setUser(updatedUser);
  };

  const handleFeedbackSubmit = async (rating: number, comment: string) => {
      if (!feedbackEvent || !user) return;
      const feedback: Feedback = { userId: user.id, rating, comment };
      await api.events.addFeedback(feedbackEvent.id, feedback);
      // Update local event state to reflect new feedback without full refetch
      setEvents(events.map(e => e.id === feedbackEvent.id ? {...e, feedback: [...(e.feedback || []), feedback]} : e));
      setFeedbackEvent(null);
  };

  // Auth Views
  if (!isAuthenticated) {
      return authView === 'login' 
        ? <LoginPage onLogin={handleLogin} onSwitchToSignup={() => setAuthView('signup')} />
        : <SignupPage onSignup={(u) => { setUser(u); setIsAuthenticated(true); setActiveTab('feed'); }} onSwitchToLogin={() => setAuthView('login')} />;
  }

  // Filtered Events for Feed
  const filteredEvents = events.filter(e => {
        if (e.status !== EventStatus.APPROVED) return false;
        if (filterPrice === 'free' && e.price > 0) return false;
        if (filterPrice === 'paid' && e.price === 0) return false;
        const query = searchQuery.toLowerCase();
        return (
          e.title.toLowerCase().includes(query) || 
          e.description.toLowerCase().includes(query) ||
          e.tags.some(tag => tag.toLowerCase().includes(query))
        );
  });

  if (!user) return null;

  return (
    <Layout user={user} onLogout={handleLogout} activeTab={activeTab} setActiveTab={setActiveTab}>

      {/* STUDENT VIEW */}
      {user.role === UserRole.STUDENT && (
        <>
           {/* ... Feed View ... */}
           {activeTab === 'feed' && (
               <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                   <div className="flex flex-col gap-4 border-b-4 border-black pb-6">
                      <div className="flex justify-between items-end">
                         <div>
                            <h2 className="text-4xl md:text-5xl font-black tracking-tighter mb-2">WHATS ON<span className="text-yellow-500">?</span></h2>
                            <p className="text-gray-500 font-medium">Discover and join campus activities.</p>
                         </div>
                      </div>
                      <div className="flex flex-col md:flex-row gap-4">
                         <div className="relative flex-1">
                            <input 
                            type="text" 
                            placeholder="Search events, tags..." 
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="pl-10 pr-4 py-3 border-2 border-black focus:outline-none focus:ring-4 focus:ring-yellow-400 w-full font-bold bg-white"
                            />
                            <Search className="absolute left-3 top-3.5 text-black" size={20} />
                         </div>
                         <div className="flex items-center gap-2">
                             <Filter size={20} className="text-gray-500" />
                             <select 
                                className="p-3 border-2 border-black font-bold bg-white focus:outline-none focus:ring-4 focus:ring-yellow-400"
                                value={filterPrice}
                                onChange={(e) => setFilterPrice(e.target.value as any)}
                             >
                                 <option value="all">All Prices</option>
                                 <option value="free">Free Only</option>
                                 <option value="paid">Paid Only</option>
                             </select>
                         </div>
                      </div>
                   </div>

                   <div className="grid gap-6">
                       {filteredEvents.map(event => (
                           <EventCard 
                             key={event.id} 
                             event={event} 
                             isAdminView={false}
                             isRegistered={userRegistrations.includes(event.id)}
                             onRegister={handleRegister}
                             venueName={venues.find(v => v.id === event.venueId)?.name || event.venueId}
                             onVolunteer={handleVolunteerApply}
                             volunteerStatus={volunteerApps.find(v => v.eventId === event.id)?.status}
                           />
                       ))}
                       {filteredEvents.length === 0 && <div className="text-center py-10 text-gray-400">No events found.</div>}
                   </div>
               </div>
           )}
           {activeTab === 'media' && <StudentMediaView user={user} />}
           {activeTab === 'clubs' && (
               selectedClub ? (
                    <StudentClubDetail 
                        club={selectedClub} 
                        onBack={() => setSelectedClub(null)} 
                        user={user} 
                        onUpdateUser={setUser}
                    />
               ) : (
                    <div className="grid grid-cols-1 gap-4 animate-in fade-in duration-300">
                        {clubs.length > 0 ? (
