const EventCard = ({ event, isAdminView, onClick, onRegister, onEdit, onGeneratePoster, onIssueCertificates }: { 
    event: Event, 
    isAdminView?: boolean, 
    onClick?: () => void, 
    onRegister?: () => void, 
    onEdit?: (e: Event) => void,
    onGeneratePoster?: () => void,
    onIssueCertificates?: (e: Event) => void
}) => {
    return (
        <div onClick={onClick} className="bg-white border-2 border-black shadow-[4px_4px_0px_#000] hover:translate-y-[-2px] hover:shadow-[6px_6px_0px_#000] transition-all cursor-pointer group relative overflow-hidden">
            <div className="h-40 overflow-hidden bg-gray-200 border-b-2 border-black relative">
                 <img src={event.image} alt={event.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                 <div className="absolute top-2 right-2 flex gap-1">
                     <StatusBadge status={event.status} />
