                                        <span className="text-xs font-bold text-gray-400">Student</span>
                                    </div>
                                    <p className="text-sm italic text-gray-700">"{fb.comment}"</p>
                                </div>
                            ))
                        ) : (
                            <p className="text-gray-500 text-sm italic">No feedback received yet.</p>
                        )}
                    </div>
                </div>
            </div>
        </Modal>
    );
};

