const LoginPage = ({ onLogin, onSwitchToSignup }: { onLogin: (u: User) => void, onSwitchToSignup: () => void }) => {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        try {
            const u = await api.auth.login(email, password);
            onLogin(u);
        } catch (err) {
            alert('Invalid credentials');
        } finally {
            setLoading(false);
        }
    };

    const handleDemo = async (role: UserRole) => {
         try {
             const u = await api.auth.loginAsRole(role);
             onLogin(u);
         } catch (e) { alert("Demo login failed"); }
    };

    return (
        <div className="min-h-screen bg-yellow-400 flex items-center justify-center p-4">
            <div className="bg-white p-8 border-4 border-black shadow-[8px_8px_0px_#000] max-w-md w-full">
                <h1 className="text-4xl font-black mb-2">CLIX.</h1>
                <p className="font-bold text-gray-500 uppercase tracking-widest mb-8">Your Campus, One Click Away</p>

                <form onSubmit={handleSubmit} className="space-y-4">
                    <div>
                        <label className="block text-xs font-bold uppercase mb-1">Email</label>
                        <input 
                            className="w-full border-2 border-black p-3 font-bold focus:outline-none focus:bg-yellow-50"
                            value={email}
                            onChange={e => setEmail(e.target.value)}
                        />
                    </div>
                    <div>
                        <label className="block text-xs font-bold uppercase mb-1">Password</label>
                        <input 
                            type="password"
                            className="w-full border-2 border-black p-3 font-bold focus:outline-none focus:bg-yellow-50"
                            value={password}
                            onChange={e => setPassword(e.target.value)}
                        />
                    </div>
                    <button disabled={loading} className="w-full bg-black text-white py-4 font-black uppercase hover:bg-gray-800 transition">
                        {loading ? <Loader2 className="animate-spin mx-auto"/> : 'Login'}
                    </button>
                </form>

                <div className="mt-4 text-center">
                    <button onClick={onSwitchToSignup} className="text-sm font-bold underline">Create an account</button>
                </div>

                <div className="mt-8 pt-6 border-t-2 border-dashed border-gray-300">
                    <p className="text-xs font-bold text-center mb-4 text-gray-400">DEMO LOGIN</p>
                    <div className="flex gap-2">
                            <button onClick={() => handleDemo(UserRole.STUDENT)} className="flex-1 text-[10px] font-bold border border-gray-300 p-2 hover:bg-gray-100">Student</button>
                            <button onClick={() => handleDemo(UserRole.CLUB_ADMIN)} className="flex-1 text-[10px] font-bold border border-gray-300 p-2 hover:bg-gray-100">Club Admin</button>
                            <button onClick={() => handleDemo(UserRole.COLLEGE_ADMIN)} className="flex-1 text-[10px] font-bold border border-gray-300 p-2 hover:bg-gray-100">Admin</button>
                    </div>
                </div>
            </div>
        </div>
    );
};

const SignupPage = ({ onSignup, onSwitchToLogin }: { onSignup: (u: User) => void, onSwitchToLogin: () => void }) => {
