const EventCard = ({ event, isAdminView, onClick, onRegister, onEdit, onGeneratePoster, onIssueCertificates, venueName, onVolunteer, volunteerStatus, isRegistered }: { 
    event: Event, 
    isAdminView?: boolean, 
    onClick?: () => void, 
    onRegister?: (e: Event) => void, 
    onEdit?: (e: Event) => void,
    onGeneratePoster?: () => void,
