    const handleGenerateReport = async () => {
        if(!event) return;
        setGeneratingReport(true);
        const reportText = await generateEventReport(
            event.title, 
            { registered: event.registeredCount, capacity: event.capacity, revenue: event.registeredCount * event.price },
            event.feedback || []
